-- HOW TO USE: Supabase → SQL Editor → New query → paste ALL of this → Run.
-- Run it only ONCE, on a new project. Don't edit this file; edit the files in
-- supabase/migrations/ and regenerate it instead.
-- No sample data: use this for the real store.
-- =============================================================================

-- Stop if the store tables already exist, so nothing gets created twice.
do $$
begin
  if to_regclass('public.products') is not null then
    raise exception 'The store database is already set up. Nothing was changed.';
  end if;
end $$;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000001_schema.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — database schema
-- =============================================================================
-- How this file is organized:
--   1. Types (enums)
--   2. Tables
--   3. Helper functions (today in Arizona, is_admin, reserved stock)
--   4. Triggers (keep products.stock in sync with the stock ledger)
--
-- Conventions used everywhere:
--   * Money is stored as whole CENTS in integer columns (price_cents = 150 means
--     $1.50). Decimals cause rounding bugs; integers don't.
--   * Every stock change is a row in `stock_movements`. Never edit
--     products.stock directly — insert a movement and the trigger updates it.
--   * "Today" means today in the store's timezone (America/Phoenix), not UTC.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. Types
-- -----------------------------------------------------------------------------

-- Order life cycle. Open statuses (received, preparing, ready) reserve stock.
create type public.order_status as enum (
  'received',   -- student placed it
  'preparing',  -- staff is bagging it
  'ready',      -- waiting at the pickup spot
  'picked_up',  -- student paid at pickup (stock is subtracted now)
  'canceled',   -- canceled by staff
  'no_show',    -- staff marked it as never collected
  'expired'     -- automatically closed at the end of the pickup day
);

-- Why stock changed. Shown in the inventory history.
create type public.movement_reason as enum (
  'initial',            -- starting stock when a product is created
  'restock',            -- added by a shopping trip (expense)
  'online_pickup',      -- online order picked up and paid
  'online_pickup_undo', -- a picked-up order was moved back to another status
  'sale_import',        -- in-person sales from the InTouchPay import
  'manual_adjustment',  -- staff fixed the count by hand (note required)
  'spoilage'            -- thrown away / expired (note required)
);

create type public.payment_type as enum ('cash', 'debit', 'other');


-- -----------------------------------------------------------------------------
-- 2. Tables
-- -----------------------------------------------------------------------------

-- The one admin account. Being logged in is NOT enough to see staff data:
-- the user's id must also be in this table. That way, even if someone found
-- a way to create a Supabase account, they would see nothing.
create table public.admins (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  created_at timestamptz not null default now()
);

-- Store-wide settings. There is exactly one row (id = 1).
create table public.settings (
  id                         int primary key default 1 check (id = 1),
  store_name                 text not null default 'School Store',
  store_hours                text not null default 'Mon–Fri, before school through 7th hour',
  pickup_location            text not null default 'Store window by the cafeteria',
  banner_text                text,               -- optional announcement on the menu
  timezone                   text not null default 'America/Phoenix',
  -- Ordering rules
  order_cutoff_time          time not null default '14:00', -- no more same-day orders after this
  order_lead_minutes         int  not null default 20 check (order_lead_minutes between 0 and 240),
  max_orders_per_student_day int  not null default 2  check (max_orders_per_student_day between 1 and 20),
  max_items_per_order        int  not null default 10 check (max_items_per_order between 1 and 50),
  max_orders_per_hour_per_device int not null default 5 check (max_orders_per_hour_per_device between 1 and 100),
  -- Privacy
  order_retention_days       int  not null default 90 check (order_retention_days between 7 and 730),
  -- Inventory math (see src/lib/calculations.ts)
  sales_average_days         int  not null default 28 check (sales_average_days between 7 and 180),
  reorder_buffer_days        int  not null default 2  check (reorder_buffer_days between 0 and 30),
  shopping_interval_days     int  not null default 7  check (shopping_interval_days between 1 and 60),
  next_shopping_date         date,
  updated_at                 timestamptz not null default now()
);
insert into public.settings (id) values (1);

-- Pickup windows students can choose at checkout.
-- `starts_at` is when the window happens (e.g. the end of 1st hour).
-- Orders for a window close `order_lead_minutes` before it starts.
create table public.pickup_windows (
  id         serial primary key,
  label      text not null,
  starts_at  time not null,
  sort_order int  not null default 0,
  active     boolean not null default true
);

-- Days the store is closed (holidays, breaks, testing days). Weekends are
-- always closed and don't need to be listed.
create table public.closed_dates (
  closed_on date primary key,
  reason    text
);

create table public.suppliers (
  id         uuid primary key default gen_random_uuid(),
  name       text not null unique,
  notes      text,
  created_at timestamptz not null default now()
);

create table public.products (
  id               uuid primary key default gen_random_uuid(),
  name             text not null,
  description      text,
  category         text not null default 'Snacks',
  emoji            text,                 -- shown when there is no photo yet
  photo_path       text,                 -- path inside the "product-photos" bucket
  price_cents      int  not null check (price_cents >= 0),
  unit_cost_cents  int  not null default 0 check (unit_cost_cents >= 0),
  stock            int  not null default 0,  -- kept in sync by stock_movements; can go negative if counts are off
  reorder_point    int  not null default 10 check (reorder_point >= 0),
  lead_days        int  not null default 2  check (lead_days >= 0), -- days between noticing and restocking
  supplier_id      uuid references public.suppliers (id) on delete set null,
  is_perishable    boolean not null default false,
  available_online boolean not null default true,
  archived         boolean not null default false,
  tags             text[] not null default '{}',  -- e.g. {new, limited}
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index on public.products (archived, category);

-- Names the InTouchPay export uses for a product ("HOT CHEETOS 1OZ").
-- Stored lowercase and trimmed so matching ignores case and extra spaces.
create table public.product_aliases (
  id         uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete cascade,
  alias      text not null unique check (alias = lower(btrim(alias)) and alias <> ''),
  created_at timestamptz not null default now()
);

-- Online orders. Only first name, last name and grade are collected.
create sequence public.order_number_seq start 1;

create table public.orders (
  id               uuid primary key default gen_random_uuid(),
  order_number     int  not null unique default nextval('public.order_number_seq'),
  first_name       text not null check (char_length(first_name) between 1 and 40),
  last_name        text not null check (char_length(last_name)  between 1 and 40),
  grade            text not null check (char_length(grade) between 1 and 20),
  pickup_window_id int  not null references public.pickup_windows (id),
  pickup_date      date not null,
  status           public.order_status not null default 'received',
  total_cents      int  not null check (total_cents >= 0),
  staff_notes      text,
  ip_hash          text,  -- one-way hash of the device's IP, only used for rate limiting
  created_at       timestamptz not null default now(),
  status_changed_at timestamptz not null default now(),
  picked_up_at     timestamptz
);
alter sequence public.order_number_seq owned by public.orders.order_number;
create index on public.orders (pickup_date, status);
create index on public.orders (ip_hash, created_at);
create index on public.orders (lower(last_name));

create table public.order_items (
  id               uuid primary key default gen_random_uuid(),
  order_id         uuid not null references public.orders (id) on delete cascade,
  product_id       uuid not null references public.products (id),
  product_name     text not null,        -- copy of the name at order time
  unit_price_cents int  not null check (unit_price_cents >= 0),
  quantity         int  not null check (quantity > 0)
);
create index on public.order_items (order_id);
create index on public.order_items (product_id);

-- The stock ledger. products.stock always equals the sum of these rows.
create table public.stock_movements (
  id             bigint generated always as identity primary key,
  product_id     uuid not null references public.products (id) on delete cascade,
  change         int  not null check (change <> 0),
  reason         public.movement_reason not null,
  -- The day the change belongs to (Arizona time). Used to line up
  -- online pickups with that day's imported sales.
  effective_date date not null,
  note           text,
  source_id      uuid,   -- the order, import, or expense that caused it (if any)
  created_by     uuid references auth.users (id) on delete set null,
  created_at     timestamptz not null default now(),
  -- Hand-made changes must say why.
  constraint manual_changes_need_a_note check (
    reason not in ('manual_adjustment', 'spoilage') or coalesce(btrim(note), '') <> ''
  )
);
create index on public.stock_movements (product_id, effective_date);
create index on public.stock_movements (source_id);

-- Perishable restocks and their expiration dates. We don't track which exact
-- package was sold; instead the app assumes the oldest batch sells first
-- (see src/lib/calculations.ts → batchesStillOnShelf).
create table public.product_batches (
  id          uuid primary key default gen_random_uuid(),
  product_id  uuid not null references public.products (id) on delete cascade,
  quantity    int  not null check (quantity > 0),
  received_on date not null,
  expires_on  date not null,
  expense_id  uuid,   -- linked after expenses table exists (below)
  created_at  timestamptz not null default now()
);
create index on public.product_batches (product_id, received_on);

-- Shopping trips.
create table public.expenses (
  id           uuid primary key default gen_random_uuid(),
  purchased_on date not null,
  supplier_id  uuid references public.suppliers (id) on delete set null,
  buyer_name   text not null,
  receipt_path text,   -- path inside the private "receipts" bucket
  notes        text,
  total_cents  int  not null default 0 check (total_cents >= 0),
  created_by   uuid references auth.users (id) on delete set null,
  created_at   timestamptz not null default now()
);
create index on public.expenses (purchased_on);

-- Line items on a shopping trip. product_id is empty for supplies that
-- aren't sold (napkins, bags) — they still count as spending.
create table public.expense_items (
  id              uuid primary key default gen_random_uuid(),
  expense_id      uuid not null references public.expenses (id) on delete cascade,
  product_id      uuid references public.products (id) on delete set null,
  description     text not null,
  quantity        int  not null check (quantity > 0),
  unit_cost_cents int  not null check (unit_cost_cents >= 0),
  line_total_cents int generated always as (quantity * unit_cost_cents) stored
);
create index on public.expense_items (expense_id);
create index on public.expense_items (product_id);

alter table public.product_batches
  add constraint product_batches_expense_fk
  foreign key (expense_id) references public.expenses (id) on delete cascade;

-- One uploaded InTouchPay export.
create table public.sales_imports (
  id              uuid primary key default gen_random_uuid(),
  file_name       text not null,
  file_hash       text not null,         -- SHA-256 of the file, to block re-uploading the same file
  column_mapping  jsonb not null default '{}',
  row_count       int  not null default 0,  -- rows in the file
  imported_count  int  not null default 0,  -- rows saved
  duplicate_count int  not null default 0,  -- rows skipped because they were already imported
  date_from       date,
  date_to         date,
  revenue_cents   int  not null default 0,
  imported_by     uuid references auth.users (id) on delete set null,
  created_at      timestamptz not null default now(),
  undone_at       timestamptz,
  undone_by       uuid references auth.users (id) on delete set null
);
-- The same file can't be active twice (it can be re-imported after an undo).
create unique index sales_imports_active_file on public.sales_imports (file_hash) where undone_at is null;

-- One row per line in the export.
create table public.sales_lines (
  id               uuid primary key default gen_random_uuid(),
  import_id        uuid not null references public.sales_imports (id) on delete cascade,
  sold_at          timestamptz,
  sale_date        date not null,
  raw_item_name    text not null,        -- exactly as it appeared in the file
  product_id       uuid references public.products (id) on delete set null, -- empty = unmatched
  quantity         int  not null,        -- negative for refunds
  unit_price_cents int  not null,
  total_cents      int  not null,
  payment_type     public.payment_type not null default 'other',
  transaction_ref  text,
  -- A fingerprint of the line's contents. Unique, so the same sale can never
  -- be imported twice even if it shows up in two different export files.
  fingerprint      text not null unique
);
create index on public.sales_lines (sale_date);
create index on public.sales_lines (product_id, sale_date);
create index on public.sales_lines (import_id);


-- -----------------------------------------------------------------------------
-- 3. Helper functions
-- -----------------------------------------------------------------------------

-- Today's date in the store's timezone.
create or replace function public.store_today()
returns date
language sql stable
set search_path = public
as $$
  select (now() at time zone (select timezone from public.settings where id = 1))::date;
$$;

-- The current time of day in the store's timezone.
create or replace function public.store_now_time()
returns time
language sql stable
set search_path = public
as $$
  select (now() at time zone (select timezone from public.settings where id = 1))::time;
$$;

-- True when the logged-in user is the store admin.
-- SECURITY DEFINER so it can read `admins` even though RLS protects it.
create or replace function public.is_admin()
returns boolean
language sql stable security definer
set search_path = public
as $$
  select exists (select 1 from public.admins where user_id = auth.uid());
$$;

-- Is the store open for pickups on this date? (Not a weekend, not a closed date.)
create or replace function public.is_open_day(d date)
returns boolean
language sql stable
set search_path = public
as $$
  select extract(isodow from d) < 6
     and not exists (select 1 from public.closed_dates where closed_on = d);
$$;

-- The first open day strictly after `d` (looks up to 60 days ahead).
create or replace function public.next_open_day(d date)
returns date
language sql stable
set search_path = public
as $$
  select min(day)::date
  from generate_series(d + 1, d + 60, interval '1 day') as day
  where public.is_open_day(day::date);
$$;

-- Units of each product held by open online orders (today or later).
-- Orders from past days don't count even if nobody closed them yet.
create or replace view public.product_reserved
with (security_invoker = true)
as
  select oi.product_id, sum(oi.quantity)::int as reserved
  from public.order_items oi
  join public.orders o on o.id = oi.order_id
  where o.status in ('received', 'preparing', 'ready')
    and o.pickup_date >= public.store_today()
  group by oi.product_id;


-- -----------------------------------------------------------------------------
-- 4. Triggers
-- -----------------------------------------------------------------------------

-- Every new stock movement updates the product's stock count.
create or replace function public.apply_stock_movement()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  update public.products
     set stock = stock + new.change,
         updated_at = now()
   where id = new.product_id;
  return new;
end;
$$;

create trigger stock_movements_apply
after insert on public.stock_movements
for each row execute function public.apply_stock_movement();

-- Movements are a permanent history: block edits and deletes.
-- (To fix a mistake, add a new movement that reverses it.)
create or replace function public.block_movement_changes()
returns trigger
language plpgsql
as $$
begin
  raise exception 'Stock history cannot be edited. Add a new adjustment instead.';
end;
$$;

create trigger stock_movements_readonly
before update or delete on public.stock_movements
for each row
when (pg_trigger_depth() = 0)  -- allow cascades when a whole product is deleted
execute function public.block_movement_changes();

-- Keep updated_at fresh.
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger products_touch before update on public.products
for each row execute function public.touch_updated_at();
create trigger settings_touch before update on public.settings
for each row execute function public.touch_updated_at();

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000002_orders.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — ordering, stock reconciliation, and public read functions
-- =============================================================================
-- The public (students) never read or write tables directly. They only call
-- these functions:
--   get_menu()             products students can see, with "available" counts
--   get_store_info()       hours, banner, pickup windows, what days are open
--   lookup_order(n, last)  status of one order, needs the matching last name
--   place_order(...)       creates an order (called by the website server only)
--
-- Errors use short codes in the message (e.g. 'SOLD_OUT') and a friendly
-- sentence in the HINT. The website shows the hint to students.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- Public: menu and store info
-- -----------------------------------------------------------------------------

-- Products students can order. Leaves out cost, supplier, and exact stock.
-- `available` = stock − reserved, never below 0.
create or replace function public.get_menu()
returns table (
  id          uuid,
  name        text,
  description text,
  category    text,
  emoji       text,
  photo_path  text,
  price_cents int,
  tags        text[],
  available   int
)
language sql stable security definer
set search_path = public
as $$
  select p.id, p.name, p.description, p.category, p.emoji, p.photo_path,
         p.price_cents, p.tags,
         greatest(p.stock - coalesce(r.reserved, 0), 0) as available
  from public.products p
  left join public.product_reserved r on r.product_id = p.id
  where p.available_online and not p.archived
  order by p.category, p.name;
$$;

-- Everything the public pages need to know about the store, as one JSON object.
create or replace function public.get_store_info()
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'store_name',        s.store_name,
    'store_hours',       s.store_hours,
    'pickup_location',   s.pickup_location,
    'banner_text',       s.banner_text,
    'today',             public.store_today(),
    'now_time',          to_char(public.store_now_time(), 'HH24:MI'),
    'order_cutoff_time', to_char(s.order_cutoff_time, 'HH24:MI'),
    'order_lead_minutes', s.order_lead_minutes,
    'max_items_per_order', s.max_items_per_order,
    'today_is_open',     public.is_open_day(public.store_today()),
    'next_open_day',     public.next_open_day(public.store_today()),
    'pickup_windows', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', w.id,
               'label', w.label,
               'starts_at', to_char(w.starts_at, 'HH24:MI'))
             order by w.sort_order, w.starts_at)
      from public.pickup_windows w where w.active), '[]'::jsonb)
  )
  from public.settings s where s.id = 1;
$$;


-- -----------------------------------------------------------------------------
-- Public: order lookup (order number + last name)
-- -----------------------------------------------------------------------------
-- Returns no rows unless BOTH match, so guessing order numbers reveals nothing.
-- The student's name is not returned.
create or replace function public.lookup_order(p_order_number int, p_last_name text)
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'order_number', o.order_number,
    'status',       o.status,
    'pickup_date',  o.pickup_date,
    'pickup_window', w.label,
    'total_cents',  o.total_cents,
    'created_at',   o.created_at,
    'items', (
      select jsonb_agg(jsonb_build_object(
               'name', oi.product_name,
               'quantity', oi.quantity,
               'unit_price_cents', oi.unit_price_cents)
             order by oi.product_name)
      from public.order_items oi where oi.order_id = o.id)
  )
  from public.orders o
  join public.pickup_windows w on w.id = o.pickup_window_id
  where o.order_number = p_order_number
    and lower(btrim(o.last_name)) = lower(btrim(p_last_name));
$$;


-- -----------------------------------------------------------------------------
-- place_order: the only way an order gets created
-- -----------------------------------------------------------------------------
-- Called by the website's server (with the service role key), never directly
-- from a browser — that's how we know the ip_hash is real and can't be faked.
--
-- p_items is a JSON array: [{"product_id": "...", "quantity": 2}, ...]
--
-- Everything happens in one transaction. Product rows are locked while we
-- check stock, so two students can't both buy the last bag of chips.
create or replace function public.place_order(
  p_first_name       text,
  p_last_name        text,
  p_grade            text,
  p_pickup_window_id int,
  p_pickup_date      date,
  p_items            jsonb,
  p_ip_hash          text
)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  s            public.settings;
  w            public.pickup_windows;
  v_today      date := public.store_today();
  v_now        time := public.store_now_time();
  v_first      text := btrim(coalesce(p_first_name, ''));
  v_last       text := btrim(coalesce(p_last_name, ''));
  v_grade      text := btrim(coalesce(p_grade, ''));
  v_item       record;
  v_product    public.products;
  v_available  int;
  v_total      int := 0;
  v_count      int;
  v_order      public.orders;
begin
  select * into s from public.settings where id = 1;

  -- ---- Who is ordering --------------------------------------------------------
  if v_first = '' or v_last = '' or v_grade = '' then
    raise exception 'MISSING_INFO' using hint = 'Please fill in your first name, last name, and grade.';
  end if;
  if char_length(v_first) > 40 or char_length(v_last) > 40 or char_length(v_grade) > 20 then
    raise exception 'INFO_TOO_LONG' using hint = 'One of your answers is too long.';
  end if;

  -- ---- When -------------------------------------------------------------------
  -- Students can order for today or for the next open school day.
  if p_pickup_date is null
     or p_pickup_date not in (v_today, public.next_open_day(v_today)) then
    raise exception 'BAD_DATE' using hint = 'Orders can only be placed for today or the next school day.';
  end if;
  if not public.is_open_day(p_pickup_date) then
    raise exception 'STORE_CLOSED' using hint = 'The store is closed that day.';
  end if;

  select * into w from public.pickup_windows where id = p_pickup_window_id and active;
  if not found then
    raise exception 'BAD_WINDOW' using hint = 'Please choose a pickup time.';
  end if;

  if p_pickup_date = v_today then
    if v_now >= s.order_cutoff_time then
      raise exception 'ORDERS_CLOSED' using hint = format(
        'Same-day orders close at %s. You can still order for the next school day.',
        to_char(s.order_cutoff_time, 'FMHH12:MI AM'));
    end if;
    if v_now >= w.starts_at - make_interval(mins => s.order_lead_minutes) then
      raise exception 'WINDOW_CLOSED' using hint = format(
        'It''s too late to order for %s today. Please pick a later time.', w.label);
    end if;
  end if;

  -- ---- Prank protection ---------------------------------------------------------
  -- 1) Limit orders per student per day (same first + last name).
  select count(*) into v_count
  from public.orders
  where pickup_date = p_pickup_date
    and lower(first_name) = lower(v_first)
    and lower(last_name)  = lower(v_last)
    and status not in ('canceled');
  if v_count >= s.max_orders_per_student_day then
    raise exception 'STUDENT_LIMIT' using hint = format(
      'You already have %s order(s) for that day, which is the limit.', v_count);
  end if;

  -- 2) Limit orders per device per hour.
  if p_ip_hash is not null then
    select count(*) into v_count
    from public.orders
    where ip_hash = p_ip_hash and created_at > now() - interval '1 hour';
    if v_count >= s.max_orders_per_hour_per_device then
      raise exception 'RATE_LIMIT' using hint = 'Too many orders from this device. Please try again later.';
    end if;
  end if;

  -- ---- What -------------------------------------------------------------------
  if p_items is null or jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'EMPTY_CART' using hint = 'Your cart is empty.';
  end if;

  -- Combine duplicate lines and check quantities.
  drop table if exists _cart;
  create temporary table _cart on commit drop as
    select (x->>'product_id')::uuid as product_id, sum((x->>'quantity')::int)::int as quantity
    from jsonb_array_elements(p_items) as x
    group by 1;

  if exists (select 1 from _cart where quantity is null or quantity < 1) then
    raise exception 'BAD_QUANTITY' using hint = 'Each item needs a quantity of at least 1.';
  end if;
  if (select sum(quantity) from _cart) > s.max_items_per_order then
    raise exception 'TOO_MANY_ITEMS' using hint = format(
      'Orders are limited to %s items.', s.max_items_per_order);
  end if;

  -- Create the order first (total filled in below).
  insert into public.orders (first_name, last_name, grade, pickup_window_id, pickup_date, total_cents, ip_hash)
  values (v_first, v_last, v_grade, w.id, p_pickup_date, 0, p_ip_hash)
  returning * into v_order;

  -- Lock each product (in a fixed order to avoid deadlocks) and check stock.
  for v_item in select * from _cart order by product_id loop
    select * into v_product from public.products where id = v_item.product_id for update;

    if not found or v_product.archived or not v_product.available_online then
      raise exception 'UNAVAILABLE' using hint = 'An item in your cart is no longer available. Please refresh the menu.';
    end if;

    select v_product.stock - coalesce((select reserved from public.product_reserved where product_id = v_product.id), 0)
      into v_available;

    if v_available < v_item.quantity then
      raise exception 'SOLD_OUT' using hint = case
        when v_available <= 0 then format('%s just sold out.', v_product.name)
        else format('Only %s %s left.', v_available, v_product.name) end;
    end if;

    insert into public.order_items (order_id, product_id, product_name, unit_price_cents, quantity)
    values (v_order.id, v_product.id, v_product.name, v_product.price_cents, v_item.quantity);

    v_total := v_total + v_product.price_cents * v_item.quantity;
  end loop;

  update public.orders set total_cents = v_total where id = v_order.id;

  return jsonb_build_object(
    'order_number',  v_order.order_number,
    'pickup_date',   v_order.pickup_date,
    'pickup_window', w.label,
    'total_cents',   v_total
  );
end;
$$;


-- -----------------------------------------------------------------------------
-- Stock reconciliation between online pickups and imported sales
-- -----------------------------------------------------------------------------
-- The rule: stock goes down when an item is paid for.
--   * Online orders are paid at pickup → stock goes down when marked Picked up.
--   * In-person sales only reach us through the InTouchPay import.
--   * BUT online orders are also rung up in InTouchPay, so they appear in the
--     import too. Subtracting both would count them twice.
--
-- So for each product and day:
--     I = units in imported sales that day
--     P = units from online orders picked up that day
--   The import should only subtract what the pickups didn't already:
--     import share = max(0, I − P)
--
-- This function compares that target with what imports have already
-- subtracted for that product/day, and adds one movement for the difference.
-- It's safe to call any number of times (calling it twice changes nothing).
create or replace function public.reconcile_sales_stock(p_product_id uuid, p_day date)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_imported  int;
  v_picked_up int;
  v_target    int;
  v_current   int;
begin
  select coalesce(sum(quantity), 0) into v_imported
  from public.sales_lines
  where product_id = p_product_id and sale_date = p_day;

  select coalesce(-sum(change), 0) into v_picked_up
  from public.stock_movements
  where product_id = p_product_id and effective_date = p_day
    and reason in ('online_pickup', 'online_pickup_undo');

  v_target := greatest(v_imported - v_picked_up, 0);

  select coalesce(-sum(change), 0) into v_current
  from public.stock_movements
  where product_id = p_product_id and effective_date = p_day
    and reason = 'sale_import';

  if v_target <> v_current then
    insert into public.stock_movements (product_id, change, reason, effective_date, note, created_by)
    values (p_product_id, -(v_target - v_current), 'sale_import', p_day,
            format('In-person sales on %s (imported %s, online pickups %s)', p_day, v_imported, v_picked_up),
            auth.uid());
  end if;
end;
$$;


-- -----------------------------------------------------------------------------
-- Staff: change an order's status
-- -----------------------------------------------------------------------------
-- Moving TO picked_up subtracts the items from stock (they've been paid for).
-- Moving AWAY from picked_up (a mistake) puts them back.
create or replace function public.set_order_status(p_order_id uuid, p_status public.order_status)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_order public.orders;
  v_day   date := public.store_today();
  v_item  record;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'NOT_FOUND' using hint = 'That order no longer exists.';
  end if;
  if v_order.status = p_status then
    return;
  end if;

  if p_status = 'picked_up' then
    for v_item in select product_id, sum(quantity)::int as qty from public.order_items
                  where order_id = p_order_id group by product_id loop
      insert into public.stock_movements (product_id, change, reason, effective_date, note, source_id, created_by)
      values (v_item.product_id, -v_item.qty, 'online_pickup', v_day,
              format('Online order SS-%s picked up', lpad(v_order.order_number::text, 4, '0')),
              p_order_id, auth.uid());
      perform public.reconcile_sales_stock(v_item.product_id, v_day);
    end loop;

  elsif v_order.status = 'picked_up' then
    -- Undo on the day it was picked up, so the day's math still lines up.
    v_day := (v_order.picked_up_at at time zone (select timezone from public.settings where id = 1))::date;
    for v_item in select product_id, sum(quantity)::int as qty from public.order_items
                  where order_id = p_order_id group by product_id loop
      insert into public.stock_movements (product_id, change, reason, effective_date, note, source_id, created_by)
      values (v_item.product_id, v_item.qty, 'online_pickup_undo', v_day,
              format('Order SS-%s moved back from Picked up', lpad(v_order.order_number::text, 4, '0')),
              p_order_id, auth.uid());
      perform public.reconcile_sales_stock(v_item.product_id, v_day);
    end loop;
  end if;

  update public.orders
     set status = p_status,
         status_changed_at = now(),
         picked_up_at = case when p_status = 'picked_up' then now()
                             when v_order.status = 'picked_up' then null
                             else picked_up_at end
   where id = p_order_id;
end;
$$;


-- -----------------------------------------------------------------------------
-- Scheduled housekeeping (run by pg_cron, see the jobs migration)
-- -----------------------------------------------------------------------------

-- Close orders nobody collected on past days. This releases their reserved
-- stock (reservations only count open orders).
create or replace function public.expire_uncollected_orders()
returns int
language sql security definer
set search_path = public
as $$
  with expired as (
    update public.orders
       set status = 'expired', status_changed_at = now()
     where status in ('received', 'preparing', 'ready')
       and pickup_date < public.store_today()
    returning 1
  )
  select count(*)::int from expired;
$$;

-- Delete orders older than the retention setting (default 90 days).
-- Stock history keeps its rows (they hold no personal info).
create or replace function public.delete_old_orders()
returns int
language sql security definer
set search_path = public
as $$
  with gone as (
    delete from public.orders
     where created_at < now() - make_interval(days => (select order_retention_days from public.settings where id = 1))
    returning 1
  )
  select count(*)::int from gone;
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000003_security.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — security: Row Level Security, function permissions, storage
-- =============================================================================
-- The short version:
--   * Students (the "anon" role) can't read or write ANY table directly.
--     They can only call get_menu, get_store_info and lookup_order.
--   * place_order can only be called by the website's server (service_role).
--   * The admin (a logged-in user listed in `admins`) can do everything.
-- =============================================================================

-- Turn on RLS for every table. With RLS on and no policy, access is denied.
alter table public.admins           enable row level security;
alter table public.settings         enable row level security;
alter table public.pickup_windows   enable row level security;
alter table public.closed_dates     enable row level security;
alter table public.suppliers        enable row level security;
alter table public.products         enable row level security;
alter table public.product_aliases  enable row level security;
alter table public.orders           enable row level security;
alter table public.order_items      enable row level security;
alter table public.stock_movements  enable row level security;
alter table public.product_batches  enable row level security;
alter table public.expenses         enable row level security;
alter table public.expense_items    enable row level security;
alter table public.sales_imports    enable row level security;
alter table public.sales_lines      enable row level security;

-- One "admin can do anything" policy per table.
do $$
declare
  t text;
begin
  foreach t in array array[
    'settings', 'pickup_windows', 'closed_dates', 'suppliers', 'products',
    'product_aliases', 'orders', 'order_items', 'product_batches',
    'expenses', 'expense_items', 'sales_imports', 'sales_lines'
  ] loop
    execute format(
      'create policy "admin full access" on public.%I for all to authenticated
         using (public.is_admin()) with check (public.is_admin())', t);
  end loop;
end $$;

-- Stock history: admin can read and add, never edit (a trigger also blocks it).
create policy "admin reads stock history" on public.stock_movements
  for select to authenticated using (public.is_admin());
create policy "admin adds stock history" on public.stock_movements
  for insert to authenticated with check (public.is_admin());

-- The admin can see their own row (used to check "am I the admin?").
create policy "admin sees self" on public.admins
  for select to authenticated using (user_id = auth.uid());


-- -----------------------------------------------------------------------------
-- Function permissions
-- -----------------------------------------------------------------------------
-- Postgres lets everyone run new functions by default. Take that away, then
-- give back exactly what each role needs.
revoke execute on all functions in schema public from public, anon, authenticated;

-- Students (and everyone else)
grant execute on function public.get_menu()                to anon, authenticated;
grant execute on function public.get_store_info()          to anon, authenticated;
grant execute on function public.lookup_order(int, text)   to anon, authenticated;

-- Small date helpers (harmless; they reveal nothing private).
grant execute on function public.store_today()        to anon, authenticated, service_role;
grant execute on function public.store_now_time()     to anon, authenticated, service_role;
grant execute on function public.is_open_day(date)    to anon, authenticated, service_role;
grant execute on function public.next_open_day(date)  to anon, authenticated, service_role;

-- Used inside RLS policies, so the logged-in user must be able to run it.
grant execute on function public.is_admin()           to authenticated;

-- Staff actions (each one also checks is_admin() inside)
grant execute on function public.set_order_status(uuid, public.order_status) to authenticated;
-- reconcile_sales_stock is only called from inside other functions.

-- The website server only
grant execute on function public.place_order(text, text, text, int, date, jsonb, text) to service_role;
grant execute on function public.expire_uncollected_orders() to service_role;
grant execute on function public.delete_old_orders()         to service_role;

-- Future functions start locked down too.
alter default privileges in schema public revoke execute on functions from public, anon, authenticated;

-- The reserved-stock view is for the admin only.
revoke all on public.product_reserved from anon;


-- -----------------------------------------------------------------------------
-- File storage
-- -----------------------------------------------------------------------------
-- product-photos: anyone can view (they're on the menu); only the admin uploads.
-- receipts:       private; only the admin can view or upload.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('product-photos', 'product-photos', true,  5242880,  array['image/jpeg', 'image/png', 'image/webp']),
  ('receipts',       'receipts',       false, 10485760, array['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'application/pdf'])
on conflict (id) do nothing;

create policy "admin manages product photos" on storage.objects
  for all to authenticated
  using (bucket_id = 'product-photos' and public.is_admin())
  with check (bucket_id = 'product-photos' and public.is_admin());

create policy "admin manages receipts" on storage.objects
  for all to authenticated
  using (bucket_id = 'receipts' and public.is_admin())
  with check (bucket_id = 'receipts' and public.is_admin());

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000004_scheduled_jobs.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — scheduled jobs (pg_cron)
-- =============================================================================
-- pg_cron runs SQL on a schedule inside the database. It's included free with
-- Supabase. Times are in UTC. Arizona is always UTC−7 (no daylight saving),
-- so 06:00 UTC = 11:00 PM in Arizona.
--
-- To see the jobs:   select * from cron.job;
-- To see past runs:  select * from cron.job_run_details order by start_time desc;
-- =============================================================================

do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;

    -- Every night at 11:00 PM Arizona: close orders nobody picked up.
    perform cron.schedule(
      'expire-uncollected-orders',
      '0 6 * * *',
      'select public.expire_uncollected_orders();'
    );

    -- Every night at 11:30 PM Arizona: delete orders past the retention period.
    perform cron.schedule(
      'delete-old-orders',
      '30 6 * * *',
      'select public.delete_old_orders();'
    );
  else
    raise notice 'pg_cron is not available here; skipping scheduled jobs.';
  end if;
end $$;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000005_dashboard.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — numbers for the staff dashboard, in one call
-- =============================================================================

create or replace function public.dashboard_summary()
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_today date := public.store_today();
  -- Monday of this week
  v_week_start date := v_today - (extract(isodow from v_today)::int - 1);
  v_result jsonb;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;

  select jsonb_build_object(
    'today', v_today,
    'week_start', v_week_start,

    -- {"received": 4, "ready": 2, ...} for orders picked up today
    'orders_today', coalesce((
      select jsonb_object_agg(status, n)
      from (select status, count(*) as n from public.orders
            where pickup_date = v_today group by status) t), '{}'::jsonb),

    'orders_upcoming', (
      select count(*) from public.orders
      where pickup_date > v_today and status in ('received', 'preparing', 'ready')),

    'week_revenue_cents', (
      select coalesce(sum(total_cents), 0) from public.sales_lines
      where sale_date between v_week_start and v_today),

    'week_spending_cents', (
      select coalesce(sum(total_cents), 0) from public.expenses
      where purchased_on between v_week_start and v_today),

    'last_week_revenue_cents', (
      select coalesce(sum(total_cents), 0) from public.sales_lines
      where sale_date between v_week_start - 7 and v_week_start - 1),

    'last_week_spending_cents', (
      select coalesce(sum(total_cents), 0) from public.expenses
      where purchased_on between v_week_start - 7 and v_week_start - 1),

    'last_import_at', (
      select max(created_at) from public.sales_imports where undone_at is null),

    'last_sale_date', (
      select max(sale_date) from public.sales_lines),

    'unmatched_sales_lines', (
      select count(*) from public.sales_lines where product_id is null),

    -- Products at or below their reorder point, most urgent first.
    'low_stock', coalesce((
      select jsonb_agg(row_to_json(t) order by t.stock - t.reorder_point, t.name)
      from (
        select p.id, p.name, p.emoji, p.stock, p.reorder_point,
               coalesce(r.reserved, 0) as reserved
        from public.products p
        left join public.product_reserved r on r.product_id = p.id
        where not p.archived and p.stock - coalesce(r.reserved, 0) <= p.reorder_point
      ) t), '[]'::jsonb),

    -- Perishable batches expiring in the next 3 days (may already be sold).
    'expiring_soon', (
      select count(*) from public.product_batches b
      join public.products p on p.id = b.product_id
      where not p.archived and p.stock > 0
        and b.expires_on between v_today and v_today + 3)
  ) into v_result;

  return v_result;
end;
$$;

revoke execute on function public.dashboard_summary() from public, anon;
grant execute on function public.dashboard_summary() to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000006_inventory_expenses.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — inventory numbers and shopping trips (phase 4)
-- =============================================================================
--   inventory_snapshot()   everything the Inventory page needs, in one call
--   save_expense(json)     records a shopping trip and adds the stock
--   delete_expense(id)     removes a trip that was entered by mistake
-- =============================================================================


-- -----------------------------------------------------------------------------
-- inventory_snapshot
-- -----------------------------------------------------------------------------
-- "Units sold" counts every unit that was PAID FOR (online pickups and
-- imported in-person sales), read from the stock history. The averaging
-- window is the sales_average_days setting, shortened if the store doesn't
-- have that much history yet (so a new store isn't under-counted).
create or replace function public.inventory_snapshot()
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  s            public.settings;
  v_today      date := public.store_today();
  v_first_sale date;
  v_days       int;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;

  select * into s from public.settings where id = 1;

  select min(effective_date) into v_first_sale
  from public.stock_movements
  where reason in ('sale_import', 'online_pickup');

  v_days := greatest(1, least(s.sales_average_days, v_today - coalesce(v_first_sale, v_today) + 1));

  return jsonb_build_object(
    'today', v_today,
    'window_days', v_days,
    'reorder_buffer_days', s.reorder_buffer_days,
    'shopping_interval_days', s.shopping_interval_days,
    'next_shopping_date', s.next_shopping_date,
    'products', coalesce((
      select jsonb_agg(row_to_json(t) order by t.name)
      from (
        select
          p.id, p.name, p.category, p.emoji, p.photo_path,
          p.stock, coalesce(r.reserved, 0) as reserved,
          p.price_cents, p.unit_cost_cents, p.reorder_point, p.lead_days,
          p.is_perishable, p.available_online,
          sup.name as supplier,
          -- units paid for in the window
          coalesce((
            select -sum(m.change)
            from public.stock_movements m
            where m.product_id = p.id
              and m.reason in ('sale_import', 'online_pickup', 'online_pickup_undo')
              and m.effective_date > v_today - v_days
          ), 0)::int as units_sold,
          -- perishable batches, newest first (for expiration dates)
          case when p.is_perishable then coalesce((
            select jsonb_agg(jsonb_build_object(
                     'quantity', b.quantity, 'received_on', b.received_on, 'expires_on', b.expires_on)
                   order by b.received_on desc, b.created_at desc)
            from public.product_batches b where b.product_id = p.id
          ), '[]'::jsonb) end as batches
        from public.products p
        left join public.product_reserved r on r.product_id = p.id
        left join public.suppliers sup on sup.id = p.supplier_id
        where not p.archived
      ) t), '[]'::jsonb)
  );
end;
$$;


-- -----------------------------------------------------------------------------
-- save_expense
-- -----------------------------------------------------------------------------
-- p is a JSON object:
-- {
--   "purchased_on": "2026-10-26", "supplier_id": "...", "buyer_name": "Ms. A",
--   "receipt_path": "2026/10/abc.jpg", "notes": "...",
--   "items": [
--     { "product_id": "...", "description": "Hot Cheetos", "quantity": 24,
--       "unit_cost_cents": 55, "update_cost": true, "expires_on": null },
--     { "product_id": null, "description": "Napkins", "quantity": 1, "unit_cost_cents": 649 }
--   ]
-- }
-- Everything happens together: if any line is bad, nothing is saved.
create or replace function public.save_expense(p jsonb)
returns uuid
language plpgsql security definer
set search_path = public
as $$
declare
  v_id      uuid;
  v_item    jsonb;
  v_product public.products;
  v_qty     int;
  v_cost    int;
  v_date    date := (p->>'purchased_on')::date;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;
  if v_date is null or v_date > public.store_today() then
    raise exception 'BAD_DATE' using hint = 'Choose the day of the trip (it can''t be in the future).';
  end if;
  if coalesce(btrim(p->>'buyer_name'), '') = '' then
    raise exception 'NO_BUYER' using hint = 'Enter who did the shopping.';
  end if;
  if jsonb_typeof(p->'items') <> 'array' or jsonb_array_length(p->'items') = 0 then
    raise exception 'NO_ITEMS' using hint = 'Add at least one item.';
  end if;

  insert into public.expenses (purchased_on, supplier_id, buyer_name, receipt_path, notes, created_by)
  values (v_date, nullif(p->>'supplier_id', '')::uuid, btrim(p->>'buyer_name'),
          nullif(p->>'receipt_path', ''), nullif(btrim(p->>'notes'), ''), auth.uid())
  returning id into v_id;

  for v_item in select * from jsonb_array_elements(p->'items') loop
    v_qty  := (v_item->>'quantity')::int;
    v_cost := (v_item->>'unit_cost_cents')::int;
    if v_qty is null or v_qty < 1 or v_cost is null or v_cost < 0 then
      raise exception 'BAD_LINE' using hint = 'Every line needs a quantity of 1 or more and a cost.';
    end if;

    v_product := null;
    if nullif(v_item->>'product_id', '') is not null then
      select * into v_product from public.products where id = (v_item->>'product_id')::uuid;
      if not found then
        raise exception 'BAD_PRODUCT' using hint = 'One of the products no longer exists.';
      end if;
    end if;

    insert into public.expense_items (expense_id, product_id, description, quantity, unit_cost_cents)
    values (v_id, v_product.id,
            coalesce(nullif(btrim(v_item->>'description'), ''), v_product.name, 'Supplies'),
            v_qty, v_cost);

    if v_product.id is not null then
      -- Add to stock.
      insert into public.stock_movements (product_id, change, reason, effective_date, note, source_id, created_by)
      values (v_product.id, v_qty, 'restock', v_date, 'Shopping trip', v_id, auth.uid());

      -- Remember the expiration date for perishables.
      if v_product.is_perishable and nullif(v_item->>'expires_on', '') is not null then
        insert into public.product_batches (product_id, quantity, received_on, expires_on, expense_id)
        values (v_product.id, v_qty, v_date, (v_item->>'expires_on')::date, v_id);
      end if;

      -- Optionally update the product's cost to this trip's price.
      if coalesce((v_item->>'update_cost')::boolean, false) then
        update public.products set unit_cost_cents = v_cost where id = v_product.id;
      end if;
    end if;
  end loop;

  update public.expenses e
     set total_cents = (select coalesce(sum(line_total_cents), 0) from public.expense_items where expense_id = e.id)
   where e.id = v_id;

  return v_id;
end;
$$;


-- -----------------------------------------------------------------------------
-- delete_expense
-- -----------------------------------------------------------------------------
-- For trips entered by mistake. Takes back the stock it added (as a new
-- history line, so the history stays honest), then deletes the trip.
-- Product costs that were updated are NOT changed back.
create or replace function public.delete_expense(p_expense_id uuid)
returns text
language plpgsql security definer
set search_path = public
as $$
declare
  v_receipt text;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;

  select receipt_path into v_receipt from public.expenses where id = p_expense_id;
  if not found then
    raise exception 'NOT_FOUND' using hint = 'That shopping trip no longer exists.';
  end if;

  insert into public.stock_movements (product_id, change, reason, effective_date, note, source_id, created_by)
  select m.product_id, -sum(m.change)::int, 'manual_adjustment', public.store_today(),
         'Shopping trip deleted (entered by mistake)', p_expense_id, auth.uid()
  from public.stock_movements m
  where m.source_id = p_expense_id and m.reason = 'restock'
  group by m.product_id
  having sum(m.change) <> 0;

  delete from public.expenses where id = p_expense_id;  -- items and batches go with it

  return v_receipt;  -- so the website can delete the receipt file too
end;
$$;


revoke execute on function public.inventory_snapshot()   from public, anon;
revoke execute on function public.save_expense(jsonb)    from public, anon;
revoke execute on function public.delete_expense(uuid)   from public, anon;
grant  execute on function public.inventory_snapshot()   to authenticated;
grant  execute on function public.save_expense(jsonb)    to authenticated;
grant  execute on function public.delete_expense(uuid)   to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000007_sales_import.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — importing the InTouchPay sales export (phase 5)
-- =============================================================================
--   import_sales(json)        saves one uploaded file's sales, all or nothing
--   undo_import(id)           removes an import's sales and fixes stock
--   link_item_name(name, id)  "this InTouchPay name is that product"
--   unmatched_item_names()    sales whose item name isn't linked to a product
--
-- After any of these, stock is corrected with reconcile_sales_stock() for
-- each product + day that changed (see the orders migration for how that
-- avoids counting online orders twice).
-- =============================================================================


-- Re-runs the stock math for a list of (product, day) pairs.
create or replace function public.reconcile_pairs(p_pairs jsonb)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_pair record;
begin
  for v_pair in
    select distinct (x->>'product_id')::uuid as product_id, (x->>'sale_date')::date as sale_date
    from jsonb_array_elements(p_pairs) x
    where x->>'product_id' is not null
  loop
    perform public.reconcile_sales_stock(v_pair.product_id, v_pair.sale_date);
  end loop;
end;
$$;


-- -----------------------------------------------------------------------------
-- import_sales
-- -----------------------------------------------------------------------------
-- p = {
--   "file_name": "export.csv", "file_hash": "<sha-256>", "row_count": 120,
--   "column_mapping": { ... },
--   "aliases": [ { "alias": "fruit snacks", "product_id": "..." } ],   -- new links to remember
--   "lines": [ { "sold_at": "2026-10-26T12:30:00-07:00", "sale_date": "2026-10-26",
--                "raw_item_name": "HOT CHEETOS 1OZ", "product_id": "..." | null,
--                "quantity": 2, "unit_price_cents": 150, "total_cents": 300,
--                "payment_type": "cash", "transaction_ref": "T123", "fingerprint": "..." } ]
-- }
-- Lines whose fingerprint was already imported are skipped (duplicate
-- protection), so overlapping exports are safe to upload.
create or replace function public.import_sales(p jsonb)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_id        uuid;
  v_inserted  int;
  v_total     int := jsonb_array_length(p->'lines');
  v_pairs     jsonb;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;
  if v_total = 0 then
    raise exception 'NO_LINES' using hint = 'There are no sales lines to import.';
  end if;
  if exists (select 1 from public.sales_imports where file_hash = p->>'file_hash' and undone_at is null) then
    raise exception 'DUPLICATE_FILE' using hint = 'This exact file was already imported. Nothing was added.';
  end if;

  -- Remember new InTouchPay names (so next time they match by themselves).
  insert into public.product_aliases (product_id, alias)
  select (a->>'product_id')::uuid, lower(btrim(a->>'alias'))
  from jsonb_array_elements(coalesce(p->'aliases', '[]'::jsonb)) a
  where nullif(a->>'product_id', '') is not null and btrim(a->>'alias') <> ''
  on conflict (alias) do update set product_id = excluded.product_id;

  insert into public.sales_imports (file_name, file_hash, column_mapping, row_count, imported_by)
  values (p->>'file_name', p->>'file_hash', coalesce(p->'column_mapping', '{}'::jsonb),
          coalesce((p->>'row_count')::int, v_total), auth.uid())
  returning id into v_id;

  with incoming as (
    select
      nullif(l->>'sold_at', '')::timestamptz as sold_at,
      (l->>'sale_date')::date as sale_date,
      l->>'raw_item_name' as raw_item_name,
      -- use the link chosen in the preview, or a saved name, or the product's own name
      coalesce(
        nullif(l->>'product_id', '')::uuid,
        (select pa.product_id from public.product_aliases pa where pa.alias = lower(btrim(l->>'raw_item_name'))),
        (select pr.id from public.products pr where lower(pr.name) = lower(btrim(l->>'raw_item_name')) limit 1)
      ) as product_id,
      (l->>'quantity')::int as quantity,
      (l->>'unit_price_cents')::int as unit_price_cents,
      (l->>'total_cents')::int as total_cents,
      coalesce(nullif(l->>'payment_type', ''), 'other')::public.payment_type as payment_type,
      nullif(l->>'transaction_ref', '') as transaction_ref,
      l->>'fingerprint' as fingerprint
    from jsonb_array_elements(p->'lines') l
  ),
  inserted as (
    insert into public.sales_lines (import_id, sold_at, sale_date, raw_item_name, product_id, quantity,
                                    unit_price_cents, total_cents, payment_type, transaction_ref, fingerprint)
    select v_id, sold_at, sale_date, raw_item_name, product_id, quantity,
           unit_price_cents, total_cents, payment_type, transaction_ref, fingerprint
    from incoming
    on conflict (fingerprint) do nothing
    returning product_id, sale_date
  )
  select count(*)::int,
         coalesce(jsonb_agg(distinct jsonb_build_object('product_id', product_id, 'sale_date', sale_date))
                  filter (where product_id is not null), '[]'::jsonb)
  into v_inserted, v_pairs
  from inserted;

  if v_inserted = 0 then
    -- Everything was a duplicate: don't keep an empty import in the history.
    delete from public.sales_imports where id = v_id;
    raise exception 'ALL_DUPLICATES' using hint = 'Every sale in this file was already imported. Nothing was added.';
  end if;

  perform public.reconcile_pairs(v_pairs);

  update public.sales_imports si set
    imported_count  = v_inserted,
    duplicate_count = v_total - v_inserted,
    date_from       = (select min(sale_date) from public.sales_lines where import_id = v_id),
    date_to         = (select max(sale_date) from public.sales_lines where import_id = v_id),
    revenue_cents   = (select coalesce(sum(total_cents), 0) from public.sales_lines where import_id = v_id)
  where si.id = v_id;

  return jsonb_build_object(
    'import_id', v_id,
    'imported', v_inserted,
    'duplicates', v_total - v_inserted,
    'unmatched', (select count(*) from public.sales_lines where import_id = v_id and product_id is null)
  );
end;
$$;


-- -----------------------------------------------------------------------------
-- undo_import
-- -----------------------------------------------------------------------------
-- Deletes the import's sales lines (so the same file can be imported again
-- later), keeps the import in the history marked "undone", and fixes stock.
create or replace function public.undo_import(p_import_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_pairs jsonb;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;
  if not exists (select 1 from public.sales_imports where id = p_import_id and undone_at is null) then
    raise exception 'NOT_FOUND' using hint = 'That import was already undone or doesn''t exist.';
  end if;

  select coalesce(jsonb_agg(distinct jsonb_build_object('product_id', product_id, 'sale_date', sale_date))
                  filter (where product_id is not null), '[]'::jsonb)
    into v_pairs
  from public.sales_lines where import_id = p_import_id;

  delete from public.sales_lines where import_id = p_import_id;

  update public.sales_imports
     set undone_at = now(), undone_by = auth.uid()
   where id = p_import_id;

  perform public.reconcile_pairs(v_pairs);
end;
$$;


-- -----------------------------------------------------------------------------
-- link_item_name
-- -----------------------------------------------------------------------------
-- Links every past sale with this InTouchPay item name to a product,
-- remembers the name for future imports, and fixes stock for those days.
create or replace function public.link_item_name(p_raw_name text, p_product_id uuid)
returns int
language plpgsql security definer
set search_path = public
as $$
declare
  v_pairs jsonb;
  v_count int;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;

  insert into public.product_aliases (product_id, alias)
  values (p_product_id, lower(btrim(p_raw_name)))
  on conflict (alias) do update set product_id = excluded.product_id;

  with changed as (
    update public.sales_lines
       set product_id = p_product_id
     where product_id is null
       and lower(btrim(raw_item_name)) = lower(btrim(p_raw_name))
    returning product_id, sale_date
  )
  select count(*)::int,
         coalesce(jsonb_agg(distinct jsonb_build_object('product_id', product_id, 'sale_date', sale_date)), '[]'::jsonb)
    into v_count, v_pairs
  from changed;

  perform public.reconcile_pairs(v_pairs);
  return v_count;
end;
$$;


-- Item names in imported sales that aren't linked to a product yet.
create or replace function public.unmatched_item_names()
returns table (raw_item_name text, lines int, units int, revenue_cents int, last_sold date)
language sql stable security definer
set search_path = public
as $$
  select min(raw_item_name), count(*)::int, sum(quantity)::int, sum(total_cents)::int, max(sale_date)
  from public.sales_lines
  where product_id is null and public.is_admin()
  group by lower(btrim(raw_item_name))
  order by sum(total_cents) desc;
$$;


-- Fingerprints already in the database (for the "already imported" count in the preview).
create or replace function public.existing_fingerprints(p_fingerprints text[])
returns setof text
language sql stable security definer
set search_path = public
as $$
  select fingerprint from public.sales_lines
  where fingerprint = any(p_fingerprints) and public.is_admin();
$$;


revoke execute on function public.reconcile_pairs(jsonb)          from public, anon, authenticated;
revoke execute on function public.import_sales(jsonb)             from public, anon;
revoke execute on function public.undo_import(uuid)               from public, anon;
revoke execute on function public.link_item_name(text, uuid)      from public, anon;
revoke execute on function public.unmatched_item_names()          from public, anon;
revoke execute on function public.existing_fingerprints(text[])   from public, anon;
grant  execute on function public.import_sales(jsonb)             to authenticated;
grant  execute on function public.undo_import(uuid)               to authenticated;
grant  execute on function public.link_item_name(text, uuid)      to authenticated;
grant  execute on function public.unmatched_item_names()          to authenticated;
grant  execute on function public.existing_fingerprints(text[])   to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000008_insights.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- School Store — numbers for the Insights page (phase 6)
-- =============================================================================
-- insights(from, to, bucket) returns everything the page shows for one date
-- range, as JSON. `bucket` ('day', 'week' or 'month') sets the size of each
-- bar in the trend chart.
--
-- Where each number comes from:
--   revenue     imported InTouchPay sales (online orders are included, since
--               they're rung up at pickup)
--   spending    shopping trips (expenses)
--   profit      revenue − spending (cash in minus cash out for the range)
--   gross profit  per product: revenue − units sold × the product's cost
--   units paid  stock that left because it was paid for (online pickups +
--               imported in-person sales), from the stock history
-- =============================================================================

create or replace function public.insights(p_from date, p_to date, p_bucket text default 'week')
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_days       int := p_to - p_from + 1;
  v_prev_from  date := p_from - (p_to - p_from + 1);
  v_prev_to    date := p_from - 1;
  v_bucket     text := case when p_bucket in ('day', 'week', 'month') then p_bucket else 'week' end;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;
  if p_from is null or p_to is null or p_to < p_from then
    raise exception 'BAD_RANGE' using hint = 'Choose a start date before the end date.';
  end if;
  if v_days > 1100 then
    raise exception 'BAD_RANGE' using hint = 'Choose a range of three years or less.';
  end if;

  return jsonb_build_object(
    'from', p_from,
    'to', p_to,
    'bucket', v_bucket,

    -- ---- Headline numbers, this range and the one before it ----
    'totals', (
      select jsonb_build_object(
        'revenue_cents',      (select coalesce(sum(total_cents), 0) from sales_lines where sale_date between p_from and p_to),
        'spending_cents',     (select coalesce(sum(total_cents), 0) from expenses where purchased_on between p_from and p_to),
        'gross_profit_cents', (select coalesce(sum(sl.total_cents - sl.quantity * p.unit_cost_cents), 0)
                               from sales_lines sl join products p on p.id = sl.product_id
                               where sl.sale_date between p_from and p_to),
        'transactions',       (select count(distinct coalesce(transaction_ref, id::text)) from sales_lines where sale_date between p_from and p_to),
        'units_sold',         (select coalesce(sum(quantity), 0) from sales_lines where sale_date between p_from and p_to),
        'online_orders',      (select count(distinct source_id) from stock_movements
                               where reason = 'online_pickup' and effective_date between p_from and p_to),
        'last_sale_date',     (select max(sale_date) from sales_lines)
      )
    ),
    'previous', (
      select jsonb_build_object(
        'from', v_prev_from,
        'to', v_prev_to,
        'revenue_cents',  (select coalesce(sum(total_cents), 0) from sales_lines where sale_date between v_prev_from and v_prev_to),
        'spending_cents', (select coalesce(sum(total_cents), 0) from expenses where purchased_on between v_prev_from and v_prev_to),
        'gross_profit_cents', (select coalesce(sum(sl.total_cents - sl.quantity * p.unit_cost_cents), 0)
                               from sales_lines sl join products p on p.id = sl.product_id
                               where sl.sale_date between v_prev_from and v_prev_to),
        'units_sold',     (select coalesce(sum(quantity), 0) from sales_lines where sale_date between v_prev_from and v_prev_to)
      )
    ),

    -- ---- Trend: one row per day / week / month ----
    'series', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'start', b.start,
               'revenue_cents', coalesce(r.cents, 0),
               'spending_cents', coalesce(e.cents, 0)) order by b.start), '[]'::jsonb)
      from (
        -- A bar never starts before the range (e.g. October's first week starts Oct 1).
        select distinct greatest(date_trunc(v_bucket, d)::date, p_from) as start
        from generate_series(p_from, p_to, interval '1 day') d
      ) b
      left join (
        select greatest(date_trunc(v_bucket, sale_date)::date, p_from) as start, sum(total_cents) as cents
        from sales_lines where sale_date between p_from and p_to group by 1
      ) r on r.start = b.start
      left join (
        select greatest(date_trunc(v_bucket, purchased_on)::date, p_from) as start, sum(total_cents) as cents
        from expenses where purchased_on between p_from and p_to group by 1
      ) e on e.start = b.start
    ),

    -- ---- How people paid ----
    'payments', (
      select coalesce(jsonb_object_agg(payment_type, cents), '{}'::jsonb)
      from (select payment_type, sum(total_cents) as cents from sales_lines
            where sale_date between p_from and p_to group by 1) t
    ),

    -- ---- Online vs in person, in units paid for ----
    'channels', (
      select jsonb_build_object(
        'online_units',  coalesce(-sum(change) filter (where reason in ('online_pickup', 'online_pickup_undo')), 0),
        'total_units',   coalesce(-sum(change), 0)
      )
      from stock_movements
      where reason in ('online_pickup', 'online_pickup_undo', 'sale_import')
        and effective_date between p_from and p_to
    ),

    -- ---- Spending by store ----
    'suppliers', (
      select coalesce(jsonb_agg(jsonb_build_object('name', name, 'cents', cents, 'trips', trips) order by cents desc), '[]'::jsonb)
      from (
        select coalesce(s.name, 'No store') as name, sum(e.total_cents) as cents, count(*) as trips
        from expenses e left join suppliers s on s.id = e.supplier_id
        where e.purchased_on between p_from and p_to
        group by 1
      ) t
    ),

    -- ---- Every product: units, revenue, margin, sell-through ----
    'products', (
      select coalesce(jsonb_agg(row_to_json(t) order by t.revenue_cents desc, t.name), '[]'::jsonb)
      from (
        select
          p.id, p.name, p.category, p.emoji, p.archived,
          p.price_cents, p.unit_cost_cents, p.stock,
          coalesce(s.units, 0)::int as units,
          coalesce(s.revenue, 0)::int as revenue_cents,
          (coalesce(s.revenue, 0) - coalesce(s.units, 0) * p.unit_cost_cents)::int as gross_profit_cents,
          -- Stock before the range, plus what was bought during it = what was available to sell.
          coalesce((select sum(change) from stock_movements m
                    where m.product_id = p.id and m.effective_date < p_from), 0)::int as start_stock,
          coalesce((select sum(change) from stock_movements m
                    where m.product_id = p.id and m.reason = 'restock'
                      and m.effective_date between p_from and p_to), 0)::int as restocked,
          coalesce((select -sum(change) from stock_movements m
                    where m.product_id = p.id
                      and m.reason in ('sale_import', 'online_pickup', 'online_pickup_undo')
                      and m.effective_date between p_from and p_to), 0)::int as units_paid
        from products p
        left join (
          select product_id, sum(quantity) as units, sum(total_cents) as revenue
          from sales_lines where sale_date between p_from and p_to and product_id is not null
          group by product_id
        ) s on s.product_id = p.id
        where not p.archived or s.units is not null
      ) t
    ),

    -- Sales that aren't linked to a product (they count in revenue only).
    'unmatched_revenue_cents', (
      select coalesce(sum(total_cents), 0) from sales_lines
      where sale_date between p_from and p_to and product_id is null
    )
  );
end;
$$;

revoke execute on function public.insights(date, date, text) from public, anon;
grant  execute on function public.insights(date, date, text) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261026000009_rewards_deals.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- Firebirds Nest — rewards accounts, deals and bundles (phase 8)
-- =============================================================================
-- What this adds:
--   customers        students who made a rewards account (signed in by email code)
--   point_entries    the points ledger: every point earned, spent, refunded or adjusted
--   rewards          what points can buy (always "a free <product>")
--   promotions       sale prices and "buy X, get Y free" deals, each with dates
--   bundles          several products sold together at one price
--   order_bundles,
--   order_discounts  what an order's bundles and discounts were
--
-- How points work:
--   * A signed-in student earns points on an online order when staff mark it
--     Picked up (settings.points_per_dollar for each $1 paid).
--   * Using a reward takes the points right away; if the order ends up
--     canceled, a no-show or expired, they're refunded automatically.
--   * sync_order_points() keeps the ledger matching each order's status — the
--     same "compare and fix the difference" idea as the stock ledger.
--
-- How prices work (_price_cart):
--   1. Each product costs its sale price if a sale is running, else its price.
--   2. Bundles cost the bundle price.
--   3. Buy-X-get-Y deals make the cheapest qualifying items free.
--   4. A reward adds one free item.
--   Members-only sales, deals and bundles only count for signed-in students.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. Settings
-- -----------------------------------------------------------------------------
alter table public.settings
  add column rewards_enabled   boolean not null default true,
  add column points_per_dollar int     not null default 10 check (points_per_dollar between 1 and 100);


-- -----------------------------------------------------------------------------
-- 2. Rewards accounts and points
-- -----------------------------------------------------------------------------
create table public.customers (
  id          uuid primary key references auth.users (id) on delete cascade,
  email       text not null,
  first_name  text not null check (char_length(first_name) between 1 and 40),
  last_name   text not null check (char_length(last_name)  between 1 and 40),
  grade       text not null check (char_length(grade) between 1 and 20),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create table public.rewards (
  id           uuid primary key default gen_random_uuid(),
  product_id   uuid not null references public.products (id) on delete cascade,
  points_cost  int  not null check (points_cost between 1 and 100000),
  active       boolean not null default true,
  created_at   timestamptz not null default now()
);

create type public.points_reason as enum (
  'earned',       -- order picked up
  'earned_undo',  -- order moved back from Picked up
  'redeemed',     -- points spent on a reward
  'refunded',     -- reward order canceled / not picked up
  'adjusted'      -- added or removed by staff
);

create table public.point_entries (
  id            bigint generated always as identity primary key,
  customer_id   uuid not null references public.customers (id) on delete cascade,
  change        int  not null check (change <> 0),
  reason        public.points_reason not null,
  order_id      uuid references public.orders (id) on delete set null,
  order_number  int,  -- kept even after old orders are deleted
  note          text,
  created_by    uuid references auth.users (id) on delete set null,
  created_at    timestamptz not null default now()
);
create index on public.point_entries (customer_id, created_at desc);
create index on public.point_entries (order_id);


-- -----------------------------------------------------------------------------
-- 3. Deals and bundles
-- -----------------------------------------------------------------------------
create table public.promotions (
  id                uuid primary key default gen_random_uuid(),
  kind              text not null check (kind in ('sale', 'buy_get')),
  title             text not null check (char_length(title) between 1 and 60),
  product_id        uuid references public.products (id) on delete cascade,
  category          text,           -- buy_get deals can cover a whole category
  sale_price_cents  int  check (sale_price_cents >= 0),
  buy_qty           int  check (buy_qty between 1 and 20),
  get_qty           int  check (get_qty between 1 and 20),
  starts_on         date not null,
  ends_on           date not null,
  members_only      boolean not null default false,
  featured          boolean not null default false,  -- "deal of the day": shown at the top of the menu
  active            boolean not null default true,
  created_at        timestamptz not null default now(),
  check (ends_on >= starts_on),
  check (
    (kind = 'sale' and product_id is not null and sale_price_cents is not null and category is null)
    or
    (kind = 'buy_get' and buy_qty is not null and get_qty is not null
       and ((product_id is null) <> (category is null)))
  )
);
create index on public.promotions (starts_on, ends_on);

create table public.bundles (
  id            uuid primary key default gen_random_uuid(),
  name          text not null check (char_length(name) between 1 and 60),
  description   text check (char_length(description) <= 200),
  emoji         text,
  photo_path    text,
  price_cents   int  not null check (price_cents >= 0),
  starts_on     date,   -- empty = no start date
  ends_on       date,   -- empty = no end date
  members_only  boolean not null default false,
  active        boolean not null default true,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  check (ends_on is null or starts_on is null or ends_on >= starts_on)
);

create table public.bundle_items (
  bundle_id   uuid not null references public.bundles (id) on delete cascade,
  product_id  uuid not null references public.products (id) on delete cascade,
  quantity    int  not null default 1 check (quantity between 1 and 20),
  primary key (bundle_id, product_id)
);


-- -----------------------------------------------------------------------------
-- 4. Orders remember bundles, discounts and points
-- -----------------------------------------------------------------------------
alter table public.orders
  add column customer_id     uuid references public.customers (id) on delete set null,
  add column subtotal_cents  int not null default 0 check (subtotal_cents >= 0),
  add column discount_cents  int not null default 0 check (discount_cents >= 0),
  add column points_earned   int not null default 0 check (points_earned >= 0),
  add column points_spent    int not null default 0 check (points_spent >= 0);
update public.orders set subtotal_cents = total_cents;
create index on public.orders (customer_id, created_at desc);

create table public.order_bundles (
  id                uuid primary key default gen_random_uuid(),
  order_id          uuid not null references public.orders (id) on delete cascade,
  bundle_id         uuid references public.bundles (id) on delete set null,
  bundle_name       text not null,
  unit_price_cents  int  not null check (unit_price_cents >= 0),
  quantity          int  not null check (quantity > 0)
);
create index on public.order_bundles (order_id);

-- A bundle's products are normal order_items rows (so stock, reservations and
-- the prep list just work) with a price of 0 and a link to the bundle line.
alter table public.order_items
  add column order_bundle_id uuid references public.order_bundles (id) on delete cascade;

create table public.order_discounts (
  id            uuid primary key default gen_random_uuid(),
  order_id      uuid not null references public.orders (id) on delete cascade,
  label         text not null,
  amount_cents  int  not null check (amount_cents > 0),
  kind          text not null check (kind in ('buy_get', 'reward'))
);
create index on public.order_discounts (order_id);


-- -----------------------------------------------------------------------------
-- 5. Helpers
-- -----------------------------------------------------------------------------

-- Is a deal running on this day for this shopper?
create or replace function public.deal_is_live(
  p_active boolean, p_starts date, p_ends date, p_members_only boolean, p_day date, p_member boolean)
returns boolean
language sql immutable
as $$
  select p_active
     and (p_starts is null or p_day >= p_starts)
     and (p_ends   is null or p_day <= p_ends)
     and (not p_members_only or p_member);
$$;

create or replace function public.points_balance(p_customer_id uuid)
returns int
language sql stable security definer
set search_path = public
as $$
  select coalesce(sum(change), 0)::int from public.point_entries where customer_id = p_customer_id;
$$;

-- How many of a product can still be ordered (stock − reserved, never below 0).
create or replace function public.product_available(p_product_id uuid)
returns int
language sql stable security definer
set search_path = public
as $$
  select greatest(p.stock - coalesce(r.reserved, 0), 0)::int
  from public.products p
  left join public.product_reserved r on r.product_id = p.id
  where p.id = p_product_id;
$$;


-- -----------------------------------------------------------------------------
-- 6. Pricing
-- -----------------------------------------------------------------------------
-- p_items:   [{"product_id": "...", "quantity": 2}, ...]
-- p_bundles: [{"bundle_id": "...", "quantity": 1}, ...]
-- Returns the priced cart as JSON (see the end of the function).
-- Doesn't check stock — place_order does that.
create or replace function public._price_cart(
  p_items jsonb, p_bundles jsonb, p_member boolean, p_reward_id uuid)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_day        date := public.store_today();
  v_bundles    jsonb := '[]'::jsonb;
  v_discounts  jsonb := '[]'::jsonb;
  v_reward     jsonb := null;
  v_subtotal   int;
  v_discount   int := 0;
  v_promo      record;
  v_rw         record;
  v_count      int;
  v_free       int;
  v_amount     int;
begin
  -- ---- Products ------------------------------------------------------------
  drop table if exists _pc_lines;
  create temporary table _pc_lines on commit drop as
    select (x->>'product_id')::uuid as product_id, sum((x->>'quantity')::int)::int as quantity
    from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) as x
    group by 1;

  if exists (select 1 from _pc_lines where product_id is null or quantity is null or quantity < 1 or quantity > 100) then
    raise exception 'BAD_QUANTITY' using hint = 'Each item needs a quantity of at least 1.';
  end if;
  if exists (select 1 from _pc_lines l left join public.products p on p.id = l.product_id
             where p.id is null or p.archived or not p.available_online) then
    raise exception 'UNAVAILABLE' using hint = 'An item in your cart is no longer available. Please refresh the menu.';
  end if;

  -- Each line's price: the lowest running sale price, or the normal price.
  drop table if exists _pc_priced;
  create temporary table _pc_priced on commit drop as
    select l.product_id, p.name, p.category, l.quantity,
           p.price_cents as regular_price_cents,
           least(p.price_cents, coalesce(s.sale_price_cents, p.price_cents)) as unit_price_cents,
           s.title as deal_title,
           false as is_reward
    from _pc_lines l
    join public.products p on p.id = l.product_id
    left join lateral (
      select pm.sale_price_cents, pm.title
      from public.promotions pm
      where pm.kind = 'sale' and pm.product_id = p.id
        and public.deal_is_live(pm.active, pm.starts_on, pm.ends_on, pm.members_only, v_day, p_member)
      order by pm.sale_price_cents
      limit 1
    ) s on true;

  -- ---- Reward (one free item) ----------------------------------------------
  if p_reward_id is not null then
    if not p_member then
      raise exception 'SIGN_IN_NEEDED' using hint = 'Sign in to your rewards account to use a reward.';
    end if;
    select rw.id, rw.points_cost, p.id as product_id, p.name, p.category, p.price_cents,
           least(p.price_cents, coalesce((
             select min(pm.sale_price_cents) from public.promotions pm
             where pm.kind = 'sale' and pm.product_id = p.id
               and public.deal_is_live(pm.active, pm.starts_on, pm.ends_on, pm.members_only, v_day, p_member)
           ), p.price_cents)) as unit_price_cents
      into v_rw
      from public.rewards rw
      join public.products p on p.id = rw.product_id
     where rw.id = p_reward_id and rw.active and not p.archived and p.available_online;
    if not found then
      raise exception 'REWARD_UNAVAILABLE' using hint = 'That reward isn''t available right now.';
    end if;

    insert into _pc_priced values (v_rw.product_id, v_rw.name, v_rw.category, 1,
                                   v_rw.price_cents, v_rw.unit_price_cents, null, true);
    v_reward := jsonb_build_object('id', v_rw.id, 'product_id', v_rw.product_id,
                                   'name', v_rw.name, 'points_cost', v_rw.points_cost);
    if v_rw.unit_price_cents > 0 then
      v_discounts := v_discounts || jsonb_build_object(
        'label', 'Reward: free ' || v_rw.name, 'amount_cents', v_rw.unit_price_cents, 'kind', 'reward');
    end if;
  end if;

  -- ---- Bundles ---------------------------------------------------------------
  drop table if exists _pc_bundles;
  create temporary table _pc_bundles on commit drop as
    select (x->>'bundle_id')::uuid as bundle_id, sum((x->>'quantity')::int)::int as quantity
    from jsonb_array_elements(coalesce(p_bundles, '[]'::jsonb)) as x
    group by 1;

  if exists (select 1 from _pc_bundles where bundle_id is null or quantity is null or quantity < 1 or quantity > 20) then
    raise exception 'BAD_QUANTITY' using hint = 'Each bundle needs a quantity of at least 1.';
  end if;
  if exists (
    select 1 from _pc_bundles pb
    left join public.bundles b on b.id = pb.bundle_id
    where b.id is null
       or not public.deal_is_live(b.active, b.starts_on, b.ends_on, b.members_only, v_day, p_member)
       or not exists (select 1 from public.bundle_items bi where bi.bundle_id = b.id)
       or exists (select 1 from public.bundle_items bi join public.products p on p.id = bi.product_id
                  where bi.bundle_id = b.id and (p.archived or not p.available_online))
  ) then
    raise exception 'BUNDLE_UNAVAILABLE' using hint = 'A bundle in your cart isn''t available right now. Please refresh the menu.';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'bundle_id', b.id,
           'name', b.name,
           'quantity', pb.quantity,
           'unit_price_cents', b.price_cents,
           'items', (select jsonb_agg(jsonb_build_object('product_id', p.id, 'name', p.name, 'quantity', bi.quantity)
                                      order by p.name)
                     from public.bundle_items bi join public.products p on p.id = bi.product_id
                     where bi.bundle_id = b.id))
         order by b.name), '[]'::jsonb)
    into v_bundles
    from _pc_bundles pb join public.bundles b on b.id = pb.bundle_id;

  -- ---- Buy X, get Y ----------------------------------------------------------
  -- One row per single item (not counting the reward or bundles). An item can
  -- only be used by one deal.
  drop table if exists _pc_units;
  create temporary table _pc_units on commit drop as
    select p.product_id, p.category, p.unit_price_cents, false as used
    from _pc_priced p
    cross join lateral generate_series(1, p.quantity)
    where not p.is_reward;

  for v_promo in
    select * from public.promotions pm
    where pm.kind = 'buy_get'
      and public.deal_is_live(pm.active, pm.starts_on, pm.ends_on, pm.members_only, v_day, p_member)
    order by pm.created_at
  loop
    select count(*) into v_count from _pc_units u
     where not u.used and (u.product_id = v_promo.product_id or u.category = v_promo.category);

    -- Every full group of (buy + get) items makes `get` of them free.
    v_free := (v_count / (v_promo.buy_qty + v_promo.get_qty)) * v_promo.get_qty;
    if v_free > 0 then
      select coalesce(sum(unit_price_cents), 0) into v_amount
      from (select u.unit_price_cents from _pc_units u
            where not u.used and (u.product_id = v_promo.product_id or u.category = v_promo.category)
            order by u.unit_price_cents
            limit v_free) cheapest;

      update _pc_units u set used = true
       where not u.used and (u.product_id = v_promo.product_id or u.category = v_promo.category);

      if v_amount > 0 then
        v_discounts := v_discounts || jsonb_build_object(
          'label', v_promo.title, 'amount_cents', v_amount, 'kind', 'buy_get');
      end if;
    end if;
  end loop;

  -- ---- Totals ----------------------------------------------------------------
  select coalesce(sum(unit_price_cents * quantity), 0)::int into v_subtotal from _pc_priced;
  select v_subtotal + coalesce(sum((b->>'unit_price_cents')::int * (b->>'quantity')::int), 0)::int
    into v_subtotal from jsonb_array_elements(v_bundles) b;
  select coalesce(sum((d->>'amount_cents')::int), 0)::int into v_discount from jsonb_array_elements(v_discounts) d;
  v_discount := least(v_discount, v_subtotal);

  return jsonb_build_object(
    'lines', coalesce((select jsonb_agg(jsonb_build_object(
                         'product_id', product_id,
                         'name', name,
                         'quantity', quantity,
                         'regular_price_cents', regular_price_cents,
                         'unit_price_cents', unit_price_cents,
                         'deal_title', deal_title,
                         'is_reward', is_reward) order by is_reward, name)
                       from _pc_priced), '[]'::jsonb),
    'bundles', v_bundles,
    'discounts', v_discounts,
    'reward', v_reward,
    'subtotal_cents', v_subtotal,
    'discount_cents', v_discount,
    'total_cents', v_subtotal - v_discount
  );
end;
$$;

-- Is this signed-in user a member (has finished their rewards profile)?
create or replace function public.current_member()
returns uuid
language sql stable security definer
set search_path = public
as $$
  select id from public.customers where id = auth.uid();
$$;

-- Public: price a cart for the checkout page (members get member prices).
create or replace function public.quote_cart(p_items jsonb, p_bundles jsonb default '[]', p_reward_id uuid default null)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  s         public.settings;
  v_member  uuid := public.current_member();
  v_quote   jsonb;
  v_total   int;
  v_balance int := 0;
  v_points  int;
begin
  select * into s from public.settings where id = 1;
  v_quote := public._price_cart(p_items, p_bundles, v_member is not null, p_reward_id);
  v_total := (v_quote->>'total_cents')::int;
  v_points := case when s.rewards_enabled then floor(v_total * s.points_per_dollar / 100.0)::int else 0 end;

  if v_member is not null then
    v_balance := public.points_balance(v_member);
    if v_quote->'reward' <> 'null'::jsonb and v_balance < (v_quote->'reward'->>'points_cost')::int then
      raise exception 'NOT_ENOUGH_POINTS' using hint = 'You don''t have enough points for that reward yet.';
    end if;
  end if;

  return v_quote || jsonb_build_object(
    'member', v_member is not null,
    'points_balance', v_balance,
    'points_earned', case when v_member is not null then v_points else 0 end,
    'points_if_member', v_points
  );
end;
$$;


-- -----------------------------------------------------------------------------
-- 7. Points follow the order's status
-- -----------------------------------------------------------------------------
-- Run after any status change. Safe to run any number of times.
create or replace function public.sync_order_points(p_order_id uuid)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  o          public.orders;
  v_target   int;
  v_current  int;
begin
  select * into o from public.orders where id = p_order_id;
  if not found or o.customer_id is null then
    return;
  end if;

  -- Spent points: taken while the order is open or picked up, refunded otherwise.
  v_target := case when o.status in ('canceled', 'no_show', 'expired') then 0 else o.points_spent end;
  select coalesce(-sum(change), 0) into v_current from public.point_entries
   where order_id = o.id and reason in ('redeemed', 'refunded');
  if v_target <> v_current then
    insert into public.point_entries (customer_id, change, reason, order_id, order_number, note)
    values (o.customer_id, -(v_target - v_current),
            case when v_target > v_current then 'redeemed' else 'refunded' end::public.points_reason,
            o.id, o.order_number,
            case when v_target > v_current then 'Used on a reward' else 'Order wasn''t picked up' end);
  end if;

  -- Earned points: only once the order is picked up (paid).
  v_target := case when o.status = 'picked_up' then o.points_earned else 0 end;
  select coalesce(sum(change), 0) into v_current from public.point_entries
   where order_id = o.id and reason in ('earned', 'earned_undo');
  if v_target <> v_current then
    insert into public.point_entries (customer_id, change, reason, order_id, order_number, note)
    values (o.customer_id, v_target - v_current,
            case when v_target > v_current then 'earned' else 'earned_undo' end::public.points_reason,
            o.id, o.order_number,
            case when v_target > v_current then 'Order picked up' else 'Pickup undone' end);
  end if;
end;
$$;


-- -----------------------------------------------------------------------------
-- 8. place_order, now with bundles, deals, rewards and members
-- -----------------------------------------------------------------------------
drop function if exists public.place_order(text, text, text, int, date, jsonb, text);

create or replace function public.place_order(
  p_first_name       text,
  p_last_name        text,
  p_grade            text,
  p_pickup_window_id int,
  p_pickup_date      date,
  p_items            jsonb,
  p_ip_hash          text,
  p_bundles          jsonb default '[]',
  p_customer_id      uuid  default null,  -- set by the website server after checking the sign-in
  p_reward_id        uuid  default null
)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  s            public.settings;
  w            public.pickup_windows;
  v_today      date := public.store_today();
  v_now        time := public.store_now_time();
  v_first      text := btrim(coalesce(p_first_name, ''));
  v_last       text := btrim(coalesce(p_last_name, ''));
  v_grade      text := btrim(coalesce(p_grade, ''));
  v_member     boolean := false;
  v_price      jsonb;
  v_item       record;
  v_bundle     jsonb;
  v_ob_id      uuid;
  v_product    public.products;
  v_available  int;
  v_count      int;
  v_total      int;
  v_spent      int := 0;
  v_earned     int := 0;
  v_order      public.orders;
begin
  select * into s from public.settings where id = 1;

  -- ---- Who is ordering --------------------------------------------------------
  if v_first = '' or v_last = '' or v_grade = '' then
    raise exception 'MISSING_INFO' using hint = 'Please fill in your first name, last name, and grade.';
  end if;
  if char_length(v_first) > 40 or char_length(v_last) > 40 or char_length(v_grade) > 20 then
    raise exception 'INFO_TOO_LONG' using hint = 'One of your answers is too long.';
  end if;
  if p_customer_id is not null then
    v_member := exists (select 1 from public.customers where id = p_customer_id);
    if not v_member then
      raise exception 'PROFILE_NEEDED' using hint = 'Finish setting up your rewards account first.';
    end if;
  end if;

  -- ---- When -------------------------------------------------------------------
  if p_pickup_date is null
     or p_pickup_date not in (v_today, public.next_open_day(v_today)) then
    raise exception 'BAD_DATE' using hint = 'Orders can only be placed for today or the next school day.';
  end if;
  if not public.is_open_day(p_pickup_date) then
    raise exception 'STORE_CLOSED' using hint = 'The store is closed that day.';
  end if;

  select * into w from public.pickup_windows where id = p_pickup_window_id and active;
  if not found then
    raise exception 'BAD_WINDOW' using hint = 'Please choose a pickup time.';
  end if;

  if p_pickup_date = v_today then
    if v_now >= s.order_cutoff_time then
      raise exception 'ORDERS_CLOSED' using hint = format(
        'Same-day orders close at %s. You can still order for the next school day.',
        to_char(s.order_cutoff_time, 'FMHH12:MI AM'));
    end if;
    if v_now >= w.starts_at - make_interval(mins => s.order_lead_minutes) then
      raise exception 'WINDOW_CLOSED' using hint = format(
        'It''s too late to order for %s today. Please pick a later time.', w.label);
    end if;
  end if;

  -- ---- Prank protection ---------------------------------------------------------
  select count(*) into v_count
  from public.orders
  where pickup_date = p_pickup_date
    and lower(first_name) = lower(v_first)
    and lower(last_name)  = lower(v_last)
    and status not in ('canceled');
  if v_count >= s.max_orders_per_student_day then
    raise exception 'STUDENT_LIMIT' using hint = format(
      'You already have %s order(s) for that day, which is the limit.', v_count);
  end if;

  if p_ip_hash is not null then
    select count(*) into v_count
    from public.orders
    where ip_hash = p_ip_hash and created_at > now() - interval '1 hour';
    if v_count >= s.max_orders_per_hour_per_device then
      raise exception 'RATE_LIMIT' using hint = 'Too many orders from this device. Please try again later.';
    end if;
  end if;

  -- ---- What -------------------------------------------------------------------
  if coalesce(jsonb_array_length(case when jsonb_typeof(p_items) = 'array' then p_items end), 0)
     + coalesce(jsonb_array_length(case when jsonb_typeof(p_bundles) = 'array' then p_bundles end), 0) = 0
     and p_reward_id is null then
    raise exception 'EMPTY_CART' using hint = 'Your cart is empty.';
  end if;

  v_price := public._price_cart(p_items, p_bundles, v_member, p_reward_id);

  -- Every single product needed, counting what's inside bundles.
  drop table if exists _need;
  create temporary table _need on commit drop as
    select product_id, sum(qty)::int as quantity from (
      select (l->>'product_id')::uuid as product_id, (l->>'quantity')::int as qty
      from jsonb_array_elements(v_price->'lines') l
      union all
      select (i->>'product_id')::uuid, (i->>'quantity')::int * (b->>'quantity')::int
      from jsonb_array_elements(v_price->'bundles') b, jsonb_array_elements(b->'items') i
    ) t
    group by product_id;

  if (select sum(quantity) from _need) > s.max_items_per_order then
    raise exception 'TOO_MANY_ITEMS' using hint = format(
      'Orders are limited to %s items (bundles count each item inside).', s.max_items_per_order);
  end if;

  -- Lock each product (in a fixed order to avoid deadlocks) and check stock.
  for v_item in select * from _need order by product_id loop
    select * into v_product from public.products where id = v_item.product_id for update;
    v_available := public.product_available(v_product.id);
    if v_available < v_item.quantity then
      raise exception 'SOLD_OUT' using hint = case
        when v_available <= 0 then format('%s just sold out.', v_product.name)
        else format('Only %s %s left.', v_available, v_product.name) end;
    end if;
  end loop;

  -- ---- Rewards points ---------------------------------------------------------
  if v_price->'reward' <> 'null'::jsonb then
    -- Lock the member so two orders at once can't spend the same points.
    perform 1 from public.customers where id = p_customer_id for update;
    v_spent := (v_price->'reward'->>'points_cost')::int;
    if public.points_balance(p_customer_id) < v_spent then
      raise exception 'NOT_ENOUGH_POINTS' using hint = 'You don''t have enough points for that reward yet.';
    end if;
  end if;

  v_total := (v_price->>'total_cents')::int;
  if v_member and s.rewards_enabled then
    v_earned := floor(v_total * s.points_per_dollar / 100.0)::int;
  end if;

  -- ---- Save it ------------------------------------------------------------------
  insert into public.orders (first_name, last_name, grade, pickup_window_id, pickup_date, ip_hash, customer_id,
                             subtotal_cents, discount_cents, total_cents, points_earned, points_spent)
  values (v_first, v_last, v_grade, w.id, p_pickup_date, p_ip_hash, p_customer_id,
          (v_price->>'subtotal_cents')::int, (v_price->>'discount_cents')::int, v_total, v_earned, v_spent)
  returning * into v_order;

  insert into public.order_items (order_id, product_id, product_name, unit_price_cents, quantity)
  select v_order.id, (l->>'product_id')::uuid, l->>'name', (l->>'unit_price_cents')::int, (l->>'quantity')::int
  from jsonb_array_elements(v_price->'lines') l;

  for v_bundle in select * from jsonb_array_elements(v_price->'bundles') loop
    insert into public.order_bundles (order_id, bundle_id, bundle_name, unit_price_cents, quantity)
    values (v_order.id, (v_bundle->>'bundle_id')::uuid, v_bundle->>'name',
            (v_bundle->>'unit_price_cents')::int, (v_bundle->>'quantity')::int)
    returning id into v_ob_id;

    insert into public.order_items (order_id, product_id, product_name, unit_price_cents, quantity, order_bundle_id)
    select v_order.id, (i->>'product_id')::uuid, i->>'name', 0,
           (i->>'quantity')::int * (v_bundle->>'quantity')::int, v_ob_id
    from jsonb_array_elements(v_bundle->'items') i;
  end loop;

  insert into public.order_discounts (order_id, label, amount_cents, kind)
  select v_order.id, d->>'label', (d->>'amount_cents')::int, d->>'kind'
  from jsonb_array_elements(v_price->'discounts') d;

  perform public.sync_order_points(v_order.id);  -- takes the reward's points

  return jsonb_build_object(
    'order_number',  v_order.order_number,
    'pickup_date',   v_order.pickup_date,
    'pickup_window', w.label,
    'total_cents',   v_total,
    'points_earned', v_earned,
    'points_spent',  v_spent
  );
end;
$$;


-- -----------------------------------------------------------------------------
-- 9. Status changes now keep points in sync too
-- -----------------------------------------------------------------------------
create or replace function public.set_order_status(p_order_id uuid, p_status public.order_status)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_order public.orders;
  v_day   date := public.store_today();
  v_item  record;
  v_ref   text;
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'NOT_FOUND' using hint = 'That order no longer exists.';
  end if;
  if v_order.status = p_status then
    return;
  end if;
  v_ref := '#' || lpad(v_order.order_number::text, 4, '0');

  if p_status = 'picked_up' then
    for v_item in select product_id, sum(quantity)::int as qty from public.order_items
                  where order_id = p_order_id group by product_id loop
      insert into public.stock_movements (product_id, change, reason, effective_date, note, source_id, created_by)
      values (v_item.product_id, -v_item.qty, 'online_pickup', v_day,
              format('Online order %s picked up', v_ref), p_order_id, auth.uid());
      perform public.reconcile_sales_stock(v_item.product_id, v_day);
    end loop;

  elsif v_order.status = 'picked_up' then
    v_day := (v_order.picked_up_at at time zone (select timezone from public.settings where id = 1))::date;
    for v_item in select product_id, sum(quantity)::int as qty from public.order_items
                  where order_id = p_order_id group by product_id loop
      insert into public.stock_movements (product_id, change, reason, effective_date, note, source_id, created_by)
      values (v_item.product_id, v_item.qty, 'online_pickup_undo', v_day,
              format('Order %s moved back from Picked up', v_ref), p_order_id, auth.uid());
      perform public.reconcile_sales_stock(v_item.product_id, v_day);
    end loop;
  end if;

  update public.orders
     set status = p_status,
         status_changed_at = now(),
         picked_up_at = case when p_status = 'picked_up' then now()
                             when v_order.status = 'picked_up' then null
                             else picked_up_at end
   where id = p_order_id;

  perform public.sync_order_points(p_order_id);
end;
$$;

-- Expired orders give back any points spent on them.
create or replace function public.expire_uncollected_orders()
returns int
language plpgsql security definer
set search_path = public
as $$
declare
  v_id    uuid;
  v_count int := 0;
begin
  for v_id in
    update public.orders
       set status = 'expired', status_changed_at = now()
     where status in ('received', 'preparing', 'ready')
       and pickup_date < public.store_today()
    returning id
  loop
    perform public.sync_order_points(v_id);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


-- -----------------------------------------------------------------------------
-- 10. Reading orders (students)
-- -----------------------------------------------------------------------------
-- One order as JSON, for the order page. No student name inside.
create or replace function public._order_json(p_order_id uuid)
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'order_number',   o.order_number,
    'status',         o.status,
    'pickup_date',    o.pickup_date,
    'pickup_window',  w.label,
    'subtotal_cents', o.subtotal_cents,
    'discount_cents', o.discount_cents,
    'total_cents',    o.total_cents,
    'points_earned',  o.points_earned,
    'points_spent',   o.points_spent,
    'member',         o.customer_id is not null,
    'created_at',     o.created_at,
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
               'name', oi.product_name,
               'quantity', oi.quantity,
               'unit_price_cents', oi.unit_price_cents)
             order by oi.product_name)
      from public.order_items oi where oi.order_id = o.id and oi.order_bundle_id is null), '[]'::jsonb),
    'bundles', coalesce((
      select jsonb_agg(jsonb_build_object(
               'name', ob.bundle_name,
               'quantity', ob.quantity,
               'unit_price_cents', ob.unit_price_cents,
               'items', (select jsonb_agg(jsonb_build_object('name', oi.product_name, 'quantity', oi.quantity)
                                          order by oi.product_name)
                         from public.order_items oi where oi.order_bundle_id = ob.id))
             order by ob.bundle_name)
      from public.order_bundles ob where ob.order_id = o.id), '[]'::jsonb),
    'discounts', coalesce((
      select jsonb_agg(jsonb_build_object('label', d.label, 'amount_cents', d.amount_cents) order by d.kind, d.label)
      from public.order_discounts d where d.order_id = o.id), '[]'::jsonb)
  )
  from public.orders o
  join public.pickup_windows w on w.id = o.pickup_window_id
  where o.id = p_order_id;
$$;

-- Order number + last name (anyone).
create or replace function public.lookup_order(p_order_number int, p_last_name text)
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select public._order_json(o.id)
  from public.orders o
  where o.order_number = p_order_number
    and lower(btrim(o.last_name)) = lower(btrim(p_last_name));
$$;

-- A signed-in member's own order (no last name needed).
create or replace function public.lookup_my_order(p_order_number int)
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select public._order_json(o.id)
  from public.orders o
  where o.order_number = p_order_number
    and o.customer_id = auth.uid();
$$;


-- -----------------------------------------------------------------------------
-- 11. Public: deals, bundles and rewards for the menu
-- -----------------------------------------------------------------------------
-- Everything running today. Members-only deals are included (marked) so the
-- menu can tempt people to sign in.
create or replace function public.get_deals()
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'promotions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', pm.id, 'kind', pm.kind, 'title', pm.title,
               'product_id', pm.product_id, 'category', pm.category,
               'sale_price_cents', pm.sale_price_cents,
               'buy_qty', pm.buy_qty, 'get_qty', pm.get_qty,
               'ends_on', pm.ends_on, 'members_only', pm.members_only, 'featured', pm.featured)
             order by pm.featured desc, pm.created_at)
      from public.promotions pm
      join lateral (select pm.product_id is null
                        or exists (select 1 from public.products p
                                   where p.id = pm.product_id and not p.archived and p.available_online) as ok) c on c.ok
      where public.deal_is_live(pm.active, pm.starts_on, pm.ends_on, false, public.store_today(), false)), '[]'::jsonb),
    'bundles', coalesce((
      select jsonb_agg(x order by x->>'name')
      from (
        select jsonb_build_object(
                 'id', b.id, 'name', b.name, 'description', b.description,
                 'emoji', b.emoji, 'photo_path', b.photo_path,
                 'price_cents', b.price_cents,
                 'regular_cents', (select sum(p.price_cents * bi.quantity) from public.bundle_items bi
                                   join public.products p on p.id = bi.product_id where bi.bundle_id = b.id),
                 'members_only', b.members_only, 'ends_on', b.ends_on,
                 'available', (select coalesce(min(public.product_available(bi.product_id) / bi.quantity), 0)
                               from public.bundle_items bi where bi.bundle_id = b.id),
                 'items', (select jsonb_agg(jsonb_build_object('product_id', p.id, 'name', p.name,
                                                               'emoji', p.emoji, 'quantity', bi.quantity)
                                            order by p.name)
                           from public.bundle_items bi join public.products p on p.id = bi.product_id
                           where bi.bundle_id = b.id)) as x
        from public.bundles b
        where public.deal_is_live(b.active, b.starts_on, b.ends_on, false, public.store_today(), false)
          and exists (select 1 from public.bundle_items bi where bi.bundle_id = b.id)
          and not exists (select 1 from public.bundle_items bi join public.products p on p.id = bi.product_id
                          where bi.bundle_id = b.id and (p.archived or not p.available_online))
      ) t), '[]'::jsonb)
  );
$$;

create or replace function public.get_rewards()
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', rw.id, 'points_cost', rw.points_cost,
           'product_id', p.id, 'name', p.name, 'emoji', p.emoji,
           'photo_path', p.photo_path, 'category', p.category,
           'available', public.product_available(p.id))
         order by rw.points_cost, p.name), '[]'::jsonb)
  from public.rewards rw
  join public.products p on p.id = rw.product_id
  where rw.active and not p.archived and p.available_online
    and (select rewards_enabled from public.settings where id = 1);
$$;

-- The store info now also says whether rewards are on and how many points per $1.
create or replace function public.get_store_info()
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'store_name',        s.store_name,
    'store_hours',       s.store_hours,
    'pickup_location',   s.pickup_location,
    'banner_text',       s.banner_text,
    'today',             public.store_today(),
    'now_time',          to_char(public.store_now_time(), 'HH24:MI'),
    'order_cutoff_time', to_char(s.order_cutoff_time, 'HH24:MI'),
    'order_lead_minutes', s.order_lead_minutes,
    'max_items_per_order', s.max_items_per_order,
    'today_is_open',     public.is_open_day(public.store_today()),
    'next_open_day',     public.next_open_day(public.store_today()),
    'rewards_enabled',   s.rewards_enabled,
    'points_per_dollar', s.points_per_dollar,
    'pickup_windows', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', w.id,
               'label', w.label,
               'starts_at', to_char(w.starts_at, 'HH24:MI'))
             order by w.sort_order, w.starts_at)
      from public.pickup_windows w where w.active), '[]'::jsonb)
  )
  from public.settings s where s.id = 1;
$$;


-- -----------------------------------------------------------------------------
-- 12. Members: their own account
-- -----------------------------------------------------------------------------
-- Create or update the signed-in student's profile.
create or replace function public.save_profile(p_first_name text, p_last_name text, p_grade text)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_first text := btrim(coalesce(p_first_name, ''));
  v_last  text := btrim(coalesce(p_last_name, ''));
  v_grade text := btrim(coalesce(p_grade, ''));
  v_email text := auth.jwt()->>'email';
begin
  if auth.uid() is null or v_email is null then
    raise exception 'SIGN_IN_NEEDED' using hint = 'Please sign in first.';
  end if;
  if public.is_admin() then
    raise exception 'STAFF_ACCOUNT' using hint = 'The staff login can''t be a rewards account.';
  end if;
  if v_first = '' or v_last = '' or v_grade = '' then
    raise exception 'MISSING_INFO' using hint = 'Please fill in your first name, last name, and grade.';
  end if;
  if char_length(v_first) > 40 or char_length(v_last) > 40 or char_length(v_grade) > 20 then
    raise exception 'INFO_TOO_LONG' using hint = 'One of your answers is too long.';
  end if;

  insert into public.customers (id, email, first_name, last_name, grade)
  values (auth.uid(), lower(v_email), v_first, v_last, v_grade)
  on conflict (id) do update
     set first_name = excluded.first_name, last_name = excluded.last_name,
         grade = excluded.grade, email = excluded.email, updated_at = now();
end;
$$;

-- Everything the "My rewards" page shows.
create or replace function public.get_my_account()
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select case when auth.uid() is null then null else jsonb_build_object(
    'email', auth.jwt()->>'email',
    'staff', public.is_admin(),
    'profile', (select jsonb_build_object('first_name', c.first_name, 'last_name', c.last_name,
                                          'grade', c.grade, 'created_at', c.created_at)
                from public.customers c where c.id = auth.uid()),
    'balance', public.points_balance(auth.uid()),
    'history', coalesce((
      select jsonb_agg(jsonb_build_object('change', e.change, 'reason', e.reason, 'note', e.note,
                                          'order_number', e.order_number, 'created_at', e.created_at)
                       order by e.created_at desc)
      from (select * from public.point_entries where customer_id = auth.uid()
            order by created_at desc limit 30) e), '[]'::jsonb),
    'orders', coalesce((
      select jsonb_agg(jsonb_build_object('order_number', o.order_number, 'status', o.status,
                                          'pickup_date', o.pickup_date, 'total_cents', o.total_cents,
                                          'points_earned', o.points_earned, 'points_spent', o.points_spent)
                       order by o.created_at desc)
      from (select * from public.orders where customer_id = auth.uid()
            order by created_at desc limit 15) o), '[]'::jsonb)
  ) end;
$$;


-- -----------------------------------------------------------------------------
-- 13. Staff: members list and point adjustments
-- -----------------------------------------------------------------------------
create or replace function public.members_list()
returns table (
  id uuid, email text, first_name text, last_name text, grade text,
  balance int, orders int, last_order_at timestamptz, created_at timestamptz)
language sql stable security definer
set search_path = public
as $$
  select c.id, c.email, c.first_name, c.last_name, c.grade,
         public.points_balance(c.id),
         (select count(*)::int from public.orders o where o.customer_id = c.id and o.status = 'picked_up'),
         (select max(o.created_at) from public.orders o where o.customer_id = c.id),
         c.created_at
  from public.customers c
  where public.is_admin()
  order by c.last_name, c.first_name;
$$;

create or replace function public.adjust_points(p_customer_id uuid, p_change int, p_note text)
returns void
language plpgsql security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'NOT_ALLOWED' using hint = 'Only the store admin can do that.';
  end if;
  if p_change is null or p_change = 0 or abs(p_change) > 100000 then
    raise exception 'BAD_AMOUNT' using hint = 'Enter a number of points to add or remove.';
  end if;
  if btrim(coalesce(p_note, '')) = '' then
    raise exception 'NOTE_NEEDED' using hint = 'Say why the points changed.';
  end if;
  if public.points_balance(p_customer_id) + p_change < 0 then
    raise exception 'NEGATIVE_BALANCE' using hint = 'That would make their balance go below zero.';
  end if;
  insert into public.point_entries (customer_id, change, reason, note, created_by)
  values (p_customer_id, p_change, 'adjusted', left(btrim(p_note), 200), auth.uid());
end;
$$;


-- -----------------------------------------------------------------------------
-- 14. Security
-- -----------------------------------------------------------------------------
alter table public.customers        enable row level security;
alter table public.rewards          enable row level security;
alter table public.point_entries    enable row level security;
alter table public.promotions       enable row level security;
alter table public.bundles          enable row level security;
alter table public.bundle_items     enable row level security;
alter table public.order_bundles    enable row level security;
alter table public.order_discounts  enable row level security;

do $$
declare
  t text;
begin
  foreach t in array array['customers', 'rewards', 'promotions', 'bundles', 'bundle_items',
                           'order_bundles', 'order_discounts'] loop
    execute format(
      'create policy "admin full access" on public.%I for all to authenticated
         using (public.is_admin()) with check (public.is_admin())', t);
  end loop;
end $$;

-- Members can see their own row and points; changes go through functions.
create policy "member sees self" on public.customers
  for select to authenticated using (id = auth.uid());
create policy "admin reads points" on public.point_entries
  for select to authenticated using (public.is_admin());
create policy "member reads own points" on public.point_entries
  for select to authenticated using (customer_id = auth.uid());

-- Functions: lock everything down, then open exactly what's needed.
revoke execute on function public.deal_is_live(boolean, date, date, boolean, date, boolean) from public, anon, authenticated;
revoke execute on function public.points_balance(uuid)          from public, anon, authenticated;
revoke execute on function public.product_available(uuid)       from public, anon, authenticated;
revoke execute on function public._price_cart(jsonb, jsonb, boolean, uuid) from public, anon, authenticated;
revoke execute on function public.current_member()              from public, anon, authenticated;
revoke execute on function public.sync_order_points(uuid)       from public, anon, authenticated;
revoke execute on function public._order_json(uuid)             from public, anon, authenticated;
revoke execute on function public.place_order(text, text, text, int, date, jsonb, text, jsonb, uuid, uuid)
  from public, anon, authenticated;
revoke execute on function public.expire_uncollected_orders()   from public, anon, authenticated;

grant execute on function public.quote_cart(jsonb, jsonb, uuid)  to anon, authenticated;
grant execute on function public.get_deals()                     to anon, authenticated;
grant execute on function public.get_rewards()                   to anon, authenticated;
grant execute on function public.get_store_info()                to anon, authenticated;
grant execute on function public.lookup_order(int, text)         to anon, authenticated;
grant execute on function public.lookup_my_order(int)            to authenticated;
grant execute on function public.save_profile(text, text, text)  to authenticated;
grant execute on function public.get_my_account()                to authenticated;
grant execute on function public.members_list()                  to authenticated;
grant execute on function public.adjust_points(uuid, int, text)  to authenticated;
grant execute on function public.set_order_status(uuid, public.order_status) to authenticated;
grant execute on function public.place_order(text, text, text, int, date, jsonb, text, jsonb, uuid, uuid) to service_role;
grant execute on function public.expire_uncollected_orders()     to service_role;

-- Bundle and deal photos use the same public bucket as product photos.

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261027000010_usernames.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- Rewards accounts get a username (and sign in with a password)
-- =============================================================================
-- Students now sign up with a username, email and password, and sign back in
-- with their username (or email) and password. The email is still used to
-- confirm the account and to reset a forgotten password.
--
--   customers.username      how they sign in; shown on their account page
--   username_available()    "is this name free?" (asked while signing up)
--   save_profile(…, username)  now also sets the username
--   get_my_account()        now also returns the username
--
-- Accounts made before this have no username yet; their account page asks
-- them to pick one (and a password) the next time they sign in.
-- =============================================================================

alter table public.customers
  add column username text
    check (username ~ '^[A-Za-z0-9_.]{3,20}$'),
  -- The same name in any capitals counts as taken ("Joey" = "joey").
  add column username_key text generated always as (lower(username)) stored;

create unique index customers_username_key on public.customers (username_key);

-- Is a username free? (Yes/no only: it never shows who has it.)
create or replace function public.username_available(p_username text)
returns boolean
language sql stable security definer
set search_path = public
as $$
  select btrim(coalesce(p_username, '')) ~ '^[A-Za-z0-9_.]{3,20}$'
     and not exists (select 1 from public.customers where username_key = lower(btrim(p_username)) and id is distinct from auth.uid());
$$;

-- save_profile gets a username. The old 3-part version is replaced.
drop function if exists public.save_profile(text, text, text);

create or replace function public.save_profile(p_first_name text, p_last_name text, p_grade text, p_username text default null)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_first text := btrim(coalesce(p_first_name, ''));
  v_last  text := btrim(coalesce(p_last_name, ''));
  v_grade text := btrim(coalesce(p_grade, ''));
  v_user  text := nullif(btrim(coalesce(p_username, '')), '');
  v_email text := auth.jwt()->>'email';
begin
  if auth.uid() is null or v_email is null then
    raise exception 'SIGN_IN_NEEDED' using hint = 'Please sign in first.';
  end if;
  if public.is_admin() then
    raise exception 'STAFF_ACCOUNT' using hint = 'The staff login can''t be a rewards account.';
  end if;
  if v_first = '' or v_last = '' or v_grade = '' then
    raise exception 'MISSING_INFO' using hint = 'Please fill in your first name, last name, and grade.';
  end if;
  if char_length(v_first) > 40 or char_length(v_last) > 40 or char_length(v_grade) > 20 then
    raise exception 'INFO_TOO_LONG' using hint = 'One of your answers is too long.';
  end if;
  if v_user is not null and v_user !~ '^[A-Za-z0-9_.]{3,20}$' then
    raise exception 'BAD_USERNAME' using hint = 'Usernames are 3 to 20 letters, numbers, dots or underscores.';
  end if;
  if v_user is not null and exists (select 1 from public.customers where username_key = lower(v_user) and id <> auth.uid()) then
    raise exception 'USERNAME_TAKEN' using hint = 'That username is taken. Try another one.';
  end if;

  insert into public.customers (id, email, first_name, last_name, grade, username)
  values (auth.uid(), lower(v_email), v_first, v_last, v_grade, v_user)
  on conflict (id) do update
     set first_name = excluded.first_name, last_name = excluded.last_name,
         grade = excluded.grade, email = excluded.email,
         username = coalesce(excluded.username, public.customers.username), updated_at = now();
end;
$$;

-- get_my_account: the same as before, plus the username.
create or replace function public.get_my_account()
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select case when auth.uid() is null then null else jsonb_build_object(
    'email', auth.jwt()->>'email',
    'staff', public.is_admin(),
    'profile', (select jsonb_build_object('first_name', c.first_name, 'last_name', c.last_name,
                                          'grade', c.grade, 'created_at', c.created_at, 'username', c.username)
                from public.customers c where c.id = auth.uid()),
    'balance', public.points_balance(auth.uid()),
    'history', coalesce((
      select jsonb_agg(jsonb_build_object('change', e.change, 'reason', e.reason, 'note', e.note,
                                          'order_number', e.order_number, 'created_at', e.created_at)
                       order by e.created_at desc)
      from (select * from public.point_entries where customer_id = auth.uid()
            order by created_at desc limit 30) e), '[]'::jsonb),
    'orders', coalesce((
      select jsonb_agg(jsonb_build_object('order_number', o.order_number, 'status', o.status,
                                          'pickup_date', o.pickup_date, 'total_cents', o.total_cents,
                                          'points_earned', o.points_earned, 'points_spent', o.points_spent)
                       order by o.created_at desc)
      from (select * from public.orders where customer_id = auth.uid()
            order by created_at desc limit 15) o), '[]'::jsonb)
  ) end;
$$;

revoke all on function public.username_available(text) from public;
grant execute on function public.username_available(text) to anon, authenticated;
revoke all on function public.save_profile(text, text, text, text) from public, anon;
grant execute on function public.save_profile(text, text, text, text) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261028000011_teachers_room_service.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- Teachers, room service and combo deals (update 11)
-- =============================================================================
-- What this adds:
--   teachers           teacher accounts. A teacher signs up, then staff approve
--                      them in Admin → Teachers before teacher prices start.
--   Teacher prices     what the item cost the store + 50¢ (settings.teacher_markup_cents),
--                      never more than the normal price. A product with no cost
--                      saved yet stays at its normal price for teachers.
--   Room service       teachers can have an order brought to their room during
--                      a class hour. Class hours live in pickup_windows with
--                      kind = 'class' (edit them in Settings). They pay when it arrives.
--   Combo deals        promotions with kind = 'combo': "chips + a soda for $2.50".
--                      Each combo has slots (what goes in it); the cart finds
--                      the combos by itself, like buy-2-get-1 deals.
--
-- Teachers don't get combos, buy-X-get-Y deals or rewards (their prices are
-- already close to cost), and don't earn points.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. Settings
-- -----------------------------------------------------------------------------
alter table public.settings
  add column teacher_markup_cents int     not null default 50 check (teacher_markup_cents between 0 and 500),
  add column room_service_enabled boolean not null default true;


-- -----------------------------------------------------------------------------
-- 2. Class hours (for room service) live next to the pickup times
-- -----------------------------------------------------------------------------
alter table public.pickup_windows
  add column kind text not null default 'pickup' check (kind in ('pickup', 'class'));

-- A starting set of class hours. Change the times in Admin → Settings.
insert into public.pickup_windows (label, starts_at, sort_order, kind) values
  ('1st hour', '07:25', 101, 'class'),
  ('2nd hour', '08:20', 102, 'class'),
  ('3rd hour', '09:15', 103, 'class'),
  ('4th hour', '10:10', 104, 'class'),
  ('5th hour', '11:30', 105, 'class'),
  ('6th hour', '12:30', 106, 'class'),
  ('7th hour', '13:25', 107, 'class');


-- -----------------------------------------------------------------------------
-- 3. Teachers
-- -----------------------------------------------------------------------------
create table public.teachers (
  id           uuid primary key references auth.users (id) on delete cascade,
  email        text not null,
  first_name   text not null check (char_length(first_name) between 1 and 40),
  last_name    text not null check (char_length(last_name)  between 1 and 40),
  room         text not null check (char_length(room) between 1 and 20),
  status       text not null default 'pending' check (status in ('pending', 'approved', 'removed')),
  approved_at  timestamptz,
  approved_by  uuid references auth.users (id) on delete set null,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index on public.teachers (status, last_name);

-- The signed-in user, if they're an APPROVED teacher.
create or replace function public.current_teacher()
returns uuid
language sql stable security definer
set search_path = public
as $$
  select id from public.teachers where id = auth.uid() and status = 'approved';
$$;

-- A teacher fills in their name and room (asks to be approved, or updates them).
create or replace function public.save_teacher_profile(p_first_name text, p_last_name text, p_room text)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_first text := btrim(coalesce(p_first_name, ''));
  v_last  text := btrim(coalesce(p_last_name, ''));
  v_room  text := btrim(coalesce(p_room, ''));
  v_email text := auth.jwt()->>'email';
begin
  if auth.uid() is null or v_email is null then
    raise exception 'SIGN_IN_NEEDED' using hint = 'Please sign in first.';
  end if;
  if public.is_admin() then
    raise exception 'STAFF_ACCOUNT' using hint = 'The staff login can''t be a teacher account.';
  end if;
  if v_first = '' or v_last = '' or v_room = '' then
    raise exception 'MISSING_INFO' using hint = 'Please fill in your name and room number.';
  end if;
  if char_length(v_first) > 40 or char_length(v_last) > 40 or char_length(v_room) > 20 then
    raise exception 'INFO_TOO_LONG' using hint = 'One of your answers is too long.';
  end if;

  insert into public.teachers (id, email, first_name, last_name, room)
  values (auth.uid(), lower(v_email), v_first, v_last, v_room)
  on conflict (id) do update
     set first_name = excluded.first_name, last_name = excluded.last_name,
         room = excluded.room, email = excluded.email, updated_at = now();
end;
$$;

-- Teacher prices for every product (only for an approved teacher; empty otherwise).
create or replace function public.get_teacher_prices()
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object('product_id', p.id, 'price_cents',
           case when p.unit_cost_cents > 0 then least(p.price_cents, p.unit_cost_cents + s.teacher_markup_cents)
                else p.price_cents end)), '[]'::jsonb)
  from public.products p, public.settings s
  where s.id = 1 and not p.archived and p.available_online
    and public.current_teacher() is not null;
$$;


-- -----------------------------------------------------------------------------
-- 4. Orders remember the teacher and the room
-- -----------------------------------------------------------------------------
alter table public.orders
  add column teacher_id    uuid references public.teachers (id) on delete set null,
  add column delivery_room text check (char_length(delivery_room) between 1 and 20);
create index on public.orders (teacher_id, created_at desc);


-- -----------------------------------------------------------------------------
-- 5. Combo deals
-- -----------------------------------------------------------------------------
-- combo_slots: [{"label": "Chips", "quantity": 1, "product_ids": ["…", "…"]},
--               {"label": "Candy", "quantity": 2, "category": "candy"}]
-- A slot is filled by the listed products, or by anything in its category.
-- The combo's price is in sale_price_cents. Combos don't need an end date.
alter table public.promotions add column combo_slots jsonb;
alter table public.promotions alter column ends_on drop not null;

-- Swap the old "what kind of deal" rules for ones that know about combos.
do $$
declare
  c record;
begin
  for c in select conname from pg_constraint
           where conrelid = 'public.promotions'::regclass and contype = 'c'
             and (pg_get_constraintdef(oid) like '%buy_get%')
  loop
    execute format('alter table public.promotions drop constraint %I', c.conname);
  end loop;
  for c in select conname from pg_constraint
           where conrelid = 'public.order_discounts'::regclass and contype = 'c'
             and pg_get_constraintdef(oid) like '%reward%'
  loop
    execute format('alter table public.order_discounts drop constraint %I', c.conname);
  end loop;
end $$;

alter table public.promotions
  add constraint promotions_kind_check check (kind in ('sale', 'buy_get', 'combo')),
  add constraint promotions_shape_check check (
    (kind = 'sale' and product_id is not null and sale_price_cents is not null and category is null and ends_on is not null)
    or
    (kind = 'buy_get' and buy_qty is not null and get_qty is not null
       and ((product_id is null) <> (category is null)) and ends_on is not null)
    or
    (kind = 'combo' and sale_price_cents is not null and product_id is null and category is null
       and jsonb_typeof(combo_slots) = 'array' and jsonb_array_length(combo_slots) between 1 and 6)
  );
alter table public.order_discounts
  add constraint order_discounts_kind_check check (kind in ('buy_get', 'reward', 'combo'));

-- Does one item fit a combo slot?
create or replace function public.fits_slot(p_slot jsonb, p_product_id uuid, p_category text)
returns boolean
language sql immutable
as $$
  select (p_slot ? 'category' and lower(p_slot->>'category') = lower(p_category))
      or (p_slot ? 'product_ids' and p_slot->'product_ids' ? p_product_id::text);
$$;


-- -----------------------------------------------------------------------------
-- 6. Pricing (now with teacher prices and combos)
-- -----------------------------------------------------------------------------
drop function if exists public._price_cart(jsonb, jsonb, boolean, uuid);

create or replace function public._price_cart(
  p_items jsonb, p_bundles jsonb, p_member boolean, p_reward_id uuid, p_teacher boolean default false)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_day        date := public.store_today();
  v_markup     int  := (select teacher_markup_cents from public.settings where id = 1);
  v_bundles    jsonb := '[]'::jsonb;
  v_discounts  jsonb := '[]'::jsonb;
  v_reward     jsonb := null;
  v_subtotal   int;
  v_discount   int := 0;
  v_promo      record;
  v_rw         record;
  v_slot       jsonb;
  v_pick       bigint[];
  v_ids        bigint[];
  v_part       int;
  v_got        int;
  v_sum        int;
  v_ok         boolean;
  v_made       int;
  v_count      int;
  v_free       int;
  v_amount     int;
begin
  -- ---- Products ------------------------------------------------------------
  drop table if exists _pc_lines;
  create temporary table _pc_lines on commit drop as
    select (x->>'product_id')::uuid as product_id, sum((x->>'quantity')::int)::int as quantity
    from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) as x
    group by 1;

  if exists (select 1 from _pc_lines where product_id is null or quantity is null or quantity < 1 or quantity > 100) then
    raise exception 'BAD_QUANTITY' using hint = 'Each item needs a quantity of at least 1.';
  end if;
  if exists (select 1 from _pc_lines l left join public.products p on p.id = l.product_id
             where p.id is null or p.archived or not p.available_online) then
    raise exception 'UNAVAILABLE' using hint = 'An item in your cart is no longer available. Please refresh the menu.';
  end if;

  -- Each line's price: the lowest of the normal price, a running sale, and
  -- (for teachers) cost + markup.
  drop table if exists _pc_priced;
  create temporary table _pc_priced on commit drop as
    select l.product_id, p.name, p.category, l.quantity,
           p.price_cents as regular_price_cents,
           least(p.price_cents, coalesce(s.sale_price_cents, p.price_cents), coalesce(t.price, p.price_cents)) as unit_price_cents,
           case when t.price is not null and t.price < least(p.price_cents, coalesce(s.sale_price_cents, p.price_cents))
                then 'Teacher price' else s.title end as deal_title,
           false as is_reward
    from _pc_lines l
    join public.products p on p.id = l.product_id
    left join lateral (
      select pm.sale_price_cents, pm.title
      from public.promotions pm
      where pm.kind = 'sale' and pm.product_id = p.id
        and public.deal_is_live(pm.active, pm.starts_on, pm.ends_on, pm.members_only, v_day, p_member)
      order by pm.sale_price_cents
      limit 1
    ) s on true
    left join lateral (
      select p.unit_cost_cents + v_markup as price
      where p_teacher and p.unit_cost_cents > 0
    ) t on true;

  -- ---- Reward (one free item) ----------------------------------------------
  if p_reward_id is not null then
    if not p_member then
      raise exception 'SIGN_IN_NEEDED' using hint = 'Sign in to your rewards account to use a reward.';
    end if;
    select rw.id, rw.points_cost, p.id as product_id, p.name, p.category, p.price_cents,
           least(p.price_cents, coalesce((
             select min(pm.sale_price_cents) from public.promotions pm
             where pm.kind = 'sale' and pm.product_id = p.id
               and public.deal_is_live(pm.active, pm.starts_on, pm.ends_on, pm.members_only, v_day, p_member)
           ), p.price_cents)) as unit_price_cents
      into v_rw
      from public.rewards rw
      join public.products p on p.id = rw.product_id
     where rw.id = p_reward_id and rw.active and not p.archived and p.available_online;
    if not found then
      raise exception 'REWARD_UNAVAILABLE' using hint = 'That reward isn''t available right now.';
    end if;

    insert into _pc_priced values (v_rw.product_id, v_rw.name, v_rw.category, 1,
                                   v_rw.price_cents, v_rw.unit_price_cents, null, true);
    v_reward := jsonb_build_object('id', v_rw.id, 'product_id', v_rw.product_id,
                                   'name', v_rw.name, 'points_cost', v_rw.points_cost);
    if v_rw.unit_price_cents > 0 then
      v_discounts := v_discounts || jsonb_build_object(
        'label', 'Reward: free ' || v_rw.name, 'amount_cents', v_rw.unit_price_cents, 'kind', 'reward');
    end if;
  end if;

  -- ---- Bundles ---------------------------------------------------------------
  drop table if exists _pc_bundles;
  create temporary table _pc_bundles on commit drop as
    select (x->>'bundle_id')::uuid as bundle_id, sum((x->>'quantity')::int)::int as quantity
    from jsonb_array_elements(coalesce(p_bundles, '[]'::jsonb)) as x
    group by 1;

  if exists (select 1 from _pc_bundles where bundle_id is null or quantity is null or quantity < 1 or quantity > 20) then
    raise exception 'BAD_QUANTITY' using hint = 'Each bundle needs a quantity of at least 1.';
  end if;
  if exists (
    select 1 from _pc_bundles pb
    left join public.bundles b on b.id = pb.bundle_id
    where b.id is null
       or not public.deal_is_live(b.active, b.starts_on, b.ends_on, b.members_only, v_day, p_member)
       or not exists (select 1 from public.bundle_items bi where bi.bundle_id = b.id)
       or exists (select 1 from public.bundle_items bi join public.products p on p.id = bi.product_id
                  where bi.bundle_id = b.id and (p.archived or not p.available_online))
  ) then
    raise exception 'BUNDLE_UNAVAILABLE' using hint = 'A bundle in your cart isn''t available right now. Please refresh the menu.';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'bundle_id', b.id,
           'name', b.name,
           'quantity', pb.quantity,
           'unit_price_cents', b.price_cents,
           'items', (select jsonb_agg(jsonb_build_object('product_id', p.id, 'name', p.name, 'quantity', bi.quantity)
                                      order by p.name)
                     from public.bundle_items bi join public.products p on p.id = bi.product_id
                     where bi.bundle_id = b.id))
         order by b.name), '[]'::jsonb)
    into v_bundles
    from _pc_bundles pb join public.bundles b on b.id = pb.bundle_id;

  -- ---- Combos, then buy X get Y ----------------------------------------------
  -- One row per single item (not counting the reward or bundles). An item can
  -- only be used by one deal. Teachers skip this part.
  drop table if exists _pc_units;
  create temporary table _pc_units on commit drop as
    select row_number() over () as unit_id, p.product_id, p.category, p.unit_price_cents, false as used
    from _pc_priced p
    cross join lateral generate_series(1, p.quantity)
    where not p.is_reward;

  if not p_teacher then
    for v_promo in
      select * from public.promotions pm
      where pm.kind = 'combo'
        and public.deal_is_live(pm.active, pm.starts_on, pm.ends_on, pm.members_only, v_day, p_member)
      order by pm.created_at
    loop
      v_made := 0;
      v_amount := 0;
      -- Make as many of this combo as the cart allows. Each round fills every
      -- slot with the priciest items that fit (so the shopper saves the most),
      -- and stops when the combo wouldn't save anything.
      loop
        v_pick := '{}';
        v_sum := 0;
        v_ok := true;
        for v_slot in select value from jsonb_array_elements(v_promo.combo_slots) loop
          select array_agg(unit_id), coalesce(sum(unit_price_cents), 0)::int, count(*)::int
            into v_ids, v_part, v_got
          from (select u.unit_id, u.unit_price_cents from _pc_units u
                where not u.used and not (u.unit_id = any(v_pick))
                  and public.fits_slot(v_slot, u.product_id, u.category)
                order by u.unit_price_cents desc, u.unit_id
                limit greatest(coalesce((v_slot->>'quantity')::int, 1), 1)) x;
          if v_got < greatest(coalesce((v_slot->>'quantity')::int, 1), 1) then
            v_ok := false;
            exit;
          end if;
          v_pick := v_pick || v_ids;
          v_sum := v_sum + v_part;
        end loop;
        exit when not v_ok or v_sum <= v_promo.sale_price_cents;

        update _pc_units set used = true where unit_id = any(v_pick);
        v_made := v_made + 1;
        v_amount := v_amount + (v_sum - v_promo.sale_price_cents);
      end loop;

      if v_amount > 0 then
        v_discounts := v_discounts || jsonb_build_object(
          'label', v_promo.title || case when v_made > 1 then ' ×' || v_made else '' end,
          'amount_cents', v_amount, 'kind', 'combo');
      end if;
    end loop;

    for v_promo in
      select * from public.promotions pm
      where pm.kind = 'buy_get'
        and public.deal_is_live(pm.active, pm.starts_on, pm.ends_on, pm.members_only, v_day, p_member)
      order by pm.created_at
    loop
      select count(*) into v_count from _pc_units u
       where not u.used and (u.product_id = v_promo.product_id or u.category = v_promo.category);

      -- Every full group of (buy + get) items makes `get` of them free.
      v_free := (v_count / (v_promo.buy_qty + v_promo.get_qty)) * v_promo.get_qty;
      if v_free > 0 then
        select coalesce(sum(unit_price_cents), 0) into v_amount
        from (select u.unit_price_cents from _pc_units u
              where not u.used and (u.product_id = v_promo.product_id or u.category = v_promo.category)
              order by u.unit_price_cents
              limit v_free) cheapest;

        update _pc_units u set used = true
         where not u.used and (u.product_id = v_promo.product_id or u.category = v_promo.category);

        if v_amount > 0 then
          v_discounts := v_discounts || jsonb_build_object(
            'label', v_promo.title, 'amount_cents', v_amount, 'kind', 'buy_get');
        end if;
      end if;
    end loop;
  end if;

  -- ---- Totals ----------------------------------------------------------------
  select coalesce(sum(unit_price_cents * quantity), 0)::int into v_subtotal from _pc_priced;
  select v_subtotal + coalesce(sum((b->>'unit_price_cents')::int * (b->>'quantity')::int), 0)::int
    into v_subtotal from jsonb_array_elements(v_bundles) b;
  select coalesce(sum((d->>'amount_cents')::int), 0)::int into v_discount from jsonb_array_elements(v_discounts) d;
  v_discount := least(v_discount, v_subtotal);

  return jsonb_build_object(
    'lines', coalesce((select jsonb_agg(jsonb_build_object(
                         'product_id', product_id,
                         'name', name,
                         'quantity', quantity,
                         'regular_price_cents', regular_price_cents,
                         'unit_price_cents', unit_price_cents,
                         'deal_title', deal_title,
                         'is_reward', is_reward) order by is_reward, name)
                       from _pc_priced), '[]'::jsonb),
    'bundles', v_bundles,
    'discounts', v_discounts,
    'reward', v_reward,
    'subtotal_cents', v_subtotal,
    'discount_cents', v_discount,
    'total_cents', v_subtotal - v_discount
  );
end;
$$;

-- Public: price a cart (members get member prices, approved teachers teacher prices).
create or replace function public.quote_cart(p_items jsonb, p_bundles jsonb default '[]', p_reward_id uuid default null)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  s         public.settings;
  v_teacher uuid := public.current_teacher();
  v_member  uuid := case when v_teacher is null then public.current_member() end;
  v_quote   jsonb;
  v_total   int;
  v_balance int := 0;
  v_points  int;
begin
  select * into s from public.settings where id = 1;
  v_quote := public._price_cart(p_items, p_bundles, v_member is not null, p_reward_id, v_teacher is not null);
  v_total := (v_quote->>'total_cents')::int;
  v_points := case when s.rewards_enabled and v_teacher is null then floor(v_total * s.points_per_dollar / 100.0)::int else 0 end;

  if v_member is not null then
    v_balance := public.points_balance(v_member);
    if v_quote->'reward' <> 'null'::jsonb and v_balance < (v_quote->'reward'->>'points_cost')::int then
      raise exception 'NOT_ENOUGH_POINTS' using hint = 'You don''t have enough points for that reward yet.';
    end if;
  end if;

  return v_quote || jsonb_build_object(
    'member', v_member is not null,
    'teacher', v_teacher is not null,
    'points_balance', v_balance,
    'points_earned', case when v_member is not null then v_points else 0 end,
    'points_if_member', v_points
  );
end;
$$;


-- -----------------------------------------------------------------------------
-- 7. place_order: teachers and room service
-- -----------------------------------------------------------------------------
drop function if exists public.place_order(text, text, text, int, date, jsonb, text, jsonb, uuid, uuid);

create or replace function public.place_order(
  p_first_name       text,
  p_last_name        text,
  p_grade            text,
  p_pickup_window_id int,
  p_pickup_date      date,
  p_items            jsonb,
  p_ip_hash          text,
  p_bundles          jsonb default '[]',
  p_customer_id      uuid  default null,  -- set by the website server after checking the sign-in
  p_reward_id        uuid  default null,
  p_teacher_id       uuid  default null,  -- set by the website server for an approved teacher
  p_delivery_room    text  default null   -- room service: the room to bring it to
)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  s            public.settings;
  w            public.pickup_windows;
  v_today      date := public.store_today();
  v_now        time := public.store_now_time();
  v_first      text := btrim(coalesce(p_first_name, ''));
  v_last       text := btrim(coalesce(p_last_name, ''));
  v_grade      text := btrim(coalesce(p_grade, ''));
  v_room       text := nullif(btrim(coalesce(p_delivery_room, '')), '');
  v_teacher    boolean := false;
  v_member     boolean := false;
  v_price      jsonb;
  v_item       record;
  v_bundle     jsonb;
  v_ob_id      uuid;
  v_product    public.products;
  v_available  int;
  v_count      int;
  v_total      int;
  v_spent      int := 0;
  v_earned     int := 0;
  v_order      public.orders;
begin
  select * into s from public.settings where id = 1;

  -- ---- Who is ordering --------------------------------------------------------
  if p_teacher_id is not null then
    v_teacher := exists (select 1 from public.teachers where id = p_teacher_id and status = 'approved');
    if not v_teacher then
      raise exception 'TEACHER_NOT_APPROVED' using hint = 'Your teacher account hasn''t been approved yet.';
    end if;
    if v_grade = '' then v_grade := 'Teacher'; end if;
  end if;
  if v_first = '' or v_last = '' or v_grade = '' then
    raise exception 'MISSING_INFO' using hint = 'Please fill in your first name, last name, and grade.';
  end if;
  if char_length(v_first) > 40 or char_length(v_last) > 40 or char_length(v_grade) > 20 then
    raise exception 'INFO_TOO_LONG' using hint = 'One of your answers is too long.';
  end if;
  if p_customer_id is not null and not v_teacher then
    v_member := exists (select 1 from public.customers where id = p_customer_id);
    if not v_member then
      raise exception 'PROFILE_NEEDED' using hint = 'Finish setting up your rewards account first.';
    end if;
  end if;

  -- ---- Room service -------------------------------------------------------------
  if v_room is not null then
    if not v_teacher then
      raise exception 'TEACHERS_ONLY' using hint = 'Room service is for teachers.';
    end if;
    if not s.room_service_enabled then
      raise exception 'NO_ROOM_SERVICE' using hint = 'Room service is turned off right now. You can still pick your order up.';
    end if;
    if char_length(v_room) > 20 then
      raise exception 'INFO_TOO_LONG' using hint = 'That room number is too long.';
    end if;
  end if;

  -- ---- When -------------------------------------------------------------------
  if p_pickup_date is null
     or p_pickup_date not in (v_today, public.next_open_day(v_today)) then
    raise exception 'BAD_DATE' using hint = 'Orders can only be placed for today or the next school day.';
  end if;
  if not public.is_open_day(p_pickup_date) then
    raise exception 'STORE_CLOSED' using hint = 'The store is closed that day.';
  end if;

  -- Pickup orders need a pickup time; room service needs a class hour.
  select * into w from public.pickup_windows
   where id = p_pickup_window_id and active
     and kind = case when v_room is not null then 'class' else 'pickup' end;
  if not found then
    raise exception 'BAD_WINDOW' using hint = case when v_room is not null
      then 'Please choose which class hour to bring it.' else 'Please choose a pickup time.' end;
  end if;

  if p_pickup_date = v_today then
    -- Teachers can order later in the day; everyone needs the lead time.
    if v_now >= s.order_cutoff_time and not v_teacher then
      raise exception 'ORDERS_CLOSED' using hint = format(
        'Same-day orders close at %s. You can still order for the next school day.',
        to_char(s.order_cutoff_time, 'FMHH12:MI AM'));
    end if;
    if v_now >= w.starts_at - make_interval(mins => s.order_lead_minutes) then
      raise exception 'WINDOW_CLOSED' using hint = format(
        'It''s too late to order for %s today. Please pick a later time.', w.label);
    end if;
  end if;

  -- ---- Prank protection ---------------------------------------------------------
  if not v_teacher then
    select count(*) into v_count
    from public.orders
    where pickup_date = p_pickup_date
      and lower(first_name) = lower(v_first)
      and lower(last_name)  = lower(v_last)
      and status not in ('canceled');
    if v_count >= s.max_orders_per_student_day then
      raise exception 'STUDENT_LIMIT' using hint = format(
        'You already have %s order(s) for that day, which is the limit.', v_count);
    end if;
  end if;

  if p_ip_hash is not null then
    select count(*) into v_count
    from public.orders
    where ip_hash = p_ip_hash and created_at > now() - interval '1 hour';
    if v_count >= s.max_orders_per_hour_per_device then
      raise exception 'RATE_LIMIT' using hint = 'Too many orders from this device. Please try again later.';
    end if;
  end if;

  -- ---- What -------------------------------------------------------------------
  if coalesce(jsonb_array_length(case when jsonb_typeof(p_items) = 'array' then p_items end), 0)
     + coalesce(jsonb_array_length(case when jsonb_typeof(p_bundles) = 'array' then p_bundles end), 0) = 0
     and p_reward_id is null then
    raise exception 'EMPTY_CART' using hint = 'Your cart is empty.';
  end if;

  v_price := public._price_cart(p_items, p_bundles, v_member, p_reward_id, v_teacher);

  -- Every single product needed, counting what's inside bundles.
  drop table if exists _need;
  create temporary table _need on commit drop as
    select product_id, sum(qty)::int as quantity from (
      select (l->>'product_id')::uuid as product_id, (l->>'quantity')::int as qty
      from jsonb_array_elements(v_price->'lines') l
      union all
      select (i->>'product_id')::uuid, (i->>'quantity')::int * (b->>'quantity')::int
      from jsonb_array_elements(v_price->'bundles') b, jsonb_array_elements(b->'items') i
    ) t
    group by product_id;

  if (select sum(quantity) from _need) > s.max_items_per_order then
    raise exception 'TOO_MANY_ITEMS' using hint = format(
      'Orders are limited to %s items (bundles count each item inside).', s.max_items_per_order);
  end if;

  -- Lock each product (in a fixed order to avoid deadlocks) and check stock.
  for v_item in select * from _need order by product_id loop
    select * into v_product from public.products where id = v_item.product_id for update;
    v_available := public.product_available(v_product.id);
    if v_available < v_item.quantity then
      raise exception 'SOLD_OUT' using hint = case
        when v_available <= 0 then format('%s just sold out.', v_product.name)
        else format('Only %s %s left.', v_available, v_product.name) end;
    end if;
  end loop;

  -- ---- Rewards points ---------------------------------------------------------
  if v_price->'reward' <> 'null'::jsonb then
    perform 1 from public.customers where id = p_customer_id for update;
    v_spent := (v_price->'reward'->>'points_cost')::int;
    if public.points_balance(p_customer_id) < v_spent then
      raise exception 'NOT_ENOUGH_POINTS' using hint = 'You don''t have enough points for that reward yet.';
    end if;
  end if;

  v_total := (v_price->>'total_cents')::int;
  if v_member and s.rewards_enabled then
    v_earned := floor(v_total * s.points_per_dollar / 100.0)::int;
  end if;

  -- ---- Save it ------------------------------------------------------------------
  insert into public.orders (first_name, last_name, grade, pickup_window_id, pickup_date, ip_hash, customer_id,
                             teacher_id, delivery_room,
                             subtotal_cents, discount_cents, total_cents, points_earned, points_spent)
  values (v_first, v_last, v_grade, w.id, p_pickup_date, p_ip_hash, case when v_member then p_customer_id end,
          case when v_teacher then p_teacher_id end, v_room,
          (v_price->>'subtotal_cents')::int, (v_price->>'discount_cents')::int, v_total, v_earned, v_spent)
  returning * into v_order;

  insert into public.order_items (order_id, product_id, product_name, unit_price_cents, quantity)
  select v_order.id, (l->>'product_id')::uuid, l->>'name', (l->>'unit_price_cents')::int, (l->>'quantity')::int
  from jsonb_array_elements(v_price->'lines') l;

  for v_bundle in select * from jsonb_array_elements(v_price->'bundles') loop
    insert into public.order_bundles (order_id, bundle_id, bundle_name, unit_price_cents, quantity)
    values (v_order.id, (v_bundle->>'bundle_id')::uuid, v_bundle->>'name',
            (v_bundle->>'unit_price_cents')::int, (v_bundle->>'quantity')::int)
    returning id into v_ob_id;

    insert into public.order_items (order_id, product_id, product_name, unit_price_cents, quantity, order_bundle_id)
    select v_order.id, (i->>'product_id')::uuid, i->>'name', 0,
           (i->>'quantity')::int * (v_bundle->>'quantity')::int, v_ob_id
    from jsonb_array_elements(v_bundle->'items') i;
  end loop;

  insert into public.order_discounts (order_id, label, amount_cents, kind)
  select v_order.id, d->>'label', (d->>'amount_cents')::int, d->>'kind'
  from jsonb_array_elements(v_price->'discounts') d;

  perform public.sync_order_points(v_order.id);  -- takes the reward's points

  return jsonb_build_object(
    'order_number',  v_order.order_number,
    'pickup_date',   v_order.pickup_date,
    'pickup_window', w.label,
    'delivery_room', v_room,
    'total_cents',   v_total,
    'points_earned', v_earned,
    'points_spent',  v_spent
  );
end;
$$;


-- -----------------------------------------------------------------------------
-- 8. Reading orders: say when it's room service
-- -----------------------------------------------------------------------------
create or replace function public._order_json(p_order_id uuid)
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'order_number',   o.order_number,
    'status',         o.status,
    'pickup_date',    o.pickup_date,
    'pickup_window',  w.label,
    'delivery_room',  o.delivery_room,
    'teacher',        o.teacher_id is not null,
    'subtotal_cents', o.subtotal_cents,
    'discount_cents', o.discount_cents,
    'total_cents',    o.total_cents,
    'points_earned',  o.points_earned,
    'points_spent',   o.points_spent,
    'member',         o.customer_id is not null,
    'created_at',     o.created_at,
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
               'name', oi.product_name,
               'quantity', oi.quantity,
               'unit_price_cents', oi.unit_price_cents)
             order by oi.product_name)
      from public.order_items oi where oi.order_id = o.id and oi.order_bundle_id is null), '[]'::jsonb),
    'bundles', coalesce((
      select jsonb_agg(jsonb_build_object(
               'name', ob.bundle_name,
               'quantity', ob.quantity,
               'unit_price_cents', ob.unit_price_cents,
               'items', (select jsonb_agg(jsonb_build_object('name', oi.product_name, 'quantity', oi.quantity)
                                          order by oi.product_name)
                         from public.order_items oi where oi.order_bundle_id = ob.id))
             order by ob.bundle_name)
      from public.order_bundles ob where ob.order_id = o.id), '[]'::jsonb),
    'discounts', coalesce((
      select jsonb_agg(jsonb_build_object('label', d.label, 'amount_cents', d.amount_cents) order by d.kind, d.label)
      from public.order_discounts d where d.order_id = o.id), '[]'::jsonb)
  )
  from public.orders o
  join public.pickup_windows w on w.id = o.pickup_window_id
  where o.id = p_order_id;
$$;

-- A signed-in member's or teacher's own order (no last name needed).
create or replace function public.lookup_my_order(p_order_number int)
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select public._order_json(o.id)
  from public.orders o
  where o.order_number = p_order_number
    and (o.customer_id = auth.uid() or o.teacher_id = auth.uid());
$$;


-- -----------------------------------------------------------------------------
-- 9. Public info: combos, class hours, room service
-- -----------------------------------------------------------------------------
create or replace function public.get_deals()
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'promotions', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', pm.id, 'kind', pm.kind, 'title', pm.title,
               'product_id', pm.product_id, 'category', pm.category,
               'sale_price_cents', pm.sale_price_cents,
               'buy_qty', pm.buy_qty, 'get_qty', pm.get_qty,
               'ends_on', pm.ends_on, 'members_only', pm.members_only, 'featured', pm.featured)
             order by pm.featured desc, pm.created_at)
      from public.promotions pm
      join lateral (select pm.product_id is null
                        or exists (select 1 from public.products p
                                   where p.id = pm.product_id and not p.archived and p.available_online) as ok) c on c.ok
      where pm.kind in ('sale', 'buy_get')
        and public.deal_is_live(pm.active, pm.starts_on, pm.ends_on, false, public.store_today(), false)), '[]'::jsonb),
    'bundles', coalesce((
      select jsonb_agg(x order by x->>'name')
      from (
        select jsonb_build_object(
                 'id', b.id, 'name', b.name, 'description', b.description,
                 'emoji', b.emoji, 'photo_path', b.photo_path,
                 'price_cents', b.price_cents,
                 'regular_cents', (select sum(p.price_cents * bi.quantity) from public.bundle_items bi
                                   join public.products p on p.id = bi.product_id where bi.bundle_id = b.id),
                 'members_only', b.members_only, 'ends_on', b.ends_on,
                 'available', (select coalesce(min(public.product_available(bi.product_id) / bi.quantity), 0)
                               from public.bundle_items bi where bi.bundle_id = b.id),
                 'items', (select jsonb_agg(jsonb_build_object('product_id', p.id, 'name', p.name,
                                                               'emoji', p.emoji, 'quantity', bi.quantity)
                                            order by p.name)
                           from public.bundle_items bi join public.products p on p.id = bi.product_id
                           where bi.bundle_id = b.id)) as x
        from public.bundles b
        where public.deal_is_live(b.active, b.starts_on, b.ends_on, false, public.store_today(), false)
          and exists (select 1 from public.bundle_items bi where bi.bundle_id = b.id)
          and not exists (select 1 from public.bundle_items bi join public.products p on p.id = bi.product_id
                          where bi.bundle_id = b.id and (p.archived or not p.available_online))
      ) t), '[]'::jsonb),
    -- Combos, with the products that can go in each slot (priciest first).
    'combos', coalesce((
      select jsonb_agg(x order by (x->>'featured')::boolean desc, x->>'title')
      from (
        select jsonb_build_object(
                 'id', pm.id, 'title', pm.title, 'price_cents', pm.sale_price_cents,
                 'ends_on', pm.ends_on, 'members_only', pm.members_only, 'featured', pm.featured,
                 'slots', (select jsonb_agg(jsonb_build_object(
                                    'label', sl.value->>'label',
                                    'quantity', greatest(coalesce((sl.value->>'quantity')::int, 1), 1),
                                    'products', coalesce((
                                      select jsonb_agg(jsonb_build_object(
                                               'product_id', p.id, 'name', p.name, 'emoji', p.emoji,
                                               'price_cents', p.price_cents,
                                               'available', public.product_available(p.id))
                                             order by p.price_cents desc, p.name)
                                      from public.products p
                                      where not p.archived and p.available_online
                                        and public.fits_slot(sl.value, p.id, p.category)), '[]'::jsonb))
                                  order by sl.ordinality)
                           from jsonb_array_elements(pm.combo_slots) with ordinality sl)) as x
        from public.promotions pm
        where pm.kind = 'combo'
          and public.deal_is_live(pm.active, pm.starts_on, pm.ends_on, false, public.store_today(), false)
      ) t
      -- Hide a combo when one of its slots has nothing left to put in it.
      where not exists (select 1 from jsonb_array_elements(x->'slots') sl where jsonb_array_length(sl->'products') = 0)
    ), '[]'::jsonb)
  );
$$;

create or replace function public.get_store_info()
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object(
    'store_name',        s.store_name,
    'store_hours',       s.store_hours,
    'pickup_location',   s.pickup_location,
    'banner_text',       s.banner_text,
    'today',             public.store_today(),
    'now_time',          to_char(public.store_now_time(), 'HH24:MI'),
    'order_cutoff_time', to_char(s.order_cutoff_time, 'HH24:MI'),
    'order_lead_minutes', s.order_lead_minutes,
    'max_items_per_order', s.max_items_per_order,
    'today_is_open',     public.is_open_day(public.store_today()),
    'next_open_day',     public.next_open_day(public.store_today()),
    'rewards_enabled',   s.rewards_enabled,
    'points_per_dollar', s.points_per_dollar,
    'room_service_enabled', s.room_service_enabled,
    'pickup_windows', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', w.id,
               'label', w.label,
               'starts_at', to_char(w.starts_at, 'HH24:MI'))
             order by w.sort_order, w.starts_at)
      from public.pickup_windows w where w.active and w.kind = 'pickup'), '[]'::jsonb),
    'class_periods', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', w.id,
               'label', w.label,
               'starts_at', to_char(w.starts_at, 'HH24:MI'))
             order by w.sort_order, w.starts_at)
      from public.pickup_windows w where w.active and w.kind = 'class'), '[]'::jsonb)
  )
  from public.settings s where s.id = 1;
$$;

-- "My account" also says whether this login is a teacher (and if approved).
create or replace function public.get_my_account()
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select case when auth.uid() is null then null else jsonb_build_object(
    'email', auth.jwt()->>'email',
    'staff', public.is_admin(),
    'profile', (select jsonb_build_object('first_name', c.first_name, 'last_name', c.last_name,
                                          'grade', c.grade, 'created_at', c.created_at, 'username', c.username)
                from public.customers c where c.id = auth.uid()),
    'teacher', (select jsonb_build_object('first_name', t.first_name, 'last_name', t.last_name,
                                          'room', t.room, 'status', t.status)
                from public.teachers t where t.id = auth.uid()),
    'balance', public.points_balance(auth.uid()),
    'history', coalesce((
      select jsonb_agg(jsonb_build_object('change', e.change, 'reason', e.reason, 'note', e.note,
                                          'order_number', e.order_number, 'created_at', e.created_at)
                       order by e.created_at desc)
      from (select * from public.point_entries where customer_id = auth.uid()
            order by created_at desc limit 30) e), '[]'::jsonb),
    'orders', coalesce((
      select jsonb_agg(jsonb_build_object('order_number', o.order_number, 'status', o.status,
                                          'pickup_date', o.pickup_date, 'total_cents', o.total_cents,
                                          'points_earned', o.points_earned, 'points_spent', o.points_spent,
                                          'delivery_room', o.delivery_room)
                       order by o.created_at desc)
      from (select * from public.orders where customer_id = auth.uid() or teacher_id = auth.uid()
            order by created_at desc limit 15) o), '[]'::jsonb)
  ) end;
$$;


-- -----------------------------------------------------------------------------
-- 10. The two combos asked for
-- -----------------------------------------------------------------------------
-- "Chips + a soda" for $2.50 and "2 candies + a soda" for $5. Sodas are the
-- $2 ones (Coke, Sprite, Fanta, Dr Pepper, Mountain Dew…). Change what's in
-- them in Admin → Deals.
do $$
declare
  v_chips  jsonb;
  v_sodas  jsonb;
begin
  select jsonb_agg(id) into v_chips from public.products
   where not archived and lower(category) = 'snacks'
     and name ~* '(chip|dorito|cheeto|takis|lay''?s|frito|ruffles|funyuns|pringles)';
  select jsonb_agg(id) into v_sodas from public.products
   where not archived and lower(category) = 'drinks' and price_cents <= 200
     and name ~* '(coke|cola|pepsi|sprite|fanta|dr\.? ?pepper|mountain dew|root beer|7 ?up|ginger ale|crush|soda|starry|mug)';

  if v_sodas is null then
    raise notice 'No sodas found, so the combos weren''t made. Make them in Admin → Deals.';
    return;
  end if;

  if v_chips is not null then
    insert into public.promotions (kind, title, sale_price_cents, combo_slots, starts_on, ends_on)
    values ('combo', 'Chips + soda', 250,
            jsonb_build_array(jsonb_build_object('label', 'Chips', 'quantity', 1, 'product_ids', v_chips),
                              jsonb_build_object('label', 'Soda', 'quantity', 1, 'product_ids', v_sodas)),
            public.store_today(), null);
  else
    raise notice 'No chips found, so "Chips + soda" wasn''t made. Make it in Admin → Deals.';
  end if;

  insert into public.promotions (kind, title, sale_price_cents, combo_slots, starts_on, ends_on)
  values ('combo', 'Candy combo', 500,
          jsonb_build_array(jsonb_build_object('label', 'Candy', 'quantity', 2, 'category', 'candy'),
                            jsonb_build_object('label', 'Soda', 'quantity', 1, 'product_ids', v_sodas)),
          public.store_today(), null);
end $$;


-- -----------------------------------------------------------------------------
-- 11. Security
-- -----------------------------------------------------------------------------
alter table public.teachers enable row level security;
create policy "admin full access" on public.teachers for all to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy "teacher sees self" on public.teachers
  for select to authenticated using (id = auth.uid());

revoke execute on function public.current_teacher() from public, anon, authenticated;
revoke execute on function public._price_cart(jsonb, jsonb, boolean, uuid, boolean) from public, anon, authenticated;
revoke execute on function public.place_order(text, text, text, int, date, jsonb, text, jsonb, uuid, uuid, uuid, text)
  from public, anon, authenticated;
grant execute on function public.place_order(text, text, text, int, date, jsonb, text, jsonb, uuid, uuid, uuid, text) to service_role;

revoke execute on function public.save_teacher_profile(text, text, text) from public, anon;
grant execute on function public.save_teacher_profile(text, text, text) to authenticated;
revoke execute on function public.get_teacher_prices() from public, anon;
grant execute on function public.get_teacher_prices() to authenticated;
grant execute on function public.fits_slot(jsonb, uuid, text) to anon, authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261028000012_item_requests.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- Item requests (update 12)
-- =============================================================================
-- Students and teachers can ask the store to sell something ("Takis Blue
-- Heat", "Gatorade Zero"…) at the request table in the 3D store or on the
-- home page. Staff see what's asked for most on the Requests page.
--
--   item_requests         one row per request
--   item_request_status   staff's answer for each item: new, planned
--                         ("coming soon"), stocked ("now selling") or declined
--   request_item()        saves a request (only the website server calls it,
--                         so it can limit how many one device sends)
--   popular_requests()    the most-asked-for items, for the "me too" list
-- =============================================================================

-- "Takis  Blue-Heat!" → "takis blue heat": requests for the same thing group together.
create or replace function public.request_key(p_name text)
returns text
language sql immutable
as $$
  select btrim(regexp_replace(regexp_replace(lower(coalesce(p_name, '')), '[^a-z0-9]+', ' ', 'g'), '\s+', ' ', 'g'));
$$;

create table public.item_requests (
  id           bigint generated always as identity primary key,
  item_name    text not null check (char_length(item_name) between 2 and 60),
  item_key     text generated always as (public.request_key(item_name)) stored,
  category     text check (char_length(category) <= 30),
  note         text check (char_length(note) <= 200),
  requester    text check (char_length(requester) <= 60),  -- optional first name
  customer_id  uuid references public.customers (id) on delete set null,
  teacher_id   uuid,  -- a teacher's login id (no link, so this update doesn't need update 11)
  source       text not null default 'web' check (source in ('store3d', 'web')),
  ip_hash      text,  -- one-way hash of the device, only for limiting spam
  created_at   timestamptz not null default now()
);
create index on public.item_requests (item_key, created_at desc);
create index on public.item_requests (created_at desc);
create index on public.item_requests (ip_hash, created_at desc);

create table public.item_request_status (
  item_key     text primary key,
  status       text not null default 'new' check (status in ('new', 'planned', 'stocked', 'declined')),
  staff_note   text check (char_length(staff_note) <= 200),
  updated_at   timestamptz not null default now()
);

-- Save a request. Returns how many people have asked for that item.
create or replace function public.request_item(
  p_item        text,
  p_category    text,
  p_note        text,
  p_requester   text,
  p_ip_hash     text,
  p_source      text default 'web',
  p_customer_id uuid default null,
  p_teacher_id  uuid default null
)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_item  text := btrim(regexp_replace(coalesce(p_item, ''), '\s+', ' ', 'g'));
  v_key   text := public.request_key(p_item);
  v_count int;
  v_dupe  boolean := false;
begin
  if char_length(v_item) < 2 or v_key = '' then
    raise exception 'MISSING_ITEM' using hint = 'Tell us what you''d like us to sell.';
  end if;
  if char_length(v_item) > 60 then
    raise exception 'TOO_LONG' using hint = 'Keep the item name under 60 characters.';
  end if;

  if p_ip_hash is not null then
    -- Spam limit: 8 requests an hour from one device.
    select count(*) into v_count from public.item_requests
     where ip_hash = p_ip_hash and created_at > now() - interval '1 hour';
    if v_count >= 8 then
      raise exception 'RATE_LIMIT' using hint = 'That''s a lot of requests! Try again in a little while.';
    end if;
    -- The same device asking for the same thing twice in a day counts once.
    v_dupe := exists (select 1 from public.item_requests
                      where ip_hash = p_ip_hash and item_key = v_key and created_at > now() - interval '1 day');
  end if;

  if not v_dupe then
    insert into public.item_requests (item_name, category, note, requester, customer_id, teacher_id, source, ip_hash)
    values (v_item,
            nullif(left(btrim(coalesce(p_category, '')), 30), ''),
            nullif(left(btrim(coalesce(p_note, '')), 200), ''),
            nullif(left(btrim(coalesce(p_requester, '')), 60), ''),
            p_customer_id, p_teacher_id,
            case when p_source = 'store3d' then 'store3d' else 'web' end,
            p_ip_hash);
  end if;

  select count(*) into v_count from public.item_requests where item_key = v_key;
  return jsonb_build_object('item', v_item, 'count', v_count, 'already', v_dupe,
                            'status', coalesce((select status from public.item_request_status where item_key = v_key), 'new'));
end;
$$;

-- The most-asked-for items in the last 60 days (no names, just counts), for
-- the "others asked for" list. Items staff turned down aren't shown.
create or replace function public.popular_requests(p_limit int default 8)
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(x order by (x->>'count')::int desc, x->>'name'), '[]'::jsonb)
  from (
    select jsonb_build_object(
             'key', r.item_key,
             -- the spelling people used most
             'name', (select item_name from public.item_requests r2 where r2.item_key = r.item_key
                      group by item_name order by count(*) desc, (item_name <> lower(item_name)) desc, min(created_at) limit 1),
             'count', count(*)::int,
             'status', coalesce(s.status, 'new')) as x
    from public.item_requests r
    left join public.item_request_status s on s.item_key = r.item_key
    where r.created_at > now() - interval '60 days'
      and coalesce(s.status, 'new') <> 'declined'
    group by r.item_key, s.status
    order by count(*) desc
    limit greatest(1, least(coalesce(p_limit, 8), 20))
  ) t;
$$;

-- Security: staff can read and answer everything; the public only through the functions above.
alter table public.item_requests       enable row level security;
alter table public.item_request_status enable row level security;
create policy "admin full access" on public.item_requests for all to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy "admin full access" on public.item_request_status for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

revoke execute on function public.request_item(text, text, text, text, text, text, uuid, uuid) from public, anon, authenticated;
grant execute on function public.request_item(text, text, text, text, text, text, uuid, uuid) to service_role;
revoke execute on function public.popular_requests(int) from public;
grant execute on function public.popular_requests(int) to anon, authenticated;
grant execute on function public.request_key(text) to anon, authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261029000013_city_game.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- The 3D city game (update 13)
-- =============================================================================
-- The 3D store's city is a game: pretend US-dollar money, jobs, cars, houses.
-- This saves it to each signed-in player's account, and lets staff hire
-- players for the in-game jobs.
--
--   game_players            one row per player: their in-game ID card number,
--                           the name on it, and their saved game (money,
--                           cars, houses, job progress) as JSON.
--   game_job_applications   a player's résumé for a job at one of the city's
--                           shops (Slice Society, Polar Scoops…). Staff
--                           hire or decline them in Admin → City jobs.
--
--   get_game_player()       the signed-in player's saved game (made the first
--                           time they play), with their job applications.
--   save_game_state()       saves their game.
--   apply_for_job()         sends a résumé.
--   leave_job()             quitting, or getting fired in the game (too many
--                           customers walked out).
--   record_job_level()      a promotion in the game.
--
-- None of this is real money: it can't be spent in the store.
-- =============================================================================

create table public.game_players (
  id            uuid primary key references auth.users (id) on delete cascade,
  id_number     text not null unique,
  display_name  text not null check (char_length(display_name) between 1 and 60),
  state         jsonb not null default '{}'::jsonb,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create table public.game_job_applications (
  id            uuid primary key default gen_random_uuid(),
  player_id     uuid not null references public.game_players (id) on delete cascade,
  business      text not null check (business in ('pizza', 'icecream', 'coffee', 'burger', 'flowers')),
  answers       jsonb not null,
  status        text not null default 'pending' check (status in ('pending', 'hired', 'declined', 'fired', 'quit')),
  level         int not null default 0 check (level between 0 and 10),
  staff_note    text check (char_length(staff_note) <= 200),
  decided_at    timestamptz,
  decided_by    uuid references auth.users (id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index on public.game_job_applications (status, created_at desc);
create index on public.game_job_applications (player_id);
-- One open application (or job) per player per shop.
create unique index game_job_one_open on public.game_job_applications (player_id, business)
  where status in ('pending', 'hired');

-- The name to put on someone's ID: their rewards name, else teacher name, else their email.
create or replace function public.game_display_name(p_user uuid)
returns text
language sql stable security definer
set search_path = public
as $$
  select coalesce(
    (select first_name || ' ' || last_name from public.customers where id = p_user),
    (select first_name || ' ' || last_name from public.teachers where id = p_user),
    (select split_part(email, '@', 1) from auth.users where id = p_user),
    'Player');
$$;

-- The signed-in player's game (made the first time). Staff logins can't play for keeps.
create or replace function public.get_game_player()
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_id   uuid := auth.uid();
  v_row  public.game_players;
  v_num  text;
begin
  if v_id is null or public.is_admin() then
    return null;
  end if;
  select * into v_row from public.game_players where id = v_id;
  if not found then
    -- A new ID number like "CTY-482-1937" (tried until it's not taken).
    loop
      v_num := 'CTY-' || lpad((floor(random() * 1000))::int::text, 3, '0') || '-' || lpad((floor(random() * 10000))::int::text, 4, '0');
      exit when not exists (select 1 from public.game_players where id_number = v_num);
    end loop;
    insert into public.game_players (id, id_number, display_name)
    values (v_id, v_num, left(public.game_display_name(v_id), 60))
    returning * into v_row;
  else
    -- Keep the name on the ID up to date with their account.
    update public.game_players set display_name = left(public.game_display_name(v_id), 60)
     where id = v_id and display_name <> left(public.game_display_name(v_id), 60)
    returning * into v_row;
    if not found then
      select * into v_row from public.game_players where id = v_id;
    end if;
  end if;
  return jsonb_build_object(
    'id_number', v_row.id_number,
    'name', v_row.display_name,
    'since', v_row.created_at,
    'state', v_row.state,
    'applications', coalesce((
      select jsonb_agg(jsonb_build_object('id', a.id, 'business', a.business, 'status', a.status, 'level', a.level,
                                          'note', a.staff_note, 'created_at', a.created_at, 'decided_at', a.decided_at)
                       order by a.created_at desc)
      from public.game_job_applications a where a.player_id = v_id), '[]'::jsonb));
end;
$$;

-- Save the game (money, cars, houses, job progress). Kept small.
create or replace function public.save_game_state(p_state jsonb)
returns void
language plpgsql security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception 'SIGN_IN_NEEDED' using hint = 'Sign in to save your game.';
  end if;
  if p_state is null or jsonb_typeof(p_state) <> 'object' or pg_column_size(p_state) > 32000 then
    raise exception 'BAD_SAVE' using hint = 'That save is too big.';
  end if;
  update public.game_players set state = p_state, updated_at = now() where id = auth.uid();
end;
$$;

-- Send a résumé.
create or replace function public.apply_for_job(p_business text, p_answers jsonb)
returns void
language plpgsql security definer
set search_path = public
as $$
begin
  if auth.uid() is null then
    raise exception 'SIGN_IN_NEEDED' using hint = 'Sign in to apply for a job.';
  end if;
  if not exists (select 1 from public.game_players where id = auth.uid()) then
    raise exception 'NO_PLAYER' using hint = 'Open the 3D city first.';
  end if;
  if p_business not in ('pizza', 'icecream', 'coffee', 'burger', 'flowers') then
    raise exception 'BAD_JOB' using hint = 'That shop isn''t hiring.';
  end if;
  if p_answers is null or jsonb_typeof(p_answers) <> 'object' or pg_column_size(p_answers) > 4000 then
    raise exception 'BAD_RESUME' using hint = 'Please fill in the résumé.';
  end if;
  if exists (select 1 from public.game_job_applications where player_id = auth.uid() and business = p_business and status in ('pending', 'hired')) then
    raise exception 'ALREADY' using hint = 'You''ve already applied here.';
  end if;
  insert into public.game_job_applications (player_id, business, answers) values (auth.uid(), p_business, p_answers);
end;
$$;

-- Quitting, or being fired by the game.
create or replace function public.leave_job(p_business text, p_reason text)
returns void
language plpgsql security definer
set search_path = public
as $$
begin
  update public.game_job_applications
     set status = case when p_reason = 'fired' then 'fired' else 'quit' end,
         staff_note = case when p_reason = 'fired' then 'Too many customers walked out.' else staff_note end,
         updated_at = now()
   where player_id = auth.uid() and business = p_business and status = 'hired';
end;
$$;

-- A promotion (the game decides when you've earned one).
create or replace function public.record_job_level(p_business text, p_level int)
returns void
language plpgsql security definer
set search_path = public
as $$
begin
  update public.game_job_applications set level = greatest(0, least(coalesce(p_level, 0), 10)), updated_at = now()
   where player_id = auth.uid() and business = p_business and status = 'hired';
end;
$$;

-- Security: staff see and change everything; players only through the functions above.
alter table public.game_players          enable row level security;
alter table public.game_job_applications enable row level security;
create policy "admin full access" on public.game_players for all to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy "admin full access" on public.game_job_applications for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

revoke execute on function public.game_display_name(uuid) from public, anon, authenticated;
revoke execute on function public.get_game_player() from public, anon;
revoke execute on function public.save_game_state(jsonb) from public, anon;
revoke execute on function public.apply_for_job(text, jsonb) from public, anon;
revoke execute on function public.leave_job(text, text) from public, anon;
revoke execute on function public.record_job_level(text, int) from public, anon;
grant execute on function public.get_game_player() to authenticated;
grant execute on function public.save_game_state(jsonb) to authenticated;
grant execute on function public.apply_for_job(text, jsonb) to authenticated;
grant execute on function public.leave_job(text, text) to authenticated;
grant execute on function public.record_job_level(text, int) to authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261030000014_golf_rounds.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- Golf at Firebird Ridge (update 14)
-- =============================================================================
-- The 3D city has a 9-hole golf course. The game keeps the score; when a
-- signed-in player finishes a round it's saved here, and everyone can see the
-- leaderboard.
--
--   golf_rounds              one row per finished round: the strokes on each
--                            hole (9 numbers), the total and the score to par.
--
--   record_golf_round()      saves the signed-in player's finished round.
--   golf_leaderboard()       the best rounds (best one per player), with the
--                            name on their in-game ID.
--
-- Nothing here is real: it's a game.
-- =============================================================================

create table public.golf_rounds (
  id          uuid primary key default gen_random_uuid(),
  player_id   uuid not null references public.game_players (id) on delete cascade,
  holes       int[] not null check (array_length(holes, 1) = 9),
  total       int not null check (total between 9 and 90),
  to_par      int not null,
  created_at  timestamptz not null default now()
);
create index on public.golf_rounds (total, created_at);
create index on public.golf_rounds (player_id, created_at desc);

-- Save a finished round. The game picks you up at 10 on a hole, so each hole is 1…10.
create or replace function public.record_golf_round(p_holes int[])
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_id    uuid := auth.uid();
  v_total int;
  v_par   int := 37; -- the course's par (golf-course.ts)
begin
  if v_id is null or public.is_admin() then
    return;
  end if;
  if p_holes is null or array_length(p_holes, 1) <> 9 then
    raise exception 'A round is 9 holes.';
  end if;
  if exists (select 1 from unnest(p_holes) h where h is null or h < 1 or h > 10) then
    raise exception 'Each hole is between 1 and 10 strokes.';
  end if;
  -- Only players with a saved game (made the first time they play).
  if not exists (select 1 from public.game_players where id = v_id) then
    return;
  end if;
  -- Not more than one round a minute (a round takes a lot longer than that).
  if exists (select 1 from public.golf_rounds where player_id = v_id and created_at > now() - interval '1 minute') then
    return;
  end if;
  select sum(h) into v_total from unnest(p_holes) h;
  insert into public.golf_rounds (player_id, holes, total, to_par)
  values (v_id, p_holes, v_total, v_total - v_par);
end;
$$;

-- The leaderboard: each player's best round, best first.
create or replace function public.golf_leaderboard()
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(row_to_json(t) order by t.total, t.date), '[]'::jsonb)
  from (
    select * from (
      select distinct on (r.player_id)
             p.display_name as name, r.total, r.to_par as "toPar", r.holes, r.created_at as date,
             (r.player_id = auth.uid()) as you
        from public.golf_rounds r
        join public.game_players p on p.id = r.player_id
       order by r.player_id, r.total, r.created_at
    ) best
    order by best.total, best.date
    limit 20
  ) t;
$$;

alter table public.golf_rounds enable row level security;
create policy "admin full access" on public.golf_rounds for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

revoke execute on function public.record_golf_round(int[]) from public, anon;
grant execute on function public.record_golf_round(int[]) to authenticated;
revoke execute on function public.golf_leaderboard() from public;
grant execute on function public.golf_leaderboard() to anon, authenticated;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261106000015_staff_time_clock.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- Staff time clock, schedule and store credit (update 15)
-- =============================================================================
-- Student employees clock in and out at /clock with a 4-digit PIN (or by
-- scanning their student ID). Staff schedule them by class hour (1st–7th hour,
-- the class hours in Settings) and every employee earns store credit for the
-- time they work: $1 for every 45 minutes (both numbers are settings).
--
--   staff                  employees: name, PIN, optional badge (student ID #).
--                          status: pending (signed up at /clock, waiting for
--                          approval) → active → removed (can be restored or erased).
--   staff_shifts           timecards: one row per shift, clock_in → clock_out.
--                          Keeps the employee's name, so hours survive erasing them.
--   staff_schedule         who works which class hour on which day.
--   staff_credit_entries   store credit spent (minus) or added by hand (plus).
--                          Credit EARNED isn't stored: it's worked out from the
--                          timecards, so fixing a shift fixes the credit too.
--   staff_clock_attempts   wrong PINs and sign-ups per device, for rate limiting.
--
--   staff_punch()          clock in / out with a PIN or badge     (website server only)
--   staff_punch_undo()     undo a punch within 2 minutes           (website server only)
--   staff_signup()         "Create account" on the time clock      (website server only)
--   staff_board()          on the clock, today's shifts, upcoming schedule (server only)
--   staff_credit_balances()  credit earned / used / left per employee (admin, server)
--   staff_credit_add()     spend or add credit (admin; can't go below $0)
--
-- Students can't read any of these tables. The time clock page talks to the
-- database only through the website's server, which hashes the device's IP for
-- the rate limits, the same way orders do.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. Settings
-- -----------------------------------------------------------------------------
alter table public.settings
  add column staff_credit_cents    int     not null default 100 check (staff_credit_cents between 0 and 2000),
  add column staff_credit_minutes  int     not null default 45  check (staff_credit_minutes between 5 and 480),
  add column staff_signup_approval boolean not null default true;


-- -----------------------------------------------------------------------------
-- 2. Tables
-- -----------------------------------------------------------------------------
create table public.staff (
  id           uuid primary key default gen_random_uuid(),
  name         text not null check (char_length(name) between 2 and 40),
  pin          text not null check (pin ~ '^[0-9]{4}$'),
  badge        text check (badge is null or char_length(badge) between 1 and 40),
  status       text not null default 'active' check (status in ('pending', 'active', 'removed')),
  self_signup  boolean not null default false,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
-- Two people who can clock in can't share a PIN or a badge.
create unique index staff_pin_in_use   on public.staff (pin)          where status <> 'removed';
create unique index staff_badge_in_use on public.staff (lower(badge)) where status <> 'removed' and badge is not null;

create table public.staff_shifts (
  id          uuid primary key default gen_random_uuid(),
  staff_id    uuid references public.staff (id) on delete set null,
  staff_name  text not null,
  clock_in    timestamptz not null,
  clock_out   timestamptz check (clock_out is null or clock_out >= clock_in),
  manual      boolean not null default false,   -- added or fixed by staff, not punched
  undo_token  text,
  undo_kind   text check (undo_kind in ('in', 'out')),
  undo_until  timestamptz,
  created_at  timestamptz not null default now()
);
-- Nobody can be clocked in twice at once.
create unique index staff_shifts_one_open on public.staff_shifts (staff_id) where clock_out is null;
create index on public.staff_shifts (clock_in desc);
create index on public.staff_shifts (staff_id, clock_in);

create table public.staff_schedule (
  id          uuid primary key default gen_random_uuid(),
  staff_id    uuid not null references public.staff (id) on delete cascade,
  work_date   date not null,
  window_id   int  not null references public.pickup_windows (id) on delete cascade,
  note        text check (note is null or char_length(note) <= 80),
  created_at  timestamptz not null default now(),
  unique (staff_id, work_date, window_id)
);
create index on public.staff_schedule (work_date, window_id);

create table public.staff_credit_entries (
  id            uuid primary key default gen_random_uuid(),
  staff_id      uuid not null references public.staff (id) on delete cascade,
  amount_cents  int  not null check (amount_cents <> 0 and amount_cents between -100000 and 100000),
  note          text check (note is null or char_length(note) <= 120),
  created_at    timestamptz not null default now()
);
create index on public.staff_credit_entries (staff_id, created_at desc);

create table public.staff_clock_attempts (
  ip_hash     text not null,
  kind        text not null check (kind in ('pin', 'signup')),
  created_at  timestamptz not null default now()
);
create index on public.staff_clock_attempts (ip_hash, kind, created_at);


-- -----------------------------------------------------------------------------
-- 3. Store credit
-- -----------------------------------------------------------------------------
-- Per employee: minutes worked (finished shifts), credit earned from them,
-- credit added/used by hand, what's left, and minutes until the next dollar.
-- Runs as the caller, so Row Level Security decides who sees what (the admin
-- sees everyone; students see nothing).
create or replace function public.staff_credit_balances()
returns table (
  staff_id            uuid,
  worked_minutes      int,
  earned_cents        int,
  adjust_cents        int,
  balance_cents       int,
  next_credit_minutes int
)
language sql stable
set search_path = public
as $$
  with rate as (
    select staff_credit_cents as cents, staff_credit_minutes as minutes from public.settings where id = 1
  ),
  worked as (
    select sh.staff_id, floor(sum(extract(epoch from (sh.clock_out - sh.clock_in))) / 60)::int as minutes
      from public.staff_shifts sh
     where sh.clock_out is not null and sh.staff_id is not null
     group by sh.staff_id
  ),
  adjusted as (
    select e.staff_id, sum(e.amount_cents)::int as cents from public.staff_credit_entries e group by e.staff_id
  )
  select s.id,
         coalesce(w.minutes, 0),
         (coalesce(w.minutes, 0) / rate.minutes) * rate.cents,
         coalesce(a.cents, 0),
         (coalesce(w.minutes, 0) / rate.minutes) * rate.cents + coalesce(a.cents, 0),
         rate.minutes - (coalesce(w.minutes, 0) % rate.minutes)
    from public.staff s
    cross join rate
    left join worked   w on w.staff_id = s.id
    left join adjusted a on a.staff_id = s.id;
$$;

-- Staff record credit an employee used at the window (a minus amount), or add
-- some by hand (a plus amount). Using more than they have is refused.
create or replace function public.staff_credit_add(p_staff_id uuid, p_amount_cents int, p_note text)
returns int
language plpgsql security definer
set search_path = public
as $$
declare
  v_balance int;
begin
  if not public.is_admin() then
    raise exception 'Only staff can change store credit.';
  end if;
  if p_amount_cents is null or p_amount_cents = 0 or abs(p_amount_cents) > 100000 then
    raise exception 'Enter an amount.';
  end if;
  perform 1 from public.staff where id = p_staff_id for update;
  if not found then
    raise exception 'That employee is gone.';
  end if;
  select balance_cents into v_balance from public.staff_credit_balances() where staff_id = p_staff_id;
  if v_balance + p_amount_cents < 0 then
    raise exception 'Only $% of credit left.', to_char(v_balance / 100.0, 'FM999990.00');
  end if;
  insert into public.staff_credit_entries (staff_id, amount_cents, note)
  values (p_staff_id, p_amount_cents, nullif(left(btrim(coalesce(p_note, '')), 120), ''));
  return v_balance + p_amount_cents;
end;
$$;


-- -----------------------------------------------------------------------------
-- 4. The time clock (called only by the website's server)
-- -----------------------------------------------------------------------------

-- An employee's next scheduled class hour that hasn't started yet, or null.
create or replace function public.staff_next_shift(p_staff_id uuid)
returns jsonb
language sql stable security definer
set search_path = public
as $$
  select jsonb_build_object('date', sc.work_date, 'label', w.label, 'startsAt', to_char(w.starts_at, 'HH24:MI'))
    from public.staff_schedule sc
    join public.pickup_windows w on w.id = sc.window_id
   where sc.staff_id = p_staff_id
     and (sc.work_date > public.store_today()
          or (sc.work_date = public.store_today() and w.starts_at > public.store_now_time()))
   order by sc.work_date, w.starts_at
   limit 1;
$$;

-- Clock in or out. p_code is a 4-digit PIN or a scanned badge.
-- Returns { status: 'in' | 'out' | 'pending', name, ... } or { error, code }.
create or replace function public.staff_punch(p_code text, p_ip_hash text)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_code   text := btrim(coalesce(p_code, ''));
  v_now    timestamptz := now();
  v_tz     text := (select timezone from public.settings where id = 1);
  v_week   timestamptz;
  v_staff  public.staff;
  v_open   public.staff_shifts;
  v_id     uuid;
  v_in     timestamptz;
  v_token  text := replace(gen_random_uuid()::text, '-', '');
  v_status text;
  v_credit record;
begin
  v_week := date_trunc('week', v_now at time zone v_tz) at time zone v_tz;  -- Monday, 12:00 AM

  -- 8 wrong tries in 15 minutes locks this device out for a while.
  if p_ip_hash is not null and (
    select count(*) from public.staff_clock_attempts
     where ip_hash = p_ip_hash and kind = 'pin' and created_at > v_now - interval '15 minutes'
  ) >= 8 then
    return jsonb_build_object('error', 'Too many wrong tries. Wait 15 minutes or ask a manager.', 'code', 'LOCKED');
  end if;

  if v_code <> '' and char_length(v_code) <= 40 then
    select * into v_staff from public.staff
     where status <> 'removed' and (pin = v_code or (badge is not null and lower(badge) = lower(v_code)))
     limit 1;
  end if;

  if v_staff.id is null then
    if p_ip_hash is not null then
      insert into public.staff_clock_attempts (ip_hash, kind) values (p_ip_hash, 'pin');
    end if;
    delete from public.staff_clock_attempts where created_at < v_now - interval '1 day';
    return jsonb_build_object('error', 'No account has that PIN. Try again, or tap Create account if you''re new.', 'code', 'NOT_FOUND');
  end if;

  if v_staff.status = 'pending' then
    return jsonb_build_object('status', 'pending', 'name', v_staff.name);
  end if;

  select * into v_open from public.staff_shifts where staff_id = v_staff.id and clock_out is null for update;
  if v_open.id is not null then
    update public.staff_shifts
       set clock_out = v_now, undo_token = v_token, undo_kind = 'out', undo_until = v_now + interval '2 minutes'
     where id = v_open.id;
    v_id := v_open.id; v_in := v_open.clock_in; v_status := 'out';
  else
    insert into public.staff_shifts (staff_id, staff_name, clock_in, undo_token, undo_kind, undo_until)
    values (v_staff.id, v_staff.name, v_now, v_token, 'in', v_now + interval '2 minutes')
    returning id into v_id;
    v_in := v_now; v_status := 'in';
  end if;

  select * into v_credit from public.staff_credit_balances() b where b.staff_id = v_staff.id;

  return jsonb_build_object(
    'status', v_status,
    'name', v_staff.name,
    'in', v_in,
    'out', case when v_status = 'out' then v_now end,
    'id', v_id,
    'undo', v_token,
    'weekMinutes', (
      select coalesce(floor(sum(extract(epoch from (coalesce(clock_out, v_now) - clock_in))) / 60), 0)::int
        from public.staff_shifts where staff_id = v_staff.id and clock_in >= v_week
    ),
    'creditCents', coalesce(v_credit.balance_cents, 0),
    'nextCreditMinutes', v_credit.next_credit_minutes,
    'next', public.staff_next_shift(v_staff.id)
  );
end;
$$;

-- Undo a punch (tapped by mistake) within 2 minutes.
create or replace function public.staff_punch_undo(p_shift_id uuid, p_token text)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_shift public.staff_shifts;
begin
  select * into v_shift from public.staff_shifts
   where id = p_shift_id and undo_token = p_token and undo_until > now()
   for update;
  if v_shift.id is null then
    return jsonb_build_object('error', 'Too late to undo. Ask a manager to fix it.');
  end if;
  if v_shift.undo_kind = 'in' then
    delete from public.staff_shifts where id = v_shift.id;
  else
    begin
      update public.staff_shifts set clock_out = null, undo_token = null, undo_kind = null, undo_until = null where id = v_shift.id;
    exception when unique_violation then
      return jsonb_build_object('error', 'You''re already clocked in again. Ask a manager to fix it.');
    end;
  end if;
  return jsonb_build_object('ok', true);
end;
$$;

-- "Create account" on the time clock. New accounts wait for approval unless
-- that's switched off (Admin → Employees).
create or replace function public.staff_signup(p_name text, p_pin text, p_badge text, p_ip_hash text)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_name    text := regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g');
  v_pin     text := btrim(coalesce(p_pin, ''));
  v_badge   text := nullif(btrim(coalesce(p_badge, '')), '');
  v_pending boolean := (select staff_signup_approval from public.settings where id = 1);
begin
  -- At most 6 sign-ups (or tries at a taken PIN) per device per hour.
  if p_ip_hash is not null and (
    select count(*) from public.staff_clock_attempts
     where ip_hash = p_ip_hash and kind = 'signup' and created_at > now() - interval '1 hour'
  ) >= 6 then
    return jsonb_build_object('error', 'Too many new accounts from this device. Try again later or ask a manager.');
  end if;
  if char_length(v_name) < 2 or char_length(v_name) > 40 then
    return jsonb_build_object('error', 'Enter your name.', 'field', 'name');
  end if;
  if v_pin !~ '^[0-9]{4}$' then
    return jsonb_build_object('error', 'Your PIN must be exactly 4 numbers.', 'field', 'pin');
  end if;
  if v_badge is not null and char_length(v_badge) > 40 then
    return jsonb_build_object('error', 'That student ID is too long.', 'field', 'badge');
  end if;
  if p_ip_hash is not null then
    insert into public.staff_clock_attempts (ip_hash, kind) values (p_ip_hash, 'signup');
  end if;
  if exists (select 1 from public.staff where status <> 'removed' and pin = v_pin) then
    return jsonb_build_object('error', 'That PIN is already taken. Pick a different one.', 'field', 'pin');
  end if;
  if v_badge is not null and exists (select 1 from public.staff where status <> 'removed' and lower(badge) = lower(v_badge)) then
    return jsonb_build_object('error', 'That student ID is already linked to an account.', 'field', 'badge');
  end if;
  begin
    insert into public.staff (name, pin, badge, status, self_signup)
    values (v_name, v_pin, v_badge, case when v_pending then 'pending' else 'active' end, true);
  exception when unique_violation then
    return jsonb_build_object('error', 'That PIN is already taken. Pick a different one.', 'field', 'pin');
  end;
  return jsonb_build_object('ok', true, 'pending', v_pending, 'name', v_name);
end;
$$;

-- What the time clock screen shows: who's on the clock, today's finished
-- shifts, and the schedule for the next two weeks. Names only.
create or replace function public.staff_board()
returns jsonb
language plpgsql stable security definer
set search_path = public
as $$
declare
  v_tz    text := (select timezone from public.settings where id = 1);
  v_today date := public.store_today();
  v_start timestamptz := v_today::timestamp at time zone v_tz;
  v_time  time := public.store_now_time();
begin
  return jsonb_build_object(
    'onClock', (
      select coalesce(jsonb_agg(jsonb_build_object('name', coalesce(s.name, sh.staff_name), 'in', sh.clock_in) order by sh.clock_in), '[]'::jsonb)
        from public.staff_shifts sh left join public.staff s on s.id = sh.staff_id
       where sh.clock_out is null
    ),
    'today', (
      select coalesce(jsonb_agg(jsonb_build_object('name', t.name, 'in', t.clock_in, 'out', t.clock_out) order by t.clock_out desc), '[]'::jsonb)
        from (
          select coalesce(s.name, sh.staff_name) as name, sh.clock_in, sh.clock_out
            from public.staff_shifts sh left join public.staff s on s.id = sh.staff_id
           where sh.clock_out is not null and sh.clock_in >= v_start
           order by sh.clock_out desc
           limit 20
        ) t
    ),
    -- A class hour stays on the list until about the end of it.
    'upcoming', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'date', u.work_date, 'label', u.label, 'startsAt', to_char(u.starts_at, 'HH24:MI'), 'name', u.name
             ) order by u.work_date, u.starts_at, u.sort_order, u.name), '[]'::jsonb)
        from (
          select sc.work_date, w.label, w.starts_at, w.sort_order, s.name
            from public.staff_schedule sc
            join public.pickup_windows w on w.id = sc.window_id
            join public.staff s on s.id = sc.staff_id and s.status = 'active'
           where sc.work_date between v_today and v_today + 14
             and (sc.work_date > v_today or w.starts_at > v_time - interval '50 minutes')
           order by sc.work_date, w.starts_at, s.name
           limit 80
        ) u
    ),
    'signupApproval', (select staff_signup_approval from public.settings where id = 1)
  );
end;
$$;


-- -----------------------------------------------------------------------------
-- 5. Security
-- -----------------------------------------------------------------------------
alter table public.staff                enable row level security;
alter table public.staff_shifts         enable row level security;
alter table public.staff_schedule       enable row level security;
alter table public.staff_credit_entries enable row level security;
alter table public.staff_clock_attempts enable row level security;

create policy "admin full access" on public.staff                for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admin full access" on public.staff_shifts         for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admin full access" on public.staff_schedule       for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admin full access" on public.staff_credit_entries for all to authenticated using (public.is_admin()) with check (public.is_admin());
-- staff_clock_attempts: no policy at all, so only the database functions touch it.

revoke execute on function public.staff_credit_balances()            from public, anon;
revoke execute on function public.staff_credit_add(uuid, int, text)  from public, anon;
revoke execute on function public.staff_next_shift(uuid)             from public, anon, authenticated;
revoke execute on function public.staff_punch(text, text)            from public, anon, authenticated;
revoke execute on function public.staff_punch_undo(uuid, text)       from public, anon, authenticated;
revoke execute on function public.staff_signup(text, text, text, text) from public, anon, authenticated;
revoke execute on function public.staff_board()                      from public, anon, authenticated;

grant execute on function public.staff_credit_balances()             to authenticated, service_role;
grant execute on function public.staff_credit_add(uuid, int, text)   to authenticated;
grant execute on function public.staff_punch(text, text)             to service_role;
grant execute on function public.staff_punch_undo(uuid, text)        to service_role;
grant execute on function public.staff_signup(text, text, text, text) to service_role;
grant execute on function public.staff_board()                       to service_role;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261109000016_employee_app.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- Employee app: new store-credit rule, phone sign-in, live time clock (update 16)
-- =============================================================================
-- Builds on update 15 (the time clock).
--
-- NEW CREDIT RULE (counted per week, Monday to Sunday, Arizona time):
--   * Every whole hour worked this week adds 10% off everything, up to 50% at
--     5 hours. The discount starts over each Monday.
--   * Every whole hour after the first 5 in a week adds $1 of store credit.
--     Credit dollars stay until they're spent.
--   All three numbers (10%, 5 hours, $1) are settings on Admin → Store credit.
--   Credit is still worked out from the timecards, so fixing a shift fixes it.
--
-- EMPLOYEE PORTAL (the app at /work): employees sign in with their name and
-- their 4-digit PIN, then clock in and out from their phone and see their
-- hours, discount, credit and schedule. Signing in makes a session (a random
-- token kept in a cookie; only its hash is stored here). Changing someone's PIN
-- or removing them signs them out everywhere. Wrong tries lock out the device
-- (8 in 15 minutes) and the employee's account (10 in an hour).
--
-- LIVE: the staff dashboard listens for punches (Supabase Realtime) and
-- updates by itself.
-- =============================================================================


-- -----------------------------------------------------------------------------
-- 1. Settings and columns
-- -----------------------------------------------------------------------------
alter table public.settings
  add column staff_discount_pct_per_hour int not null default 10  check (staff_discount_pct_per_hour between 0 and 100),
  add column staff_credit_after_hours    int not null default 5   check (staff_credit_after_hours between 0 and 40),
  add column staff_credit_cents_per_hour int not null default 100 check (staff_credit_cents_per_hour between 0 and 2000);
-- (staff_credit_cents and staff_credit_minutes from update 15 are no longer used.)

-- Where a punch came from: the time clock screen, someone's phone, or staff fixing it.
alter table public.staff_shifts
  add column source     text not null default 'kiosk' check (source in ('kiosk', 'phone', 'manual')),
  add column out_source text check (out_source in ('kiosk', 'phone', 'manual'));
update public.staff_shifts set source = 'manual' where manual;
update public.staff_shifts set out_source = source where clock_out is not null;

alter table public.staff_clock_attempts drop constraint staff_clock_attempts_kind_check;
alter table public.staff_clock_attempts add constraint staff_clock_attempts_kind_check check (kind in ('pin', 'signup', 'portal'));

create table public.staff_sessions (
  token_hash  text primary key,
  staff_id    uuid not null references public.staff (id) on delete cascade,
  user_agent  text,
  created_at  timestamptz not null default now(),
  last_seen   timestamptz not null default now()
);
create index on public.staff_sessions (staff_id);
alter table public.staff_sessions enable row level security;
-- No policies: only the database functions below (run by the website's server) use it.

-- A new PIN, or being removed, signs that person out on every phone.
create or replace function public.staff_sessions_reset()
returns trigger
language plpgsql security definer
set search_path = public
as $$
begin
  if new.pin is distinct from old.pin or new.status <> 'active' then
    delete from public.staff_sessions where staff_id = new.id;
  end if;
  return new;
end;
$$;
create trigger staff_sessions_reset after update of pin, status on public.staff
  for each row execute function public.staff_sessions_reset();


-- -----------------------------------------------------------------------------
-- 2. Store credit and discount
-- -----------------------------------------------------------------------------
-- Return columns changed, so the old function is replaced, not edited.
drop function public.staff_credit_balances();

-- Per employee:
--   worked_minutes       all finished shifts, ever
--   week_minutes         this week so far (counts a shift that's still going)
--   discount_pct         10% per whole hour this week, up to 5 hours' worth
--   earned_cents         $1 per whole hour past 5 in each week (finished shifts)
--   adjust_cents         credit used (minus) or added by hand (plus)
--   balance_cents        earned + adjust: what they can spend
--   next_credit_minutes  minutes until their next whole hour this week
create function public.staff_credit_balances()
returns table (
  staff_id            uuid,
  worked_minutes      int,
  week_minutes        int,
  discount_pct        int,
  earned_cents        int,
  adjust_cents        int,
  balance_cents       int,
  next_credit_minutes int
)
language sql stable
set search_path = public
as $$
  with cfg as (
    select timezone as tz,
           staff_discount_pct_per_hour as pct,
           staff_credit_after_hours    as after_hours,
           staff_credit_cents_per_hour as cents
      from public.settings where id = 1
  ),
  per_week as (
    select sh.staff_id,
           date_trunc('week', sh.clock_in at time zone cfg.tz) as week,
           coalesce(sum(extract(epoch from (sh.clock_out - sh.clock_in))) filter (where sh.clock_out is not null), 0) as done_secs,
           sum(extract(epoch from (coalesce(sh.clock_out, now()) - sh.clock_in))) as all_secs
      from public.staff_shifts sh cross join cfg
     where sh.staff_id is not null
     group by sh.staff_id, 2
  ),
  earned as (
    select pw.staff_id,
           sum(floor(pw.done_secs / 60))::int as minutes,
           sum(greatest(0, floor(pw.done_secs / 3600)::int - cfg.after_hours) * cfg.cents)::int as cents
      from per_week pw cross join cfg
     group by pw.staff_id
  ),
  this_week as (
    select pw.staff_id, floor(pw.all_secs / 60)::int as minutes
      from per_week pw cross join cfg
     where pw.week = date_trunc('week', now() at time zone cfg.tz)
  ),
  adjusted as (
    select e.staff_id, sum(e.amount_cents)::int as cents from public.staff_credit_entries e group by e.staff_id
  )
  select s.id,
         coalesce(e.minutes, 0),
         coalesce(w.minutes, 0),
         (least(coalesce(w.minutes, 0) / 60, cfg.after_hours) * cfg.pct)::int,
         coalesce(e.cents, 0),
         coalesce(a.cents, 0),
         coalesce(e.cents, 0) + coalesce(a.cents, 0),
         60 - (coalesce(w.minutes, 0) % 60)
    from public.staff s
    cross join cfg
    left join earned    e on e.staff_id = s.id
    left join this_week w on w.staff_id = s.id
    left join adjusted  a on a.staff_id = s.id;
$$;

revoke execute on function public.staff_credit_balances() from public, anon;
grant execute on function public.staff_credit_balances() to authenticated, service_role;


-- -----------------------------------------------------------------------------
-- 3. Clocking in and out (shared by the time clock screen and phones)
-- -----------------------------------------------------------------------------
create or replace function public.staff_punch_for(p_staff public.staff, p_source text)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_now    timestamptz := now();
  v_open   public.staff_shifts;
  v_id     uuid;
  v_in     timestamptz;
  v_token  text := replace(gen_random_uuid()::text, '-', '');
  v_status text;
  v_credit record;
begin
  select * into v_open from public.staff_shifts where staff_id = p_staff.id and clock_out is null for update;
  if v_open.id is not null then
    update public.staff_shifts
       set clock_out = v_now, out_source = p_source, undo_token = v_token, undo_kind = 'out', undo_until = v_now + interval '2 minutes'
     where id = v_open.id;
    v_id := v_open.id; v_in := v_open.clock_in; v_status := 'out';
  else
    insert into public.staff_shifts (staff_id, staff_name, clock_in, source, undo_token, undo_kind, undo_until)
    values (p_staff.id, p_staff.name, v_now, p_source, v_token, 'in', v_now + interval '2 minutes')
    returning id into v_id;
    v_in := v_now; v_status := 'in';
  end if;

  select * into v_credit from public.staff_credit_balances() b where b.staff_id = p_staff.id;

  return jsonb_build_object(
    'status', v_status,
    'name', p_staff.name,
    'in', v_in,
    'out', case when v_status = 'out' then v_now end,
    'id', v_id,
    'undo', v_token,
    'weekMinutes', coalesce(v_credit.week_minutes, 0),
    'discountPct', coalesce(v_credit.discount_pct, 0),
    'creditCents', coalesce(v_credit.balance_cents, 0),
    'nextCreditMinutes', coalesce(v_credit.next_credit_minutes, 60),
    'next', public.staff_next_shift(p_staff.id)
  );
end;
$$;

-- The time clock screen (/clock): PIN or badge.
create or replace function public.staff_punch(p_code text, p_ip_hash text)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_code  text := btrim(coalesce(p_code, ''));
  v_staff public.staff;
begin
  if p_ip_hash is not null and (
    select count(*) from public.staff_clock_attempts
     where ip_hash = p_ip_hash and kind = 'pin' and created_at > now() - interval '15 minutes'
  ) >= 8 then
    return jsonb_build_object('error', 'Too many wrong tries. Wait 15 minutes or ask a manager.', 'code', 'LOCKED');
  end if;

  if v_code <> '' and char_length(v_code) <= 40 then
    select * into v_staff from public.staff
     where status <> 'removed' and (pin = v_code or (badge is not null and lower(badge) = lower(v_code)))
     limit 1;
  end if;

  if v_staff.id is null then
    if p_ip_hash is not null then
      insert into public.staff_clock_attempts (ip_hash, kind) values (p_ip_hash, 'pin');
    end if;
    delete from public.staff_clock_attempts where created_at < now() - interval '1 day';
    return jsonb_build_object('error', 'No account has that PIN. Try again, or tap Create account if you''re new.', 'code', 'NOT_FOUND');
  end if;

  if v_staff.status = 'pending' then
    return jsonb_build_object('status', 'pending', 'name', v_staff.name);
  end if;

  return public.staff_punch_for(v_staff, 'kiosk');
end;
$$;


-- -----------------------------------------------------------------------------
-- 4. The employee portal (/work)
-- -----------------------------------------------------------------------------
-- "Maya R." → "mayar": names match however they're typed.
create or replace function public.staff_name_key(p_name text)
returns text
language sql immutable
as $$ select lower(regexp_replace(coalesce(p_name, ''), '[^A-Za-z0-9]', '', 'g')) $$;

-- Sign in with name + PIN. p_token_hash is the hash of a random token the
-- website puts in a cookie. Returns { ok, name } or { error, code }.
create or replace function public.staff_portal_login(p_name text, p_pin text, p_token_hash text, p_ip_hash text, p_user_agent text)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_key   text := public.staff_name_key(p_name);
  v_pin   text := btrim(coalesce(p_pin, ''));
  v_staff public.staff;
  v_count int;
  v_wrong constant text := 'That name and PIN don''t match. Use your name the way your manager has it, and your time clock PIN.';
begin
  if p_ip_hash is not null and (
    select count(*) from public.staff_clock_attempts
     where ip_hash = p_ip_hash and kind = 'portal' and created_at > now() - interval '15 minutes'
  ) >= 8 then
    return jsonb_build_object('error', 'Too many wrong tries on this phone. Wait 15 minutes, or ask a manager.', 'code', 'LOCKED');
  end if;
  if v_key = '' or v_pin !~ '^[0-9]{4}$' or p_token_hash is null or char_length(p_token_hash) < 32 then
    return jsonb_build_object('error', 'Type your name and your 4-digit PIN.', 'code', 'INVALID');
  end if;

  -- Full name first; if nobody matches, a first name that only one person has.
  select count(*) into v_count from public.staff where status <> 'removed' and public.staff_name_key(name) = v_key;
  if v_count = 1 then
    select * into v_staff from public.staff where status <> 'removed' and public.staff_name_key(name) = v_key;
  elsif v_count = 0 then
    select count(*) into v_count from public.staff where status <> 'removed' and public.staff_name_key(split_part(name, ' ', 1)) = v_key;
    if v_count = 1 then
      select * into v_staff from public.staff where status <> 'removed' and public.staff_name_key(split_part(name, ' ', 1)) = v_key;
    elsif v_count > 1 then
      return jsonb_build_object('error', 'More than one employee has that first name. Type your full name, like "Maya R".', 'code', 'AMBIGUOUS');
    end if;
  end if;

  -- The employee's own account locks after 10 wrong PINs in an hour, from anywhere.
  if v_staff.id is not null and (
    select count(*) from public.staff_clock_attempts
     where ip_hash = 'staff:' || v_staff.id and kind = 'portal' and created_at > now() - interval '1 hour'
  ) >= 10 then
    return jsonb_build_object('error', 'This account is locked for an hour after too many wrong PINs. Ask a manager.', 'code', 'LOCKED');
  end if;

  if v_staff.id is null or v_staff.pin <> v_pin then
    if p_ip_hash is not null then
      insert into public.staff_clock_attempts (ip_hash, kind) values (p_ip_hash, 'portal');
    end if;
    if v_staff.id is not null then
      insert into public.staff_clock_attempts (ip_hash, kind) values ('staff:' || v_staff.id, 'portal');
    end if;
    delete from public.staff_clock_attempts where created_at < now() - interval '1 day';
    return jsonb_build_object('error', v_wrong, 'code', 'NOT_FOUND');
  end if;

  if v_staff.status = 'pending' then
    return jsonb_build_object('error', 'Your account is waiting for a manager to approve it.', 'code', 'PENDING');
  end if;

  delete from public.staff_sessions where last_seen < now() - interval '90 days';
  insert into public.staff_sessions (token_hash, staff_id, user_agent)
  values (p_token_hash, v_staff.id, left(p_user_agent, 200));
  return jsonb_build_object('ok', true, 'name', v_staff.name);
end;
$$;

-- The signed-in employee, or null if the session is gone.
create or replace function public.staff_portal_staff(p_token_hash text)
returns public.staff
language plpgsql security definer
set search_path = public
as $$
declare
  v_staff public.staff;
begin
  update public.staff_sessions set last_seen = now()
   where token_hash = p_token_hash and last_seen < now() - interval '5 minutes';
  select s.* into v_staff
    from public.staff_sessions ss join public.staff s on s.id = ss.staff_id
   where ss.token_hash = p_token_hash and s.status = 'active';
  return v_staff;
end;
$$;

-- Everything the portal shows. Returns null when signed out.
create or replace function public.staff_portal(p_token_hash text)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_staff  public.staff := public.staff_portal_staff(p_token_hash);
  v_credit record;
  v_cfg    record;
begin
  if v_staff.id is null then
    return null;
  end if;
  select * into v_credit from public.staff_credit_balances() b where b.staff_id = v_staff.id;
  select staff_discount_pct_per_hour as pct, staff_credit_after_hours as after_hours, staff_credit_cents_per_hour as cents
    into v_cfg from public.settings where id = 1;

  return jsonb_build_object(
    'id', v_staff.id,
    'name', v_staff.name,
    'open', (
      select jsonb_build_object('id', id, 'in', clock_in, 'source', source)
        from public.staff_shifts where staff_id = v_staff.id and clock_out is null
    ),
    'weekMinutes', coalesce(v_credit.week_minutes, 0),
    'discountPct', coalesce(v_credit.discount_pct, 0),
    'creditCents', coalesce(v_credit.balance_cents, 0),
    'earnedCents', coalesce(v_credit.earned_cents, 0),
    'workedMinutes', coalesce(v_credit.worked_minutes, 0),
    'rule', jsonb_build_object('pct', v_cfg.pct, 'afterHours', v_cfg.after_hours, 'cents', v_cfg.cents),
    'schedule', (
      select coalesce(jsonb_agg(jsonb_build_object('date', t.work_date, 'label', t.label, 'startsAt', to_char(t.starts_at, 'HH24:MI'))
                                order by t.work_date, t.starts_at), '[]'::jsonb)
        from (
          select sc.work_date, w.label, w.starts_at
            from public.staff_schedule sc join public.pickup_windows w on w.id = sc.window_id
           where sc.staff_id = v_staff.id
             and sc.work_date between public.store_today() and public.store_today() + 21
             and (sc.work_date > public.store_today() or w.starts_at > public.store_now_time() - interval '50 minutes')
           order by sc.work_date, w.starts_at
           limit 15
        ) t
    ),
    'shifts', (
      select coalesce(jsonb_agg(jsonb_build_object('in', t.clock_in, 'out', t.clock_out, 'phone', t.source = 'phone' or t.out_source = 'phone') order by t.clock_in desc), '[]'::jsonb)
        from (
          select clock_in, clock_out, source, out_source from public.staff_shifts
           where staff_id = v_staff.id order by clock_in desc limit 12
        ) t
    ),
    'credit', (
      select coalesce(jsonb_agg(jsonb_build_object('cents', t.amount_cents, 'note', t.note, 'at', t.created_at) order by t.created_at desc), '[]'::jsonb)
        from (
          select amount_cents, note, created_at from public.staff_credit_entries
           where staff_id = v_staff.id order by created_at desc limit 10
        ) t
    )
  );
end;
$$;

-- Clock in or out from the phone.
create or replace function public.staff_portal_punch(p_token_hash text)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_staff public.staff := public.staff_portal_staff(p_token_hash);
begin
  if v_staff.id is null then
    return jsonb_build_object('error', 'You''re signed out. Sign in again.', 'code', 'SIGNED_OUT');
  end if;
  return public.staff_punch_for(v_staff, 'phone');
end;
$$;

create or replace function public.staff_portal_logout(p_token_hash text)
returns void
language sql security definer
set search_path = public
as $$ delete from public.staff_sessions where token_hash = p_token_hash $$;


-- -----------------------------------------------------------------------------
-- 5. Live updates on the staff dashboard (Supabase Realtime)
-- -----------------------------------------------------------------------------
-- Only the admin can read staff_shifts (Row Level Security), so only the admin
-- hears about punches.
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'staff_shifts') then
    alter publication supabase_realtime add table public.staff_shifts;
  end if;
end;
$$;


-- -----------------------------------------------------------------------------
-- 6. Who may call what
-- -----------------------------------------------------------------------------
revoke execute on function public.staff_punch_for(public.staff, text)                   from public, anon, authenticated;
revoke execute on function public.staff_portal_login(text, text, text, text, text)       from public, anon, authenticated;
revoke execute on function public.staff_portal_staff(text)                               from public, anon, authenticated;
revoke execute on function public.staff_portal(text)                                     from public, anon, authenticated;
revoke execute on function public.staff_portal_punch(text)                               from public, anon, authenticated;
revoke execute on function public.staff_portal_logout(text)                              from public, anon, authenticated;
revoke execute on function public.staff_sessions_reset()                                 from public, anon, authenticated;

grant execute on function public.staff_portal_login(text, text, text, text, text) to service_role;
grant execute on function public.staff_portal(text)                               to service_role;
grant execute on function public.staff_portal_punch(text)                         to service_role;
grant execute on function public.staff_portal_logout(text)                        to service_role;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261109000017_auto_clock_out.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- Automatic clock-out (update 17)
-- =============================================================================
-- Nobody stays on the clock longer than 1 hour 15 minutes: a shift still open
-- after that is ended automatically at exactly 1h 15m after it started (so a
-- forgotten clock-out doesn't add hours or credit). Change the limit on
-- Admin → Timecards (0 turns it off).
--
-- It runs every minute (pg_cron), and also right before every punch, so it
-- works even if pg_cron isn't on.
--
-- If someone was clocked out automatically and then types their PIN (they
-- meant to clock out), that punch doesn't start a new shift: it tells them
-- they were already clocked out automatically. Their next punch clocks in.
-- =============================================================================

alter table public.settings
  add column staff_max_shift_minutes int not null default 75 check (staff_max_shift_minutes between 0 and 720);

alter table public.staff_shifts drop constraint staff_shifts_out_source_check;
alter table public.staff_shifts add constraint staff_shifts_out_source_check check (out_source in ('kiosk', 'phone', 'manual', 'auto'));
-- Whether the employee has been told about their automatic clock-out yet.
alter table public.staff_shifts add column auto_seen boolean not null default false;


-- Ends every shift that has gone past the limit. Returns how many it ended.
create or replace function public.staff_auto_clock_out()
returns int
language plpgsql security definer
set search_path = public
as $$
declare
  v_max int := (select staff_max_shift_minutes from public.settings where id = 1);
  v_count int;
begin
  if coalesce(v_max, 0) <= 0 then
    return 0;
  end if;
  update public.staff_shifts
     set clock_out = clock_in + make_interval(mins => v_max),
         out_source = 'auto',
         undo_token = null, undo_kind = null, undo_until = null
   where clock_out is null
     and clock_in + make_interval(mins => v_max) <= now();
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


-- Clocking in and out (time clock screen and phones), now with the limit.
create or replace function public.staff_punch_for(p_staff public.staff, p_source text)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_now    timestamptz := now();
  v_open   public.staff_shifts;
  v_auto   public.staff_shifts;
  v_id     uuid;
  v_in     timestamptz;
  v_token  text := replace(gen_random_uuid()::text, '-', '');
  v_status text;
  v_credit record;
  v_max    int := (select staff_max_shift_minutes from public.settings where id = 1);
begin
  perform public.staff_auto_clock_out();

  select * into v_open from public.staff_shifts where staff_id = p_staff.id and clock_out is null for update;

  if v_open.id is null then
    -- Clocked out automatically and not told yet: say so instead of clocking in.
    select * into v_auto from public.staff_shifts
     where staff_id = p_staff.id and out_source = 'auto' and not auto_seen and clock_out > v_now - interval '12 hours'
     order by clock_out desc limit 1
     for update;
    if v_auto.id is not null then
      update public.staff_shifts set auto_seen = true where staff_id = p_staff.id and out_source = 'auto' and not auto_seen;
      select * into v_credit from public.staff_credit_balances() b where b.staff_id = p_staff.id;
      return jsonb_build_object(
        'status', 'auto',
        'name', p_staff.name,
        'in', v_auto.clock_in,
        'out', v_auto.clock_out,
        'weekMinutes', coalesce(v_credit.week_minutes, 0),
        'discountPct', coalesce(v_credit.discount_pct, 0),
        'creditCents', coalesce(v_credit.balance_cents, 0),
        'next', public.staff_next_shift(p_staff.id)
      );
    end if;
  end if;

  if v_open.id is not null then
    update public.staff_shifts
       set clock_out = v_now, out_source = p_source, undo_token = v_token, undo_kind = 'out', undo_until = v_now + interval '2 minutes'
     where id = v_open.id;
    v_id := v_open.id; v_in := v_open.clock_in; v_status := 'out';
  else
    insert into public.staff_shifts (staff_id, staff_name, clock_in, source, undo_token, undo_kind, undo_until)
    values (p_staff.id, p_staff.name, v_now, p_source, v_token, 'in', v_now + interval '2 minutes')
    returning id into v_id;
    v_in := v_now; v_status := 'in';
  end if;

  select * into v_credit from public.staff_credit_balances() b where b.staff_id = p_staff.id;

  return jsonb_build_object(
    'status', v_status,
    'name', p_staff.name,
    'in', v_in,
    'out', case when v_status = 'out' then v_now end,
    'id', v_id,
    'undo', v_token,
    'autoOutAt', case when v_status = 'in' and coalesce(v_max, 0) > 0 then v_in + make_interval(mins => v_max) end,
    'weekMinutes', coalesce(v_credit.week_minutes, 0),
    'discountPct', coalesce(v_credit.discount_pct, 0),
    'creditCents', coalesce(v_credit.balance_cents, 0),
    'nextCreditMinutes', coalesce(v_credit.next_credit_minutes, 60),
    'next', public.staff_next_shift(p_staff.id)
  );
end;
$$;


-- Every minute (when pg_cron is available, as it is on Supabase).
do $$
begin
  if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
    create extension if not exists pg_cron;
    perform cron.schedule('staff-auto-clock-out', '* * * * *', 'select public.staff_auto_clock_out();');
  else
    raise notice 'pg_cron is not available here; shifts are ended automatically at the next punch instead.';
  end if;
end $$;

revoke execute on function public.staff_auto_clock_out() from public, anon;
grant execute on function public.staff_auto_clock_out() to authenticated, service_role;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261109000018_kiosk_lock.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- Lock the store tablet on the time clock (update 18)
-- =============================================================================
-- The store's tablet runs the time clock all day. On the dashboard the
-- manager taps "Lock tablet on time clock": that signs the manager out on the
-- tablet, remembers the tablet, and opens the time clock. On the time clock,
-- "Manager" asks for the manager code (4–6 digits); the right code signs the
-- manager back in and opens the dashboard.
--
-- The code only works on a tablet the manager locked (a random token in the
-- tablet's cookie; only its hash is stored here), and 5 wrong codes in 15
-- minutes lock that tablet out of it for 15 minutes. Anywhere else, the admin
-- password is still the only way in.
-- =============================================================================

alter table public.settings
  add column kiosk_pin_salt text,
  add column kiosk_pin_hash text;

create table public.kiosk_devices (
  token_hash  text primary key,
  label       text not null default 'Store tablet' check (char_length(label) <= 40),
  created_at  timestamptz not null default now(),
  last_used   timestamptz
);
alter table public.kiosk_devices enable row level security;
create policy "admin full access" on public.kiosk_devices for all to authenticated using (public.is_admin()) with check (public.is_admin());

create table public.kiosk_unlock_attempts (
  token_hash  text not null,
  created_at  timestamptz not null default now()
);
create index on public.kiosk_unlock_attempts (token_hash, created_at);
alter table public.kiosk_unlock_attempts enable row level security;
-- No policies: only the functions below touch it.


-- The manager sets (or changes) the code. Returns nothing; raises on a bad code.
create or replace function public.kiosk_set_pin(p_pin text)
returns void
language plpgsql security definer
set search_path = public
as $$
declare
  v_salt text := replace(gen_random_uuid()::text, '-', '');
begin
  if not public.is_admin() then
    raise exception 'Only the manager can set the manager code.';
  end if;
  if coalesce(p_pin, '') !~ '^[0-9]{4,6}$' then
    raise exception 'The manager code must be 4 to 6 numbers.';
  end if;
  if exists (select 1 from public.staff where status <> 'removed' and pin = p_pin) then
    raise exception 'An employee already uses that number as their PIN. Pick a different code.';
  end if;
  update public.settings
     set kiosk_pin_salt = v_salt,
         kiosk_pin_hash = encode(sha256(convert_to(v_salt || p_pin, 'UTF8')), 'hex'),
         updated_at = now()
   where id = 1;
end;
$$;

-- Lock: remember this tablet (the website keeps the token in its cookie).
create or replace function public.kiosk_register(p_token_hash text)
returns void
language plpgsql security definer
set search_path = public
as $$
begin
  if not public.is_admin() then
    raise exception 'Only the manager can lock a tablet.';
  end if;
  if (select kiosk_pin_hash from public.settings where id = 1) is null then
    raise exception 'Set a manager code first.';
  end if;
  insert into public.kiosk_devices (token_hash) values (p_token_hash)
  on conflict (token_hash) do update set last_used = now();
end;
$$;

-- Is this a locked store tablet? (The time clock shows the manager keypad if so.)
create or replace function public.kiosk_is_locked(p_token_hash text)
returns boolean
language sql stable security definer
set search_path = public
as $$ select exists (select 1 from public.kiosk_devices where token_hash = p_token_hash) $$;

-- Unlock: the right code on a locked tablet. Returns { ok } or { error, code }.
-- The website then signs the manager in.
create or replace function public.kiosk_unlock(p_token_hash text, p_pin text)
returns jsonb
language plpgsql security definer
set search_path = public
as $$
declare
  v_salt text;
  v_hash text;
begin
  if not exists (select 1 from public.kiosk_devices where token_hash = p_token_hash) then
    return jsonb_build_object('error', 'This device isn''t a locked store tablet. Sign in with the admin password.', 'code', 'NOT_KIOSK');
  end if;
  if (select count(*) from public.kiosk_unlock_attempts
       where token_hash = p_token_hash and created_at > now() - interval '15 minutes') >= 5 then
    return jsonb_build_object('error', 'Too many wrong codes. Wait 15 minutes, or sign in with the admin password.', 'code', 'LOCKED');
  end if;
  select kiosk_pin_salt, kiosk_pin_hash into v_salt, v_hash from public.settings where id = 1;
  if v_hash is null or encode(sha256(convert_to(v_salt || coalesce(p_pin, ''), 'UTF8')), 'hex') <> v_hash then
    insert into public.kiosk_unlock_attempts (token_hash) values (p_token_hash);
    delete from public.kiosk_unlock_attempts where created_at < now() - interval '1 day';
    return jsonb_build_object('error', 'That isn''t the manager code.', 'code', 'WRONG');
  end if;
  delete from public.kiosk_unlock_attempts where token_hash = p_token_hash;
  update public.kiosk_devices set last_used = now() where token_hash = p_token_hash;
  return jsonb_build_object('ok', true);
end;
$$;

revoke execute on function public.kiosk_set_pin(text)        from public, anon;
revoke execute on function public.kiosk_register(text)       from public, anon;
revoke execute on function public.kiosk_is_locked(text)      from public, anon, authenticated;
revoke execute on function public.kiosk_unlock(text, text)   from public, anon, authenticated;
grant execute on function public.kiosk_set_pin(text)         to authenticated;
grant execute on function public.kiosk_register(text)        to authenticated;
grant execute on function public.kiosk_is_locked(text)       to service_role;
grant execute on function public.kiosk_unlock(text, text)    to service_role;

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261110000019_receipt_inbox.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- Receipt photos from the store (update 19)
-- =============================================================================
-- While shopping, the teacher taps "Snap receipt" on the Shopping list and
-- takes a picture of the receipt. The photo goes into the private "receipts"
-- storage (the same place expense receipts already live) and a row here, so it
-- shows up under Expenses → "Receipts to enter". "Make expense" opens the
-- shopping-trip form with the photo attached; saving the trip links them.
-- =============================================================================

create table public.receipt_inbox (
  id           uuid primary key default gen_random_uuid(),
  path         text not null unique,                -- inside the private "receipts" bucket
  store        text check (store is null or char_length(store) <= 60),
  total_cents  int  check (total_cents is null or total_cents between 0 and 10000000),
  shopper      text check (shopper is null or char_length(shopper) <= 60),
  note         text check (note is null or char_length(note) <= 200),
  shopped_on   date not null default public.store_today(),
  expense_id   uuid references public.expenses (id) on delete set null,
  dismissed    boolean not null default false,
  created_at   timestamptz not null default now()
);
create index on public.receipt_inbox (created_at desc);

alter table public.receipt_inbox enable row level security;
create policy "admin full access" on public.receipt_inbox for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- >>>>>>>>>>>>>>>>>>>>>>>> 20261110000020_team_tools.sql >>>>>>>>>>>>>>>>>>>>>>>>
-- =============================================================================
-- Team tools (update 20): messages, restock photos, absences, daily tasks and
-- notifications.
-- =============================================================================
-- Everything here is read and written by the website's server (which checks
-- who's asking: the admin login, or an employee's sign-in token from update
-- 16), so the tables only need the usual "admin full access" policy.
--
--   Messages      chat_threads / chat_members / chat_messages. One "Everyone"
--                 chat for the whole team, one-on-one chats, and named group
--                 chats. A member is a staff id, or 'admin' for the manager.
--   Restocking    After each shift the employee photographs each area
--                 (settings.restock_areas: Fridge, Snacks, Ramen, Chips) fully
--                 stocked. restock_checks + restock_photos; the photos live in
--                 the private "restock" storage, seen only by the admin.
--   Absences      staff_absences: "I can't make my 5th hour on Thursday."
--   Tasks         staff_tasks: one-off (a date), weekly (a weekday) or every
--                 day; for everyone or one person. staff_task_done: who
--                 checked what off, which day.
--   Notifications push_subscriptions (web push from the browser / home-screen
--                 app), app_secrets (keys the server makes for itself), and a
--                 job every 5 minutes that asks the website to send clock-in
--                 reminders.
-- =============================================================================

-- ---------------------------------------------------------------- messages
create table public.chat_threads (
  id               uuid primary key default gen_random_uuid(),
  kind             text not null check (kind in ('everyone', 'direct', 'group')),
  name             text check (name is null or char_length(name) between 1 and 40),
  direct_key       text unique,              -- the two members, sorted, for one-on-one chats
  created_by       text,
  created_at       timestamptz not null default now(),
  last_message_at  timestamptz not null default now()
);
create unique index chat_threads_one_everyone on public.chat_threads (kind) where kind = 'everyone';
insert into public.chat_threads (kind, name) values ('everyone', 'Everyone');

create table public.chat_members (
  thread_id     uuid not null references public.chat_threads (id) on delete cascade,
  member        text not null check (member = 'admin' or member ~ '^[0-9a-f-]{36}$'),
  last_read_at  timestamptz not null default now(),
  primary key (thread_id, member)
);
create index on public.chat_members (member);

create table public.chat_messages (
  id           uuid primary key default gen_random_uuid(),
  thread_id    uuid not null references public.chat_threads (id) on delete cascade,
  sender       text not null,
  sender_name  text not null check (char_length(sender_name) between 1 and 40),
  body         text not null check (char_length(body) between 1 and 1000),
  created_at   timestamptz not null default now()
);
create index on public.chat_messages (thread_id, created_at desc);

-- ---------------------------------------------------------------- restocking
alter table public.settings
  add column restock_areas text[] not null default array['Fridge', 'Snacks', 'Ramen', 'Chips']
    check (cardinality(restock_areas) between 1 and 10);

create table public.restock_checks (
  id            uuid primary key default gen_random_uuid(),
  staff_id      uuid references public.staff (id) on delete set null,
  staff_name    text not null,
  shift_id      uuid references public.staff_shifts (id) on delete set null,
  token_hash    text,                        -- lets the tablet or phone add photos for a while
  areas         text[] not null,
  skipped_note  text check (skipped_note is null or char_length(skipped_note) <= 200),
  completed_at  timestamptz,
  reviewed      boolean not null default false,
  created_at    timestamptz not null default now()
);
create unique index restock_checks_one_per_shift on public.restock_checks (shift_id) where shift_id is not null;
create index on public.restock_checks (created_at desc);

create table public.restock_photos (
  id          uuid primary key default gen_random_uuid(),
  check_id    uuid not null references public.restock_checks (id) on delete cascade,
  area        text not null check (char_length(area) between 1 and 40),
  path        text not null unique,          -- inside the private "restock" bucket
  created_at  timestamptz not null default now(),
  unique (check_id, area)
);

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('restock', 'restock', false, 8388608, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;
create policy "admin manages restock photos" on storage.objects
  for all to authenticated
  using (bucket_id = 'restock' and public.is_admin())
  with check (bucket_id = 'restock' and public.is_admin());

-- ---------------------------------------------------------------- absences
create table public.staff_absences (
  id          uuid primary key default gen_random_uuid(),
  staff_id    uuid not null references public.staff (id) on delete cascade,
  work_date   date not null,
  window_id   int references public.pickup_windows (id) on delete cascade,   -- null = the whole day
  reason      text check (reason is null or char_length(reason) <= 200),
  seen        boolean not null default false,
  created_at  timestamptz not null default now()
);
create unique index staff_absences_once on public.staff_absences (staff_id, work_date, coalesce(window_id, 0));
create index on public.staff_absences (work_date);

-- ---------------------------------------------------------------- tasks
create table public.staff_tasks (
  id          uuid primary key default gen_random_uuid(),
  title       text not null check (char_length(title) between 1 and 120),
  details     text check (details is null or char_length(details) <= 300),
  task_date   date,                          -- one day only
  weekday     int check (weekday between 0 and 6),   -- every week on this day (0 = Sunday)
  staff_id    uuid references public.staff (id) on delete cascade,   -- null = everyone working
  sort        int not null default 0,
  created_at  timestamptz not null default now(),
  check (task_date is null or weekday is null)
);
create index on public.staff_tasks (task_date);

create table public.staff_task_done (
  task_id    uuid not null references public.staff_tasks (id) on delete cascade,
  work_date  date not null,
  staff_id   uuid not null references public.staff (id) on delete cascade,
  done_at    timestamptz not null default now(),
  primary key (task_id, work_date, staff_id)
);

-- ---------------------------------------------------------------- notifications
create table public.push_subscriptions (
  id          uuid primary key default gen_random_uuid(),
  member      text not null check (member = 'admin' or member ~ '^[0-9a-f-]{36}$'),
  endpoint    text not null unique check (char_length(endpoint) <= 1000),
  p256dh      text not null,
  auth        text not null,
  created_at  timestamptz not null default now()
);
create index on public.push_subscriptions (member);

create table public.staff_reminders_sent (
  staff_id   uuid not null references public.staff (id) on delete cascade,
  work_date  date not null,
  window_id  int not null,
  sent_at    timestamptz not null default now(),
  primary key (staff_id, work_date, window_id)
);

-- Keys the website makes for itself (web push keys) and the reminder job's
-- password. No policies: only the website's server can read them.
create table public.app_secrets (
  key    text primary key,
  value  text not null
);
insert into public.app_secrets (key, value) values
  ('cron_secret', replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '')),
  ('site_url', 'https://school-store-steel.vercel.app');

-- ---------------------------------------------------------------- access
alter table public.chat_threads         enable row level security;
alter table public.chat_members         enable row level security;
alter table public.chat_messages        enable row level security;
alter table public.restock_checks       enable row level security;
alter table public.restock_photos       enable row level security;
alter table public.staff_absences       enable row level security;
alter table public.staff_tasks          enable row level security;
alter table public.staff_task_done      enable row level security;
alter table public.push_subscriptions   enable row level security;
alter table public.staff_reminders_sent enable row level security;
alter table public.app_secrets          enable row level security;

create policy "admin full access" on public.chat_threads    for all to authenticated using (public.is_admin()) with check (public.is_admin());
